window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0017", [{"word":"furthermore","ipa_uk":"/ˌfɜːðəˈmɔː/","ipa_us":"/ˌfɜːrðərˈmɔːr/","definition_zh":"此外；而且；再者；进一步说","definition_en":"used to add another point to what has just been said, especially one that makes the case stronger","core_image":"已经迈出一步的脚，再沿同一方向落下另一只脚","scene":"The deadline is Friday; furthermore, no late submissions will be accepted at all.","sceneCN":"这里 furthermore 是「此外、而且」（第 1 个义项：在已说内容之外再补一条）；句意：截止时间是周五；此外，逾期提交一概不予接受。场景要点：一张标着周五的日历、一份被退回的逾期稿件，以及说话人伸出的第二根手指。","pos":[{"tag":"adv.","zh":"此外；而且；再者（句子副词，连接前后两个句子）"}],"collocations":[{"phrase":"and furthermore","zh":"而且；此外（在口语中常前接并列连词）"},{"phrase":"furthermore, it should be noted that","zh":"此外应当指出"},{"phrase":"furthermore, the evidence suggests","zh":"此外，证据表明"},{"phrase":"furthermore, this applies to","zh":"此外，这也适用于"},{"phrase":"furthermore, the cost is high","zh":"此外，成本很高"},{"phrase":"furthermore, no one objected","zh":"此外，没有人反对"}],"forms":[{"label":"副词形态","form":"furthermore（无屈折变化）"}],"derivatives":[{"word":"further","pos":"adv./adj./v.","zh":"更远地；进一步的；推进；促进"},{"word":"farther","pos":"adj./adv.","zh":"更远的；更远地（仅用于空间距离）"},{"word":"furtherance","pos":"n.","zh":"促进；推进"},{"word":"furthermost","pos":"adj.","zh":"最远的"},{"word":"furthest","pos":"adj./adv.","zh":"最远的；最远地"}],"senses":[{"no":"01","title":"Add one more point","titleCN":"再加一条：补充信息","definition":"used at the beginning of a sentence to add another point to what has just been said","definitionCN":"用在句首，为刚说过的话再补充一条内容","example":"The course is expensive; furthermore, it lasts only six weeks.","exampleCN":"这门课很贵；此外，它只持续六周。","why":"Further began as the comparative of forth, meaning 'more forward'. Furthermore places one more item in front of the listener, extending the line that the previous sentence opened.","whyCN":"further 最初是 forth（向前）的比较级，意为“更往前”。furthermore 就是把又一条内容推到听者面前，把上一句开启的那条线继续延长。"},{"no":"02","title":"Add a weightier point","titleCN":"再加一条更重的理由","definition":"used when the point being added is stronger or more persuasive than the one before it","definitionCN":"所补充的内容比前一条更有力、更有说服力时使用","example":"The plan is already behind schedule; furthermore, its budget has been cut.","exampleCN":"这个计划已经落后于进度；而且，它的预算还被削减了。","why":"The element more adds a second comparative on top of further, so the word literally says 'further still'. English uses that stacked form for a climax, which is why the later clause usually outranks the earlier one.","whyCN":"more 在 further 之上又叠了一层比较，因此这个词字面上就是“还要更往前”。英语用这种叠加形式表达递进的高潮，所以后一个分句通常比前一个更重。"},{"no":"03","title":"Chain several points","titleCN":"连缀多条：成串推进","definition":"used repeatedly in formal writing to carry a series of parallel points through one paragraph","definitionCN":"在正式写作中重复使用，把一串并列论点推进下去","example":"The plan is late; furthermore, it is over budget; furthermore, no one has approved it.","exampleCN":"这个计划已经迟了；此外，它超出预算；此外，还没有人批准它。","why":"Each furthermore is another stride on the same path. A chain of them keeps the reader moving in one direction instead of turning back.","whyCN":"每一个 furthermore 都是同一条路上的又一步。连用几个，读者就被一直推着朝同一方向走，而不会回头。"},{"no":"04","title":"Draw a further consequence","titleCN":"进一步说：推出后果","definition":"used to introduce an inference or consequence that follows from the previous statement","definitionCN":"用来引出由前一句推出的推论或后果","example":"The well is dry; furthermore, the pumps have failed.","exampleCN":"井已经干了；进一步说，水泵也坏了。","why":"The word marks distance travelled, and a consequence is simply the point the argument reaches after the first fact. The second clause stands further along the same road.","whyCN":"这个词标记的是已经走出的距离，而“后果”正是论证在第一个事实之后抵达的那一点。第二个分句站在同一条路上更远的位置。"},{"no":"05","title":"Formal documents: an added rule","titleCN":"正式文本：追加条款","definition":"in contracts, rules, and official notices, used to add a binding condition","definitionCN":"在合同、规则和正式通告中，用来追加一项有约束力的条件","example":"Payment must be made in advance; furthermore, the deposit is not refundable.","exampleCN":"必须预先付款；此外，订金不予退还。","why":"Legal drafting needs an additive connector that carries no hint of contrast. Furthermore only adds, so the second condition stands beside the first rather than against it.","whyCN":"法律起草需要一个不带转折意味的增补连接词。furthermore 只做添加，因此第二项条件与前一项并立，而不是与它对立。"},{"no":"06","title":"Academic argument: another layer of evidence","titleCN":"学术论证：再加一层证据","definition":"in essays and reports, used to stack evidence or reasons without changing the direction of the argument","definitionCN":"在论文和报告中，用来叠加证据或理由，而不改变论证方向","example":"The sample is small; furthermore, it was drawn from a single region.","exampleCN":"样本很小；此外，它只取自一个地区。","why":"Academic prose builds a case brick by brick in one direction. Furthermore lays the next brick in line, signalling that the argument is widening rather than turning.","whyCN":"学术写作沿着一个方向一块砖一块砖地垒起论证。furthermore 顺着线放下下一块砖，表示论证在加宽，而不是在转向。"},{"no":"07","title":"Spoken afterthought","titleCN":"口语中的追加：还有一点","definition":"in speech, used after a short pause to add a point the speaker has just thought of","definitionCN":"在口语中，短暂停顿之后用来补上说话人临时想到的一点","example":"I cannot make it tonight; furthermore, my car is in the shop.","exampleCN":"今晚我来不了；还有，我的车在修理厂。","why":"Even in speech the word keeps its forward motion: the speaker pauses, steps further, and sets down one more item before closing.","whyCN":"即使在口语里，这个词仍保留向前的动作：说话人停顿一下，再往前迈一步，在收尾之前又放下一件事。"},{"no":"08","title":"Register: formal, never contrastive","titleCN":"语域特征：正式，且从不表转折","definition":"belonging to formal written English and never functioning as an adjective or as a marker of contrast","definitionCN":"属于正式书面英语，从不用作形容词，也从不表示转折","example":"The results were inconclusive; furthermore, the method itself was questioned.","exampleCN":"结果没有定论；此外，方法本身也受到了质疑。","why":"Because it is built from 'further + more', the word can only point forward and add. It cannot turn back, which is why it never contrasts and never describes a noun.","whyCN":"因为它是“further + more”的合成，这个词只能向前指、只能添加。它不能回头，所以从不表转折，也从不修饰名词。"}],"etymology":{"intro":{"en":"Furthermore is a transparent English compound of two native words, yet the history inside 'further' is disputed between two readings. Dates are approximate.","cn":"furthermore 是两个本族词组成的透明合成词，但“further”内部的来历存在两种说法。年代为大致估计。"},"items":[{"era":"C. 1200","en":"First recorded as further + more, with the sense 'in addition, moreover'. Middle English also had a twin, farthermore, which did not survive.","cn":"约 1200 年首次记录为 further 加 more 的组合，意为“此外、而且”。中古英语还有一个孪生形式 farthermore，后来没有留存下来。"},{"era":"OLD ENGLISH","en":"Further comes from Old English furðor, forðor, 'to a more advanced position, forward, onward, beyond; later; to a greater degree'.","cn":"further 来自古英语 furðor、forðor，意为“到更靠前的位置、向前、更远；后来；到更大的程度”。"},{"era":"TWO READINGS","en":"One reading takes further as 'forth-er': furðum (see forth) plus the comparative suffix -eron- / -uron-, as in inner and outer. The other reading (Watkins) traces it to Proto-Germanic *furthera-, from PIE *pr-tero-, 'forward' plus a comparative suffix also seen in after and other. The two are not reconciled.","cn":"一种说法把 further 解作“forth 的比较级”：furðum（见 forth）加比较级后缀 -eron-／-uron-，如同 inner 与 outer。另一种说法（Watkins）把它追溯到原始日耳曼语 *furthera-，来自原始印欧语 *pr-tero-，即“向前”加一个也见于 after、other 的比较级后缀。两说尚未调和。"},{"era":"MIDDLE ENGLISH","en":"Furthermore and farthermore coexisted; English kept the first and dropped the second. Furthermost also survives, built with -most.","cn":"furthermore 与 farthermore 曾经并存；英语保留了前者，淘汰了后者。由 -most 构成的 furthermost 也保留至今。"},{"era":"MODERN ENGLISH","en":"The compound settled into formal written English as a sentence adverb. Further remains an adverb, adjective and verb, while its cousin farther is now limited to physical distance.","cn":"这个合成词在正式书面英语中固定为句子副词。further 仍可作副词、形容词和动词，而它的表亲 farther 现在只用于物理距离。"},{"era":"RECONSTRUCTED ROOT","en":"PIE *per- 'forward' and *pr-tero- are reconstructions, not attested words; the claim that further contains them is an etymology, not a recorded fact.","cn":"原始印欧语 *per-“向前”与 *pr-tero- 都是重构形式，并非有文献记录的词；说 further 含有它们，是一种词源解释，而不是既成事实。"}]},"similar":{"note":{"en":"The first group is built on the same 'forward' stem; the second compares the additive connectors that learners most often confuse.","cn":"第一组建立在同一个“向前”的词干上；第二组比较学习者最容易混淆的几个增补连接词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"further","ipa":"/ˈfɜːðə/","tag":"same stem, adv./adj./v.","definition":"at or to a greater distance or degree, or additional. It can modify a noun ('further details') and act as a verb ('further a cause'), which furthermore cannot do.","definitionCN":"在更大距离或程度上，或“进一步的”。它可以修饰名词（如 further details），也可以作动词（如 further a cause），而 furthermore 都不能。"},{"word":"farther","ipa":"/ˈfɑːðə/","tag":"distance only","definition":"at or to a greater physical distance. It is the comparative of far in space and does not carry the sense 'additional'.","definitionCN":"在更远的物理距离上。它是 far 在空间意义上的比较级，不含“额外的”这一层意思。"},{"word":"furthermost","ipa":"/ˈfɜːðəməʊst/","tag":"superlative compound","definition":"the most distant. It adds -most to further and is an adjective of place, not a connector.","definitionCN":"最远的。它在 further 后加 -most，是表示位置的形容词，不是连接词。"},{"word":"furtherance","ipa":"/ˈfɜːðərəns/","tag":"derived noun","definition":"the act of helping something to progress. It is a noun from the verb further, not a variant of furthermore.","definitionCN":"促进、推进的行为。它是动词 further 派生的名词，不是 furthermore 的变体。"}]},{"heading":"NEAR MEANING","entries":[{"word":"moreover","ipa":"/mɔːrˈəʊvə/","tag":"additive, formal","definition":"used to add a point, often a stronger one. It is close to furthermore, slightly more formal and more common in argumentative prose.","definitionCN":"用来补充一点，常常是更有力的一点。它与 furthermore 接近，略更正式，在议论性文章中更常见。"},{"word":"besides","ipa":"/bɪˈsaɪdz/","tag":"additive, conversational","definition":"used to add a point, often as an afterthought; it can also mean 'apart from'. It is far more conversational than furthermore.","definitionCN":"用来补上一点，常带临时想起的意味；也可表示“除……之外”。它比 furthermore 口语化得多。"},{"word":"in addition","ipa":"/ɪn əˈdɪʃn/","tag":"plain additive phrase","definition":"a neutral additive phrase that can stand at the front, middle or end of a sentence, while furthermore is mostly sentence-initial.","definitionCN":"中性的增补短语，可放在句首、句中或句末，而 furthermore 基本只出现在句首。"},{"word":"what is more","ipa":"/wɒt ɪz ˈmɔː/","tag":"climactic, spoken","definition":"used to introduce a stronger added point. It is more emphatic and more spoken than furthermore.","definitionCN":"用来引出更有力的一点。它比 furthermore 更强调，也更口语化。"}]}]},"mnemonics":{"normalIntro":{"en":"Real word parts and real relatives: further as the comparative of forth, plus more, plus the Middle English twin farthermore.","cn":"只用真实构词成分与真实同族词：作为 forth 比较级的 further，加上 more，以及中古英语的孪生形式 farthermore。"},"normal":[{"en":"Further is the comparative of forth, 'more forward'. Furthermore is one more step forward on the same path.","cn":"further 是 forth（向前）的比较级，意为“更往前”。furthermore 就是在同一条路上再往前一步。"},{"en":"More adds a second comparative, so the word literally says 'further still'. That is why the second point often outranks the first.","cn":"more 又叠了一层比较，所以这个词字面上就是“还要更往前”。正因如此，第二点往往比第一点更重。"},{"en":"Middle English also had farthermore; English kept furthermore and dropped the twin.","cn":"中古英语还有 farthermore；英语留下了 furthermore，淘汰了那个孪生形式。"},{"en":"Because it can only move forward, furthermore can add but can never contrast: no 'but' hides inside it.","cn":"因为它只能向前，furthermore 只能添加，永远不能转折：它里面藏着一个“但是”是说不通的。"},{"en":"In contracts and essays it works as a signpost: another rule or another piece of evidence is coming, in the same direction.","cn":"在合同和论文里，它是一块路标：还有一条规则或一层证据要来，而且方向不变。"}],"abstract":[{"en":"Picture a walker on a straight road. The first sentence is one footprint; furthermore is the next footprint, placed ahead, not behind.","cn":"想象一个人走在直路上。第一句是一个脚印；furthermore 是下一个脚印，落在前方，而不是后方。"},{"en":"A chain of footprints is a paragraph: every furthermore keeps the direction and adds distance.","cn":"一串脚印就是一段话：每一个 furthermore 都保持方向，并增加距离。"},{"en":"The word is a one-way sign: it points forward, so it can never be used to turn an argument around.","cn":"这个词是一块单向路标：它只指向前方，因此永远不能用来把论证掉头。"}]},"examples":[{"en":"The application is incomplete; furthermore, it arrived after the deadline.","cn":"这份申请不完整；此外，它还是在截止日期之后才到的。"},{"en":"The new engine is quieter; furthermore, it uses less fuel.","cn":"新发动机更安静；而且，它更省油。"},{"en":"The report notes a rise in temperature; furthermore, it links the rise to emissions.","cn":"报告指出气温上升；进一步说，它把这一上升与排放联系了起来。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“佛则摩”——佛则先走一步，摩再添一句 → furthermore 此外、而且（只借音，不表词源）","word":"furthermore"},"root":"由 further“更往前”加 more“更多”合成，核心是“沿着同一方向再往前加一层”。","sensesIntro":{"en":"Eight senses of furthermore, all built on one motion: a foot that has already stepped forward takes one more step in the same direction.","cn":"furthermore 的八个义项都建立在同一个动作上：已经迈出一步的脚，沿同一方向再走一步。"},"semanticMap":{"core":{"en":"CORE IMAGE: a second step taken in the same direction as the first.","cn":"核心意象：沿着与第一步相同的方向再迈出第二步。"},"chain":["ONE POINT MADE","STEP FURTHER","ADD ANOTHER","ADD A STRONGER ONE","KEEP THE SAME DIRECTION","FORMAL, NEVER CONTRASTING"],"branches":[{"senses":"01","en":"ADDITION: the next item is placed in front of the listener, extending the line already begun.","cn":"添加：下一条内容被推到听者面前，延续已经开始的线。"},{"senses":"02","en":"CLIMAX: more stacks a second comparative on further, so the added point is stronger.","cn":"递进高潮：more 在 further 上再叠一层比较，所以补上的那点更有力。"},{"senses":"03 · 04","en":"SEQUENCE: a chain of steps carries several parallel points, or carries the argument to its consequence.","cn":"序列：一串步伐既能把多个并列论点推下去，也能把论证推到它的后果。"},{"senses":"05 · 06","en":"FORMAL PROSE: contracts and essays use the step to add rules or evidence without turning.","cn":"正式文本：合同与论文用这一步追加条款或证据，而不转向。"},{"senses":"07 · 08","en":"SPEECH AND REGISTER: even an afterthought moves forward, and the word never becomes an adjective or a contrast marker.","cn":"口语与语域：即使临时想起的补充也向前走；这个词从不作形容词，也从不表转折。"}]},"affixes":{"intro":{"en":"Furthermore is an English compound of two native words, not a Latin derivative. Its only affix-like element is the comparative ending inside further.","cn":"furthermore 是两个本族词构成的英语合成词，不是拉丁派生词。它唯一像词缀的成分，是 further 内部的比较级词尾。"},"latinIntro":{"en":"There is no Latin source here. Further belongs to the Germanic stock, and even its deeper origin is disputed between a 'forth' reading and a Proto-Indo-European *per- reading.","cn":"这里没有拉丁语来源。further 属于日耳曼语词库，连它更深的来历都存在“forth 说”与原始印欧语 *per- 说两种分歧。"},"items":[{"word":"furthermore","structure":"further + more (compound adverb)","meaning":"in addition; moreover","meaningCN":"此外；而且（合成副词）","example":"The room is small; furthermore, it has no window.","exampleCN":"房间很小；此外，它没有窗户。"},{"word":"further","structure":"furðor + comparative suffix -er","meaning":"more forward; additional","meaningCN":"更往前；进一步的（比较级形式）","example":"We need further evidence before deciding.","exampleCN":"在作决定之前，我们需要更多证据。"},{"word":"furtherance","structure":"further + -ance (noun of action)","meaning":"the act of promoting or helping something forward","meaningCN":"促进；推进（-ance 构成行为名词）","example":"The grant was used for the furtherance of research.","exampleCN":"这笔拨款用于推进研究。"},{"word":"furthermost","structure":"further + -most (superlative)","meaning":"most distant","meaningCN":"最远的（-most 构成最高级）","example":"They reached the furthermost point of the trail.","exampleCN":"他们到达了小径的最远端。"},{"word":"furthest","structure":"further + -est (superlative)","meaning":"to the greatest distance or degree","meaningCN":"最远地；最大程度上（-est 构成最高级）","example":"Of the three villages, this one lies furthest from the road.","exampleCN":"三个村庄中，这一个离公路最远。"},{"word":"farther","structure":"far + -ther (comparative)","meaning":"at a greater physical distance","meaningCN":"更远的（far 的比较级，只用于空间距离）","example":"The station is farther than it looks on the map.","exampleCN":"车站比地图上看起来更远。"},{"word":"far","structure":"Old English feor","meaning":"at a great distance","meaningCN":"远的；远地","example":"The lighthouse can be seen from far away.","exampleCN":"那座灯塔从很远的地方就能看见。"},{"word":"forth","structure":"Old English forð","meaning":"forward, onward, out","meaningCN":"向前；向外","example":"From that day forth, the rule was never broken.","exampleCN":"从那天起，这条规则再未被违反。"},{"word":"moreover","structure":"more + over (parallel compound)","meaning":"besides; in addition","meaningCN":"此外；而且（与 furthermore 同型的合成词）","example":"The plan is costly; moreover, it is risky.","exampleCN":"这个计划代价高昂；此外，它还有风险。"}],"latinEntries":[]}},{"word":"generate","ipa_uk":"/ˈdʒenəreɪt/","ipa_us":"/ˈdʒenəreɪt/","definition_zh":"产生；生成；引起；发电；生育","definition_en":"to bring something into existence, whether offspring, energy, a result, or a piece of content","core_image":"种子裂开，第一寸芽把原本不存在的东西带到眼前","scene":"The rooftop panels generate enough electricity to run the school's lights.","sceneCN":"这里 generate 是「发电、产生电力」（第 8 个义项：用装置把其他形式的能量转成电）；句意：屋顶的光伏板产生的电力足以供学校的照明使用。场景要点：一排屋顶光伏板、配电箱上的读数，以及亮起的教室灯。","pos":[{"tag":"vt.","zh":"产生；生成（能量、数据、收益、情绪）"},{"tag":"vt.","zh":"生育；繁殖（较正式的旧义）"}],"collocations":[{"phrase":"generate electricity","zh":"发电；产生电力"},{"phrase":"generate revenue","zh":"创造收益"},{"phrase":"generate interest","zh":"引起兴趣"},{"phrase":"generate data","zh":"生成数据"},{"phrase":"generate jobs","zh":"创造就业岗位"},{"phrase":"generate a response","zh":"产生回应"},{"phrase":"generate heat","zh":"产生热量"}],"forms":[{"label":"三单（he/she/it）","form":"generates"},{"label":"过去式（已经发生）","form":"generated"},{"label":"过去分词（完成／被动）","form":"generated"},{"label":"现在分词（进行体）","form":"generating"}],"derivatives":[{"word":"generation","pos":"n.","zh":"产生；生成；一代人；发电"},{"word":"generator","pos":"n.","zh":"发电机；生成器；产生者"},{"word":"generative","pos":"adj.","zh":"生成的；有生产能力的"},{"word":"generational","pos":"adj.","zh":"代际的；世代的"},{"word":"regenerate","pos":"v.","zh":"再生；使恢复"},{"word":"regeneration","pos":"n.","zh":"再生；重建"}],"senses":[{"no":"01","title":"Beget: produce offspring","titleCN":"生育：产下后代","definition":"to produce offspring; the oldest recorded sense of the verb","definitionCN":"产下后代；这是该动词最早有记录的义项","example":"These animals generate young once a year.","exampleCN":"这些动物每年生育一次幼崽。","why":"The Latin verb generare meant 'to bring forth, beget', from genus 'race, kind'. The first thing it brings forth is a new member of the same kind.","whyCN":"拉丁语 generare 意为“生出、繁衍”，来自 genus“种族、种类”。它最先带出来的，是同一类中的新成员。"},{"no":"02","title":"Send out heat, light, or sound","titleCN":"发出热、光、声","definition":"of a natural source or device, to produce heat, light, sound, or another physical effect","definitionCN":"指自然源头或装置产生热、光、声等物理效应","example":"The reactor generates heat even after shutdown.","exampleCN":"反应堆在停堆之后仍会产生热量。","why":"From the 1560s the verb was applied to natural forces: what a source brings forth is no longer a child but an effect that leaves the source.","whyCN":"从 16 世纪 60 年代起，这个词被用于自然力：源头带出的不再是孩子，而是离开源头向外扩散的效果。"},{"no":"03","title":"Arouse a feeling or reaction","titleCN":"引起情绪或反应","definition":"to cause a feeling, reaction, or discussion to arise in people","definitionCN":"使人产生某种情绪、反应或讨论","example":"The proposal generated a heated debate in the council.","exampleCN":"这项提案在议会中引发了激烈辩论。","why":"A feeling is brought forth inside people rather than outside them, so the same 'bringing forth' is relocated into the mind.","whyCN":"情绪是在人的内部被带出来的，而不是在外部，于是同一个“生出”被移到了心里。"},{"no":"04","title":"Create economic output","titleCN":"创造经济产出","definition":"to produce revenue, profit, jobs, or growth as a result of activity","definitionCN":"通过活动产生收益、利润、就业或增长","example":"Tourism generates millions of dollars for the region each year.","exampleCN":"旅游业每年为该地区带来数百万美元的收入。","why":"An economy is treated as a field that yields a crop: activity is the seed and revenue is what comes up.","whyCN":"经济被看成像田地一样会长出庄稼：活动是种子，收益是长出来的东西。"},{"no":"05","title":"Computing: produce data, text, or images","titleCN":"计算机：生成数据、文本、图像","definition":"of software or a model, to produce data, text, images, or code according to rules or instructions","definitionCN":"指软件或模型按规则或指令产出数据、文本、图像或代码","example":"The program generates a report from the raw figures every night.","exampleCN":"这个程序每晚根据原始数字生成一份报告。","why":"This is the modern mechanical version: a rule or model plays the role of the seed, and the output is brought forth on demand.","whyCN":"这是现代的机械版本：规则或模型扮演种子的角色，输出则按要求被带出来。"},{"no":"06","title":"Linguistics: generate sentences","titleCN":"语言学：生成句子","definition":"in generative grammar, to produce an infinite set of sentences from a finite set of rules","definitionCN":"在生成语法中，从有限的规则集合产出无限的句子","example":"A grammar must be able to generate every grammatical sentence of the language.","exampleCN":"一部语法必须能够生成该语言中每一个合乎语法的句子。","why":"The mind acts as the source: from a small store of rules it brings forth sentences that were never heard before.","whyCN":"这里头脑成了源头：从少量规则中带出从未听过的句子。"},{"no":"07","title":"Mathematics: generate a sequence","titleCN":"数学：生成数列或图形","definition":"to produce a sequence, curve, or set by applying a rule repeatedly","definitionCN":"通过反复运用同一条规则产出一个数列、曲线或集合","example":"The formula generates a sequence of prime numbers.","exampleCN":"这个公式生成一个质数数列。","why":"A rule takes the place of the parent: each term is brought forth from the one before, in the same line of descent.","whyCN":"规则取代了亲代：每一项都由前一项生出，处在同一条传承线上。"},{"no":"08","title":"Engineering: generate power","titleCN":"工程：发电","definition":"to convert another form of energy into electricity in a machine","definitionCN":"用机器把其他形式的能量转换成电力","example":"The dam generates power for three provinces.","exampleCN":"这座大坝为三个省发电。","why":"This is the most industrialised branch: a generator is literally 'the thing that brings forth', and what it brings forth is current.","whyCN":"这是最工业化的一支：generator 字面上就是“带出东西的装置”，而它带出的是电流。"},{"no":"09","title":"Create an atmosphere or culture","titleCN":"造出气氛或风气","definition":"to cause an abstract social condition, such as trust, excitement, or a culture, to come into being","definitionCN":"使信任、热情或某种文化等抽象社会状况得以形成","example":"The open studio generated a culture of collaboration.","exampleCN":"这间开放式工作室造就了一种协作的文化。","why":"The offspring here is intangible: a way of working is brought into existence and then lives on in the group.","whyCN":"这里生出的后代是无形的：一种工作方式被带出来，随后在群体中延续。"}],"etymology":{"intro":{"en":"Generate is a Latin verb that entered English around 1500; its stem carries the idea of 'kind, race', and every sense keeps the shape of a source bringing something forth.","cn":"generate 是约 1500 年进入英语的拉丁动词；它的词干带有“种类、族类”的意思，所有义项都保留着“源头带出某物”的形状。"},"items":[{"era":"C. 1500","en":"First recorded in English meaning 'to beget' (offspring).","cn":"英语中最早记录于约 1500 年，意为“生育（后代）”。"},{"era":"DOUBLE SOURCE","en":"It is either a back-formation from generation or a direct borrowing of Latin generatus, the past participle of generare. The two routes cannot be fully separated, so the immediate source is source uncertain.","cn":"它要么是从 generation 逆构而成的动词，要么直接借用了 generare 的过去分词 generatus。两条路径无法完全分开，因此直接来源属于存疑。"},{"era":"1560S","en":"The verb extends to natural forces, conditions and substances: heat, light, steam, and later electricity can be generated.","cn":"该动词扩展到自然力、状况与物质：热、光、蒸汽，后来还有电，都可以被“产生”。"},{"era":"LATIN","en":"Latin generare 'to bring forth, beget, produce' is built on genus, generis 'race, stock, kind'.","cn":"拉丁语 generare“生出、繁衍、产生”建立在 genus、generis“种族、血统、种类”之上。"},{"era":"PROTO-INDO-EUROPEAN","en":"The reconstructed root *gene- 'give birth, beget' also underlies genus, gene, kin, kind, native, nation, nature and pregnant. Reconstructed roots are not attested words.","cn":"重构词根 *gene-“生育、繁衍”也是 genus、gene、kin、kind、native、nation、nature、pregnant 的来源。重构词根并非有文献记录的词。"},{"era":"MODERN ENGLISH","en":"Generator and generation supply the technical senses; generative in linguistics is attested by 1959; machine text generation later extends the computing branch.","cn":"generator 与 generation 提供技术义；generative 在语言学中的用法于 1959 年有记录；机器文本生成后来又扩展了计算机这一支。"}]},"similar":{"note":{"en":"The first group separates the members of the gener- family; the second compares verbs that all mean 'bring something into being'.","cn":"第一组区分 gener- 词族的成员；第二组比较几个都表示“使某物出现”的动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"generation","ipa":"/ˌdʒenəˈreɪʃn/","tag":"same verb, noun","definition":"the act of producing, a cohort born at the same time, or a stage in a family line. It is the noun of generate, not a synonym of the verb.","definitionCN":"产生的行为、同期出生的一代人，或家族中的一辈。它是 generate 的名词，不是这个动词的同义词。"},{"word":"generator","ipa":"/ˈdʒenəreɪtə/","tag":"agent noun","definition":"a machine that produces electricity, or a person or thing that produces something. The -or suffix names the agent.","definitionCN":"发电机，或产生某物的人或物。-or 后缀命名的是施动者。"},{"word":"generative","ipa":"/ˈdʒenərətɪv/","tag":"adjective of capacity","definition":"able to produce or to produce new output, especially in linguistics. It names a capacity, while generate names the act.","definitionCN":"有生产能力或能产出新内容的，尤用于语言学。它命名的是能力，而 generate 命名的是动作。"},{"word":"general","ipa":"/ˈdʒenrəl/","tag":"same root, different branch","definition":"concerning the whole kind or class. It shares the Latin genus but has no sense of producing anything.","definitionCN":"涉及整个种类或类别的。它与拉丁语 genus 同源，但完全没有“生产”的意思。"}]},{"heading":"NEAR MEANING","entries":[{"word":"produce","ipa":"/prəˈdjuːs/","tag":"regular output","definition":"to make or bring forth, often in large quantities and as a regular process. Generate stresses the source or mechanism rather than the quantity.","definitionCN":"制造或产出，常指大批量、常规性的生产。generate 更强调源头或机制，而不是数量。"},{"word":"create","ipa":"/kriˈeɪt/","tag":"newness and design","definition":"to bring something new into existence, often by imagination or design. Generate is more about a process that yields output than about originality.","definitionCN":"使新事物出现，常靠想象或设计。generate 更强调产出结果的过程，而不是原创性。"},{"word":"yield","ipa":"/jiːld/","tag":"return from land or investment","definition":"to produce a result, crop, or profit, especially from land or an investment. It stresses the return obtained, not the act of bringing forth.","definitionCN":"产出结果、收成或利润，尤指来自土地或投资。它强调所得到的回报，而不是“生出”的动作。"},{"word":"engender","ipa":"/ɪnˈdʒendə/","tag":"abstract, literary","definition":"to cause a feeling or situation to develop. It is literary and limited to abstract results, while generate is wider and also covers physical output.","definitionCN":"使某种情绪或局面发展起来。它偏文学，且只用于抽象结果，而 generate 范围更广，也涵盖实体产出。"}]}]},"mnemonics":{"normalIntro":{"en":"Real word parts and real relatives: Latin genus 'kind', the Latin verb generare, and the everyday family generation / generator / generative.","cn":"只用真实构词成分与真实同族词：拉丁语 genus“种类”、动词 generare，以及日常词族 generation／generator／generative。"},"normal":[{"en":"Latin genus means 'race, kind'. To generate is to bring forth a new member of the kind.","cn":"拉丁语 genus 意为“种族、种类”。generate 就是生出这一种类的新成员。"},{"en":"Generation is the noun, generator is the machine, generative is the capacity: three branches of one verb.","cn":"generation 是名词，generator 是机器，generative 是能力：同一个动词的三条分支。"},{"en":"A grammar generates sentences: finite rules, infinite output.","cn":"语法生成句子：有限的规则，无限的输出。"},{"en":"A model generates text the way a rule generates a sequence: input plus rule, output on demand.","cn":"模型生成文本，就像规则生成数列：输入加规则，按需给出输出。"},{"en":"The 1560s extension to natural forces is why we say a heater generates heat, not that it gives birth to heat.","cn":"16 世纪 60 年代向自然力的扩展，正是我们说取暖器“产生热量”、而不说它“生下热量”的原因。"}],"abstract":[{"en":"Picture a seed splitting: the first green tip is something that did not exist a moment ago.","cn":"想象一粒种子裂开：那第一截绿芽，是片刻之前还不存在的东西。"},{"en":"Sometimes the seed is a rule, sometimes a machine, sometimes a group of people; whatever the source, the output is brought forth.","cn":"有时种子是一条规则，有时是一台机器，有时是一群人；不论源头是什么，输出都被带了出来。"},{"en":"Generate always keeps a direction: from source to output, never the reverse.","cn":"generate 始终保留一个方向：从源头到产出，从不反过来。"}]},"examples":[{"en":"The new factory will generate about two hundred jobs in the region.","cn":"这家新工厂将为该地区创造约两百个就业岗位。"},{"en":"Her joke generated more laughter than the rest of the speech.","cn":"她那个笑话引起的笑声比整场演讲其余部分都多。"},{"en":"The model can generate a short story from a single sentence.","cn":"这个模型能根据一句话生成一篇短篇故事。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“杰诺雷特”——杰诺一按开关，雷特就来了电 → generate 产生、发电（只借音，不表词源）","word":"generate"},"root":"源自拉丁语 generare“生出、繁衍”，词根为 genus“种族、种类”，核心是“由某个源头带出新的个体或结果”。","sensesIntro":{"en":"Nine senses of generate, all built on one movement: a source brings something out of itself, and that something did not exist before.","cn":"generate 的九个义项都建立在同一个运动上：某个源头从自身带出某物，而该物此前并不存在。"},"semanticMap":{"core":{"en":"CORE IMAGE: a source brings forth something new from itself.","cn":"核心意象：源头从自身带出新的东西。"},"chain":["A SOURCE","SOMETHING HELD INSIDE","BROUGHT FORTH","IT EXISTS ON ITS OWN","IT CAN BE REPEATED","OUTPUT WITHOUT END"],"branches":[{"senses":"01","en":"LIFE: offspring are the first thing the verb brings forth.","cn":"生命：后代是这个动词最先带出来的东西。"},{"senses":"02 · 08","en":"PHYSICAL OUTPUT: heat, light and electricity leave the source and travel outward.","cn":"物理产出：热、光与电离开源头，向外传播。"},{"senses":"03 · 09","en":"STATES AND CLIMATES: feelings and cultures are brought into being inside people or groups.","cn":"状态与风气：情绪和文化在人的心里或群体内部被带出来。"},{"senses":"04","en":"ECONOMY: activity is the seed and revenue is the crop.","cn":"经济：活动是种子，收益是庄稼。"},{"senses":"05 · 06 · 07","en":"RULES: software, grammar and mathematics generate by applying a rule repeatedly.","cn":"规则：软件、语法与数学都靠反复运用同一条规则来生成。"}]},"affixes":{"intro":{"en":"Generate is a Latin verb borrowed into English. Its stem gener- carries 'kind, race', and English adds -ate, -ion, -or, -ive, plus prefixes such as re- and de-.","cn":"generate 是借入英语的拉丁动词。它的词干 gener- 带有“种类、族类”的意思，英语在其后加 -ate、-ion、-or、-ive，并在前面加 re-、de- 等前缀。"},"latinIntro":{"en":"Latin generare 'to bring forth' is built on genus, generis 'race, kind'. The same stem yields generatio, generatus and generativus, which English renders as generation, generative and the rest of the family.","cn":"拉丁语 generare“生出”建立在 genus、generis“种族、种类”上。同一词干给出 generatio、generatus、generativus，英语把它们对应为 generation、generative 以及这一词族的其余成员。"},"items":[{"word":"generation","structure":"generat- + -ion (action or result noun)","meaning":"the act of producing; a cohort; a stage in a family line","meaningCN":"产生；一代人；家族中的一辈（-ion 构成行为或结果名词）","example":"The generation of electricity from sunlight is now cheaper.","exampleCN":"利用阳光发电如今更便宜了。"},{"word":"generator","structure":"generat- + -or (agent noun)","meaning":"a machine or person that produces something","meaningCN":"发电机；生成器；产生者（-or 表示施动者）","example":"The backup generator started within seconds.","exampleCN":"备用发电机在几秒内启动了。"},{"word":"generative","structure":"generat- + -ive (adjective)","meaning":"having the power to produce or create","meaningCN":"有生成能力的（-ive 构成形容词）","example":"The course introduces generative grammar.","exampleCN":"这门课介绍生成语法。"},{"word":"generational","structure":"generation + -al (relational adjective)","meaning":"relating to generations or to differences between them","meaningCN":"代际的；与世代有关的（-al 构成关系形容词）","example":"The debate is really about generational change.","exampleCN":"这场辩论实际上是关于代际更替的。"},{"word":"regenerate","structure":"re- (again) + generate","meaning":"to produce again; to restore","meaningCN":"再生；使恢复（re- 表示“再次”）","example":"The forest can regenerate after a fire.","exampleCN":"森林在火灾之后能够再生。"},{"word":"regeneration","structure":"re- + generation","meaning":"the process of being produced again","meaningCN":"再生；重建（re- 加名词后缀）","example":"The project aims at the regeneration of the old harbour.","exampleCN":"这个项目旨在重建旧港区。"},{"word":"degenerate","structure":"de- (down, away) + generate","meaning":"to fall away from the original kind or quality","meaningCN":"退化；堕落（de- 表示“离开、下降”）","example":"The debate degenerated into shouting.","exampleCN":"辩论退化成了一场吼叫。"},{"word":"engender","structure":"en- (in) + Latin generare, through Old French","meaning":"to cause a feeling or situation to arise","meaningCN":"引起；产生（情绪或局面）","example":"Trust engenders cooperation.","exampleCN":"信任会带来合作。"},{"word":"generable","structure":"gener- + -able (able to be)","meaning":"capable of being produced","meaningCN":"可生成的；能被产生的（-able 表示“能够被”）","example":"Only a generable class of objects can be listed by rule.","exampleCN":"只有可生成的一类对象才能按规则列出。"},{"word":"generate","structure":"gener- + -ate (verb)","meaning":"to bring forth, produce","meaningCN":"产生；生成（-ate 构成动词）","example":"The plant generates power for the town.","exampleCN":"这座电厂为小镇发电。"}],"latinEntries":[{"word":"generare","structure":"gener- + -are (infinitive)","meaning":"to bring forth, beget, produce","meaningCN":"生出；繁衍；产生"},{"word":"generatio","structure":"generare + -io (action noun)","meaning":"a generating; a race or generation","meaningCN":"生成；生育；一代人"},{"word":"generatus","structure":"past participle of generare","meaning":"brought forth, produced","meaningCN":"被生出；被产生"},{"word":"genus","structure":"PIE *gene- 'give birth, beget'","meaning":"race, stock, kind","meaningCN":"种族；血统；种类"}]}},{"word":"generation","ipa_uk":"/ˌdʒenəˈreɪʃn/","ipa_us":"/ˌdʒenəˈreɪʃn/","definition_zh":"一代人；世代；辈分；产生；发电；生成","definition_en":"a group of people born around the same time, a stage in a family line, or the act of producing something such as power or data","core_image":"同一段时间里长出的一圈年轮，一圈接着一圈向外扩开","scene":"Wind generation now covers a third of the country's electricity demand.","sceneCN":"这里 generation 是「发电、电力生产」（第 5 个义项：把其他形式的能量转成电力）；句意：风力发电现已满足全国三分之一的用电需求。场景要点：转动的风机、并入电网的输电塔、显示三分之一比例的仪表盘。","pos":[{"tag":"n.","zh":"一代人；同代人；世代；辈分"},{"tag":"n.","zh":"产生；生成；（电力）生产"}],"collocations":[{"phrase":"generation gap","zh":"代沟"},{"phrase":"the younger generation","zh":"年轻一代"},{"phrase":"from generation to generation","zh":"世代相传"},{"phrase":"power generation","zh":"发电"},{"phrase":"first-generation","zh":"第一代（移民或产品）"},{"phrase":"a new generation of","zh":"新一代的……"},{"phrase":"Generation X","zh":"X 世代"}],"forms":[{"label":"复数","form":"generations"}],"derivatives":[{"word":"generational","pos":"adj.","zh":"代际的；世代的"},{"word":"intergenerational","pos":"adj.","zh":"代与代之间的"},{"word":"multigenerational","pos":"adj.","zh":"多代同堂的；跨越多代的"},{"word":"generationally","pos":"adv.","zh":"在代际层面上"},{"word":"generate","pos":"v.","zh":"产生；生成；发电"},{"word":"generator","pos":"n.","zh":"发电机；生成器"}],"senses":[{"no":"01","title":"A cohort born around the same time","titleCN":"同代人：同一时期出生的一群人","definition":"all the people born within a particular period, considered as one body","definitionCN":"在某一时期内出生的所有人，被视为一个整体","example":"The older generation remembers the blackout years.","exampleCN":"老一辈人还记得那些停电的年份。","why":"Latin generatio is a noun of action from generare 'to bring forth'. A generation is first what a period brings forth: the body of people born inside it.","whyCN":"拉丁语 generatio 是动词 generare“生出”的行为名词。generation 最初指一个时期“带出来”的东西：在这段时期内出生的一群人。"},{"no":"02","title":"A stage in a family line","titleCN":"辈分：家族传承中的一代","definition":"one level in a line of descent, counted from parent to child","definitionCN":"血缘传承中的一级，从父母到子女计作一辈","example":"The house has been in the family for five generations.","exampleCN":"这栋房子在这个家族中已经传了五代。","why":"The image turns vertical: instead of a horizontal slice of time, the word counts steps in a line of descent, each one brought forth by the one before.","whyCN":"这个意象转为纵向：它不再切一段横向的时间，而是数一条传承线上的台阶，每一级都由前一级生出。"},{"no":"03","title":"The act of procreating","titleCN":"生育、繁殖的行为","definition":"the act or process of producing offspring","definitionCN":"产下后代的行为或过程","example":"Biologists separate generation from growth: one is reproduction, the other an increase in size.","exampleCN":"生物学家把生育与生长分开：前者是繁殖，后者是体积增大。","why":"This is the oldest abstract sense: the act itself rather than its result. To generate is to beget, and generation names that begetting.","whyCN":"这是最古老的抽象义：指行为本身，而不是其结果。generate 是“生出”，而 generation 命名这个“生出”的过程。"},{"no":"04","title":"A span of about thirty years","titleCN":"一代的时间跨度","definition":"the period of time typically occupied by one cohort, conventionally about thirty years","definitionCN":"一代人通常占据的时间，习惯上约为三十年","example":"Attitudes to work can shift within a single generation.","exampleCN":"对工作的态度可能在一代人的时间内发生转变。","why":"Since a cohort occupies a stretch of time, the word comes to mean that stretch itself. The thirty-year figure is conventional, not a natural constant.","whyCN":"既然一代人占据一段时间，这个词也就用来指那段时间本身。三十年只是习惯说法，并非自然界的常数。"},{"no":"05","title":"Production of electric power","titleCN":"发电","definition":"the production of electricity from other forms of energy","definitionCN":"把其他形式的能量转化为电力","example":"Wind generation now covers a third of demand.","exampleCN":"风力发电现已满足三分之一的需求。","why":"Here what is brought forth is current: turbines turn and the grid receives power, the industrial version of 'bringing forth'.","whyCN":"这里被带出来的是电流：风机转动，电网得到电力，这是“生出”的工业版本。"},{"no":"06","title":"Production or creation in general","titleCN":"产生、生成（泛指）","definition":"the act of producing something, such as ideas, records, heat, or income","definitionCN":"产出某物的行为，例如想法、记录、热量或收入","example":"The generation of new ideas requires unscheduled time.","exampleCN":"新想法的产生需要不被安排的时间。","why":"The object brought forth can be almost anything, so the noun widens into a general word for production.","whyCN":"被带出的对象几乎可以是任何东西，于是这个名词扩展成泛指“生产、产生”的词。"},{"no":"07","title":"A new round of a product","titleCN":"新一代产品","definition":"one release in a series of products or technologies that succeed one another","definitionCN":"在一系列相继推出的产品或技术中的一轮","example":"The company unveiled a new generation of solar panels.","exampleCN":"这家公司推出了新一代太阳能板。","why":"Products are now treated as lineages: each model is brought forth from the previous one, so a release becomes a generation.","whyCN":"产品现在被当作谱系：每一款都由前一款生出，于是每一次发布都成了“一代”。"},{"no":"08","title":"The gap between cohorts","titleCN":"代沟：两代人之间的落差","definition":"in the fixed phrase generation gap, the difference in values or habits between two cohorts","definitionCN":"在固定搭配 generation gap 中，指两代人在观念或习惯上的差异","example":"The generation gap showed in how they used the same phone.","exampleCN":"代沟体现在他们使用同一部手机的方式上。","why":"When two cohorts are compared, the distance between them becomes visible; the fixed phrase names that distance.","whyCN":"当两代人被放在一起比较时，他们之间的距离就显现出来；这个固定说法命名的正是这段距离。"},{"no":"09","title":"Rule-based production in computing","titleCN":"计算机与数学中的“生成”","definition":"the production of text, images, or sequences by a rule, grammar, or model","definitionCN":"由规则、语法或模型产出文本、图像或序列","example":"Text generation has improved faster than machine translation.","exampleCN":"文本生成的进步速度超过了机器翻译。","why":"The newest branch keeps the oldest structure: a rule or model brings forth output, and the noun names the producing rather than the product.","whyCN":"最新的一支仍保留最古老的结构：规则或模型带出输出，而这个名词命名的是产出过程，而不是产物。"}],"etymology":{"intro":{"en":"Generation came into English from Old French and Latin in the early 14th century, and its senses grew outward from one cohort to a whole family of 'producing' meanings.","cn":"generation 在 14 世纪早期经由古法语和拉丁语进入英语，它的义项从“一群人”向外扩展成整族“生产、产生”的含义。"},"items":[{"era":"EARLY 14C.","en":"First recorded meaning 'body of individuals born about the same period', on the notion of 'descendants at the same stage in the line of descent'.","cn":"最早记录义为“大约同一时期出生的一群人”，基于“处于传承线上同一阶段的后代”这一观念。"},{"era":"OLD FRENCH / LATIN","en":"From Old French generacion (12c.) 'race, people, species; progeny; act of procreating', and directly from Latin generationem, a noun of action from generare.","cn":"来自古法语 generacion（12 世纪），意为“种族、人群、物种；后代；生育行为”，并直接来自拉丁语 generationem，即 generare 的行为名词。"},{"era":"LATE 14C.","en":"Senses widen to 'act or process of procreation', 'that which is produced, fruit, crop', and 'offspring, descendants of the same parent'.","cn":"义项扩展为“生育的行为或过程”“被产出的东西、果实、收成”，以及“同一父母的后代、子嗣”。"},{"era":"LATIN ROOT","en":"Latin generare 'bring forth, beget, produce' is built on genus 'race, kind', from the reconstructed PIE root *gene- 'give birth, beget'.","cn":"拉丁语 generare“生出、繁衍、产生”建立在 genus“种族、种类”上，后者可追溯到重构的原始印欧语词根 *gene-“生育、繁衍”。"},{"era":"FIXED PHRASES","en":"First-generation and second-generation, used of immigrant families, are recorded from 1856; generation gap from 1967; Generation X from 1991, in Douglas Coupland's book of that name.","cn":"用于移民家庭的第一代、第二代说法自 1856 年有记录；generation gap 自 1967 年；Generation X 自 1991 年，出自道格拉斯·库普兰的同名著作。"},{"era":"MODERN TECHNICAL","en":"Power generation and data generation extend the 'production' branch, and text generation is the newest computing extension. None of these adds a new etymology; they widen the same noun.","cn":"发电与数据生成扩展了“生产”这一支，文本生成则是最新的计算机扩展。这些用法都没有新增词源，只是把同一个名词用得更宽。"}]},"similar":{"note":{"en":"The first group separates the gener- family members that learners mix up; the second compares nouns for cohorts, periods and products.","cn":"第一组区分 gener- 词族中最易混淆的成员；第二组比较表示人群、时期与产物的名词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"generate","ipa":"/ˈdʒenəreɪt/","tag":"same family, verb","definition":"to produce or bring forth. It is the verb; generation is the noun and cannot take an object.","definitionCN":"产生、生成。它是动词；generation 是名词，不能带宾语。"},{"word":"generational","ipa":"/ˌdʒenəˈreɪʃənl/","tag":"adjective","definition":"relating to generations or to differences between them, as in generational change. It describes a relation, not a process.","definitionCN":"与世代或代际差异有关的，如 generational change。它描述一种关系，而不是一个过程。"},{"word":"generator","ipa":"/ˈdʒenəreɪtə/","tag":"agent noun","definition":"a machine that produces electricity, or any agent that produces something. It names the producer, not the production.","definitionCN":"发电机，或任何产生某物的施动者。它命名生产者，而不是生产过程。"},{"word":"generative","ipa":"/ˈdʒenərətɪv/","tag":"adjective of capacity","definition":"having the power to produce, especially in the phrase generative grammar. It is a capacity word, not a count noun.","definitionCN":"具有生产能力的，尤见于生成语法一语。它是能力形容词，不是可数名词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"cohort","ipa":"/ˈkəʊhɔːt/","tag":"social-science term","definition":"a group of people with a shared characteristic, such as a birth year. It is precise and neutral, while generation also means a family stage and a period.","definitionCN":"具有共同特征（如出生年份）的一群人。它精确而中性，而 generation 还表示辈分与一段时间。"},{"word":"era","ipa":"/ˈɪərə/","tag":"period of time","definition":"a long period with a distinctive character. It names time itself, not the people born in it.","definitionCN":"具有鲜明特征的一段长时期。它命名时间本身，而不是在其中出生的人。"},{"word":"offspring","ipa":"/ˈɒfsprɪŋ/","tag":"product of procreation","definition":"the young of a person or animal. It is the product of procreation, not the whole cohort or the act.","definitionCN":"人或动物的幼崽、子女。它是生育的产物，而不是整个同代人或生育行为。"},{"word":"production","ipa":"/prəˈdʌkʃn/","tag":"general making","definition":"the act of making goods or bringing something into being. It overlaps with the power or data senses but is wider and more industrial.","definitionCN":"制造商品或使某物出现的行为。它与发电、数据生成等义重叠，但范围更广、更偏工业。"}]}]},"mnemonics":{"normalIntro":{"en":"Real word parts and real relatives: the Latin noun generatio and the verb generare, plus the modern family generate / generator / generational.","cn":"只用真实构词成分与真实同族词：拉丁名词 generatio 与动词 generare，以及现代词族 generate／generator／generational。"},"normal":[{"en":"Generation is the noun of generate: whatever is brought forth can be called a generation, whether people, power or text.","cn":"generation 是 generate 的名词：被带出的东西都可叫 generation，不论是人、电还是文本。"},{"en":"The cohort sense counts sideways in time; the family sense counts downward in a line of descent.","cn":"同代人的义项沿时间横向计数；辈分的义项沿传承线向下计数。"},{"en":"First-generation and second-generation are fixed labels for immigrant families, recorded since 1856.","cn":"第一代、第二代是移民家庭的固定标签，自 1856 年起有记录。"},{"en":"Generation gap is a 1967 phrase, and Generation X a 1991 one: both are recent labels for old relations.","cn":"generation gap 是 1967 年的说法，Generation X 是 1991 年的说法：两者都是用新标签命名旧关系。"},{"en":"Power generation and text generation are the same noun doing industrial and digital work.","cn":"发电与文本生成，是同一个名词在做工业与数字两方面的活。"}],"abstract":[{"en":"Picture tree rings: each ring is a span of years, and each ring grows out of the one before it.","cn":"想象树的年轮：每一圈是一段时间，每一圈都由前一圈长出来。"},{"en":"The same ring can be read as people born together, as one step in a family, or as one round of a product.","cn":"同一圈年轮可以被读成同期出生的人、家族中的一级，或产品的一轮。"},{"en":"Generation always names a unit that is brought forth, never the source that brings it forth.","cn":"generation 始终命名被带出的那个单位，而从不命名带出它的源头。"}]},"examples":[{"en":"Each generation inherits the language of the one before it and changes it.","cn":"每一代人都继承上一代的语言，并改变它。"},{"en":"The report compares electricity generation from coal and from wind.","cn":"这份报告比较了燃煤发电与风力发电。"},{"en":"A new generation of sensors can detect damage before it spreads.","cn":"新一代传感器能在损坏扩散之前发现它。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“杰诺瑞神”——杰诺瑞一挥手，生出一整代人 → generation 一代人、产生（只借音，不表词源）","word":"generation"},"root":"源自拉丁语 generatio，为 generare“生出”的行为名词，词根 genus“种族、种类”，核心是“一段时间或一条谱系中被带出来的一批”。","sensesIntro":{"en":"Nine senses of generation, all built on one image: a stretch of time or a line of descent brings forth a set of people, things or energy, one round after another.","cn":"generation 的九个义项都建立在同一个意象上：一段时间或一条谱系带出一批人、一批物或一股能量，一轮接着一轮。"},"semanticMap":{"core":{"en":"CORE IMAGE: one ring of growth, brought forth by the ring before it.","cn":"核心意象：一圈年轮，由前一圈带出。"},"chain":["BIRTH","SAME STAGE","A COHORT","A SPAN OF YEARS","A LINE OF DESCENT","A NEW ROUND"],"branches":[{"senses":"01 · 04","en":"TIME: a cohort and the thirty-odd years it occupies are the same horizontal slice read two ways.","cn":"时间：同代人与它占据的三十来年，是同一段横向切片被读成两种东西。"},{"senses":"02 · 07","en":"LINEAGE: family stages and product rounds are both steps in a line, each brought forth by the previous one.","cn":"谱系：家族辈分与产品轮次都是线上的台阶，每一级都由上一级带出。"},{"senses":"03","en":"BIRTH: the act of begetting, the oldest abstract sense of the noun.","cn":"生育：生育行为本身，是这个名词最古老的抽象义。"},{"senses":"05 · 06 · 09","en":"PRODUCTION: power, ideas and text are all brought forth, and the noun names the producing.","cn":"生产：电、想法与文本都被带出，而这个名词命名的是产出过程。"},{"senses":"08","en":"DISTANCE: when two cohorts are compared, the gap between them gets a phrase of its own.","cn":"落差：当两代人被比较时，他们之间的差距就得到自己的固定说法。"}]},"affixes":{"intro":{"en":"Generation is a Latin noun of action: the stem generat- plus -ion. English then adds -al, inter-, multi- and -ly to build the modern family.","cn":"generation 是拉丁语的行为名词：词干 generat- 加 -ion。英语随后加 -al、inter-、multi- 与 -ly，构成现代词族。"},"latinIntro":{"en":"Latin generatio is built on generare 'to bring forth', whose own stem is genus, generis 'race, kind'. Generatus is its past participle, and generativus the adjective that English turns into generative.","cn":"拉丁语 generatio 建立在 generare“生出”上，而后者的词干是 genus、generis“种族、种类”。generatus 是它的过去分词，generativus 则是对应的形容词，英语把它变成 generative。"},"items":[{"word":"generation","structure":"generat- + -ion (action noun)","meaning":"the act of producing; a cohort; a stage in a line","meaningCN":"产生；一代人；谱系中的一级（-ion 构成行为名词）","example":"The generation of the report took three days.","exampleCN":"这份报告的生成花了三天。"},{"word":"generate","structure":"gener- + -ate (verb)","meaning":"to bring forth, produce","meaningCN":"产生；生成","example":"The panels generate power all afternoon.","exampleCN":"这些光伏板整个下午都在发电。"},{"word":"generator","structure":"generat- + -or (agent noun)","meaning":"a machine or agent that produces something","meaningCN":"发电机；生成器；产生者","example":"The generator failed during the storm.","exampleCN":"暴风雨中发电机坏了。"},{"word":"generative","structure":"generat- + -ive (adjective)","meaning":"having the power to produce","meaningCN":"有生成能力的","example":"Generative grammar studies rule-based sentence production.","exampleCN":"生成语法研究按规则产出句子的机制。"},{"word":"generational","structure":"generation + -al (relational adjective)","meaning":"relating to generations","meaningCN":"代际的；与世代有关的","example":"Generational differences shape the debate.","exampleCN":"代际差异塑造了这场辩论。"},{"word":"intergenerational","structure":"inter- (between) + generational","meaning":"between generations","meaningCN":"代与代之间的（inter- 表示“在……之间”）","example":"The programme pairs students with older residents for intergenerational learning.","exampleCN":"这个项目把学生与年长居民配对，进行代际学习。"},{"word":"multigenerational","structure":"multi- (many) + generational","meaning":"involving several generations","meaningCN":"多代的；多代同堂的（multi- 表示“多”）","example":"They live in a multigenerational household.","exampleCN":"他们住在一个多代同堂的家庭里。"},{"word":"generationally","structure":"generational + -ly (adverb)","meaning":"with respect to generations","meaningCN":"在代际层面上（-ly 构成副词）","example":"The habit is generationally transmitted.","exampleCN":"这种习惯在代际之间传递。"},{"word":"regenerate","structure":"re- (again) + generate","meaning":"to produce again","meaningCN":"再生；重新产生","example":"The tissue can regenerate within weeks.","exampleCN":"这种组织能在几周内再生。"},{"word":"degenerate","structure":"de- (away) + generate","meaning":"to fall away from the original kind","meaningCN":"退化；变质","example":"The discussion degenerated into noise.","exampleCN":"讨论退化成了一片噪音。"}],"latinEntries":[{"word":"generatio","structure":"generare + -io (action noun)","meaning":"a generating; a race or generation","meaningCN":"生成；生育；一代人"},{"word":"generare","structure":"gener- + -are (infinitive)","meaning":"to bring forth, beget, produce","meaningCN":"生出；繁衍；产生"},{"word":"generatus","structure":"past participle of generare","meaning":"brought forth, produced","meaningCN":"被生出；被产生"},{"word":"genus","structure":"PIE *gene- 'give birth, beget'","meaning":"race, stock, kind","meaningCN":"种族；血统；种类"}]}},{"word":"global","ipa_uk":"/ˈɡləʊbl/","ipa_us":"/ˈɡloʊbl/","definition_zh":"全球的；全世界的；整体的；全面的；球形的","definition_en":"relating to the whole world, or covering every part of a system rather than only some of it","core_image":"一只球面被整片涂满，没有留下任何一块空白","scene":"The report warns that global temperatures have risen for the third year in a row.","sceneCN":"这里 global 是「全球的、整个地球范围的」（第 2 个义项：覆盖整个地球）；句意：报告警告说，全球气温已连续第三年上升。场景要点：一只画满经纬线的地球仪、三条向上的温度曲线，以及代表各大洲的色块。","pos":[{"tag":"adj.","zh":"全球的；全世界的"},{"tag":"adj.","zh":"整体的；全面的；全局的"}],"collocations":[{"phrase":"global warming","zh":"全球变暖"},{"phrase":"the global economy","zh":"全球经济"},{"phrase":"the global market","zh":"全球市场"},{"phrase":"on a global scale","zh":"在全球范围内"},{"phrase":"global village","zh":"地球村"},{"phrase":"global citizen","zh":"世界公民"},{"phrase":"a global variable","zh":"全局变量"}],"forms":[{"label":"比较级（多音节形容词用 more 构成）","form":"more global"}],"derivatives":[{"word":"globally","pos":"adv.","zh":"全球地；在世界范围内"},{"word":"globalization","pos":"n.","zh":"全球化"},{"word":"globalize","pos":"v.","zh":"使全球化"},{"word":"globalism","pos":"n.","zh":"全球主义"},{"word":"globalist","pos":"n./adj.","zh":"全球主义者；全球主义的"},{"word":"globalized","pos":"adj.","zh":"已经全球化的"}],"senses":[{"no":"01","title":"Shaped like a globe","titleCN":"球形的","definition":"shaped like a sphere or ball; the oldest recorded sense","definitionCN":"形状像球体的；这是最早有记录的义项","example":"The lamp has a global shade that spreads light evenly.","exampleCN":"这盏灯有一个球形灯罩，能把光均匀散开。","why":"Global began in the 1670s as the adjective of globe, and globe meant a round mass or sphere. The first sense is simply 'sphere-shaped'.","whyCN":"global 在 17 世纪 70 年代作为 globe 的形容词出现，而 globe 指圆形的团块或球体。最早的义项就是“球形的”。"},{"no":"02","title":"Covering the whole earth","titleCN":"覆盖整个地球的","definition":"relating to or affecting the entire planet","definitionCN":"与整个地球有关或影响整个地球的","example":"Global temperatures have risen for the third year.","exampleCN":"全球气温已连续第三年上升。","why":"The earth is itself a globe, so an adjective meaning 'sphere-shaped' transfers to the sphere we live on and comes to mean 'worldwide'.","whyCN":"地球本身就是一个球体，因此表示“球形”的形容词被转用到我们居住的这个球上，进而表示“全世界的”。"},{"no":"03","title":"Operating at worldwide scale","titleCN":"全球规模的（经营、贸易）","definition":"working or trading across the whole world rather than in one region","definitionCN":"在整个世界而非某一地区经营或交易","example":"The firm runs a global supply chain across four continents.","exampleCN":"这家公司经营着横跨四大洲的全球供应链。","why":"Business activity draws a boundary around the whole planet: if every region is inside it, the operation is global.","whyCN":"商业活动把整个星球圈成一条边界：如果每个地区都在边界之内，这项经营就是全球性的。"},{"no":"04","title":"Total within a system","titleCN":"整体的、全面的（系统范围）","definition":"covering every part of a system, not just one section of it","definitionCN":"覆盖一个系统的每个部分，而不只是其中一段","example":"A global check of the design caught problems the local tests missed.","exampleCN":"一次对设计的整体检查发现了局部测试漏掉的问题。","why":"The notion of a closed sphere moves from geography to a system: what is global covers every part of that system.","whyCN":"封闭球体的观念从地理转向系统：global 的东西覆盖该系统的每一个部分。"},{"no":"05","title":"Computing: accessible everywhere in a program","titleCN":"计算机：全局的","definition":"of a variable or setting, visible and usable throughout a whole program","definitionCN":"指变量或设置在整个程序中可见、可用","example":"A global variable can be read by every function in the file.","exampleCN":"全局变量可以被文件中的每个函数读取。","why":"A program is treated as a small world with a boundary; a variable declared global is visible across the whole of it.","whyCN":"程序被看作一个有边界的微型世界；被声明为 global 的变量在其中处处可见。"},{"no":"06","title":"Planetary environment and climate","titleCN":"地球环境的、气候的","definition":"relating to effects that belong to the earth as one physical body, especially in climate science","definitionCN":"指属于地球这一整体物理系统的影响，尤用于气候科学","example":"Global sea levels are measured by satellite.","exampleCN":"全球海平面由卫星测量。","why":"Earth-system science needs a word for effects that belong to the planet as one body, and the earth-globe sense supplies it.","whyCN":"地球系统科学需要一个词来指属于整个星球这一实体的效应，而“地球即球体”的义项正好提供了它。"},{"no":"07","title":"Involving all nations together","titleCN":"涉及所有国家的","definition":"including all nations collectively, as opposed to only some of them","definitionCN":"把所有国家作为一个整体包含进来，而不是只涉及其中一部分","example":"The treaty requires a global agreement, not a regional one.","exampleCN":"这项条约需要一项全球协议，而不是地区性协议。","why":"Here the sphere is divided into states: global means that all of them are inside the boundary at once.","whyCN":"这里球面被划分成国家：global 意味着所有国家同时都在边界之内。"},{"no":"08","title":"One shared world of people","titleCN":"全球一体的（地球村、世界公民）","definition":"in phrases such as global village and global citizen, belonging to the world as a single community","definitionCN":"在 global village、global citizen 等说法中，指属于作为单一共同体的世界","example":"Global citizenship is taught as a way of thinking about shared problems.","exampleCN":"世界公民意识作为一种思考共同问题的方式被教授。","why":"The last step is social: the globe becomes a single community, and global describes belonging to it rather than to a nation.","whyCN":"最后一步是社会性的：地球变成一个单一共同体，global 描述的是归属于它，而不是归属于某个国家。"}],"etymology":{"intro":{"en":"Global was a plain adjective of shape for more than two hundred years before it came to mean 'worldwide'; its history runs from a ball to the planet.","cn":"global 在两百多年里一直是朴素的形状形容词，之后才表示“全世界的”；它的历史从一只球走到了整个星球。"},"items":[{"era":"1670S","en":"First recorded meaning 'spherical', formed from globe plus the adjective suffix -al.","cn":"最早记录义为“球形的”，由 globe 加形容词后缀 -al 构成。"},{"era":"GLOBE","en":"Globe is recorded from the late 14c. as 'a large mass', and from the mid-15c. as 'spherical solid body', from Old French globe and Latin globus 'round mass, sphere, ball'. Latin globus is related to gleba 'clod, lump of soil' and perhaps to glomus 'ball of yarn'.","cn":"globe 在 14 世纪晚期记录为“一大团”，15 世纪中期记录为“球形实体”，来自古法语 globe 和拉丁语 globus“圆团、球体、球”。拉丁语 globus 与 gleba“土块”有关，并且可能与 glomus“线球”有关。"},{"era":"1550S","en":"Globe comes to mean 'the planet earth' and also a map of the earth drawn on a sphere.","cn":"globe 开始表示“地球这颗行星”，也指画在球面上的地球图。"},{"era":"1892","en":"The sense 'worldwide, universal, pertaining to the whole globe of the earth' appears, attributed to a sense development in French. The specific French source is not documented, so the route is source uncertain.","cn":"“全世界的、普遍的、与整个地球有关的”这一义项出现，并被归因于法语中的语义发展。具体是哪个法语用法，并无文献说明，因此这条路径属于存疑。"},{"era":"1960","en":"Global village is first attested in 1960, popularized if not coined by the Canadian educator Marshall McLuhan.","cn":"global village 最早见于 1960 年，由加拿大教育家马歇尔·麦克卢汉普及，可能并非他首创。"},{"era":"20C","en":"Globalism is used from about 1946; globalize, globalization and globally follow as the world becomes a unit of trade, communication and policy.","cn":"globalism 约自 1946 年起使用；随着世界成为贸易、通信与政策的单位，globalize、globalization、globally 相继出现。"}]},"similar":{"note":{"en":"The first group separates the noun, adverb and process nouns built on globe; the second compares words for scope, from geography to logic.","cn":"第一组区分由 globe 构成的名词、副词与过程名词；第二组比较表示范围大小的词，从地理到逻辑。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"globe","ipa":"/ɡləʊb/","tag":"the noun","definition":"a spherical model of the earth, or the earth itself. The noun names the object, while global is the adjective of scope.","definitionCN":"地球的球体模型，或地球本身。名词命名物体，而 global 是表示范围的形容词。"},{"word":"globally","ipa":"/ˈɡləʊbəli/","tag":"adverb","definition":"in a way that involves the whole world. It modifies an action or a statement, not a noun.","definitionCN":"以涉及全世界的方式。它修饰动作或陈述，而不是名词。"},{"word":"globalization","ipa":"/ˌɡləʊbəlaɪˈzeɪʃn/","tag":"process noun","definition":"the process by which economies and cultures become connected worldwide. It names the process; global only names the scope.","definitionCN":"经济与文化在全球范围内连成一体的过程。它命名过程，而 global 只命名范围。"},{"word":"globalism","ipa":"/ˈɡləʊbəlɪzəm/","tag":"doctrine noun","definition":"an ideology or policy favouring worldwide integration. The -ism marks a doctrine, not a geographic scope.","definitionCN":"主张全球一体化的意识形态或政策。-ism 标记的是一种主张，而不是地理范围。"}]},{"heading":"NEAR MEANING","entries":[{"word":"worldwide","ipa":"/ˌwɜːldˈwaɪd/","tag":"plain geography","definition":"extending over the whole world. It is plainer and more geographical; global is also used for systems and computing.","definitionCN":"延伸到整个世界。它更朴素、更偏地理；global 还用于系统和计算机领域。"},{"word":"international","ipa":"/ˌɪntəˈnæʃənl/","tag":"between nations","definition":"involving two or more nations. It does not require all nations, so an international meeting can be regional; global implies all.","definitionCN":"涉及两个或更多国家。它不要求所有国家参与，因此一次国际会议可以是地区性的；global 则暗示全部。"},{"word":"universal","ipa":"/ˌjuːnɪˈvɜːsl/","tag":"logic and abstraction","definition":"true of or applying to all cases, people, or things. It is logical and abstract, while global is physical or systemic.","definitionCN":"对一切情况、人或物都成立或适用。它偏逻辑、偏抽象，而 global 偏物理或系统。"},{"word":"planetary","ipa":"/ˈplænətəri/","tag":"earth-system term","definition":"relating to a planet as a whole, especially Earth in climate science. It is more technical and narrower than global.","definitionCN":"与整个行星有关的，尤指气候科学中的地球。它比 global 更技术化，范围也更窄。"}]}]},"mnemonics":{"normalIntro":{"en":"Real word parts and real relatives: globe plus -al, and the modern family globally / globalization / globalize.","cn":"只用真实构词成分与真实同族词：globe 加 -al，以及现代词族 globally／globalization／globalize。"},"normal":[{"en":"Global began as the adjective of globe: first 'ball-shaped', then 'earth-wide', because the earth is a globe.","cn":"global 起初是 globe 的形容词：先表示“球形的”，后表示“遍及地球的”，因为地球本身就是一个球。"},{"en":"The 1892 date matters: for two centuries global described shape, not scope.","cn":"1892 年这个时间点很重要：在此之前的两百年里，global 描述的是形状，而不是范围。"},{"en":"Global village is a 1960 phrase associated with Marshall McLuhan, not a medieval one.","cn":"global village 是 1960 年的说法，与马歇尔·麦克卢汉相关，并不是中世纪的表达。"},{"en":"In computing, global is about visibility inside a program: a global variable can be seen everywhere in it.","cn":"在计算机领域，global 讲的是程序内部的可见性：全局变量在程序各处都能被看到。"},{"en":"Globalism is a doctrine, globalization is a process, and global is only a scope; the suffixes keep them apart.","cn":"globalism 是一种主张，globalization 是一个过程，而 global 只是范围；后缀把它们区分开来。"}],"abstract":[{"en":"Picture a ball painted completely, with no unpainted patch left anywhere on it.","cn":"想象一只被完全涂满的球，表面任何地方都没有留下未涂的斑块。"},{"en":"That ball can be the earth, a market, a program, or a design: the same complete surface, different worlds.","cn":"这只球可以是地球、一个市场、一段程序或一份设计：同样完整的表面，不同的世界。"},{"en":"Global always draws a boundary around a whole, then says that nothing important lies outside it.","cn":"global 总是先围出一个整体的边界，然后说明重要内容都不在边界之外。"}]},"examples":[{"en":"The pandemic turned a local shortage into a global one within weeks.","cn":"这场大流行在几周内把局部的短缺变成了全球性的短缺。"},{"en":"A global review found that the two departments were duplicating work.","cn":"一次整体审查发现这两个部门在做重复的工作。"},{"en":"The variable was declared global so that every module could read it.","cn":"这个变量被声明为全局变量，以便每个模块都能读取它。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“哥楼宝”——哥站在楼顶抱着地球仪，一抬眼看到整个世界 → global 全球的（只借音，不表词源）","word":"global"},"root":"由 globe“球体”加 -al 构成；globe 源自拉丁语 globus“圆团、球”，核心是“把整个球面都包括进来”。","sensesIntro":{"en":"Eight senses of global, all built on one shape: a complete surface with no gap, whether that surface is a ball, the earth, a market, a program or a design.","cn":"global 的八个义项都建立在同一个形状上：一个没有缺口的完整表面——这个表面可以是一只球、地球、一个市场、一段程序或一份设计。"},"semanticMap":{"core":{"en":"CORE IMAGE: a whole sphere, entirely covered.","cn":"核心意象：一只被完全覆盖的球体。"},"chain":["A ROUND BALL","THE EARTH ITSELF","ALL PLACES AT ONCE","ALL NATIONS TOGETHER","EVERY PART OF A SYSTEM","ONE SHARED WORLD"],"branches":[{"senses":"01","en":"SHAPE: the original 1670s sense is simply 'sphere-shaped'.","cn":"形状：17 世纪 70 年代最初的义项就是“球形的”。"},{"senses":"02 · 06","en":"THE PLANET: the earth is a globe, so the word covers the whole planet and its climate.","cn":"行星：地球是一个球体，因此这个词覆盖整个星球及其气候。"},{"senses":"03 · 07","en":"SCALE AND NATIONS: trade or a treaty can include every region or every state at once.","cn":"规模与国家：贸易或条约可以同时包含每个地区或每个国家。"},{"senses":"04","en":"SYSTEM: the sphere becomes a system, and global means every part of it has been checked.","cn":"系统：球体变成系统，global 意味着它的每个部分都已被检查。"},{"senses":"05 · 08","en":"TECHNICAL AND SOCIAL: a program's global scope, or a world treated as one community.","cn":"技术与社群：程序的全局作用域，或被视为一个共同体的世界。"}]},"affixes":{"intro":{"en":"Global is globe plus the adjective suffix -al. The modern family then adds -ly, -ize, -ization, -ism and -ist, each with a clear function.","cn":"global 是 globe 加形容词后缀 -al。现代词族随后加上 -ly、-ize、-ization、-ism 与 -ist，每个后缀都有清楚的功能。"},"latinIntro":{"en":"Latin globus 'round mass, sphere' is the source of globe and global. Gleba 'clod of soil' is a related Latin word, and glomus 'ball of yarn' is only perhaps related.","cn":"拉丁语 globus“圆团、球体”是 globe 与 global 的来源。gleba“土块”是有关的拉丁词，而 glomus“线球”只是可能有关。"},"items":[{"word":"globe","structure":"Latin globus 'round mass, sphere'","meaning":"a spherical model of the earth; the earth","meaningCN":"地球仪；地球","example":"The teacher turned the globe to show the equator.","exampleCN":"老师转动地球仪，指出赤道。"},{"word":"global","structure":"globe + -al (relational adjective)","meaning":"relating to the whole world or a whole system","meaningCN":"全球的；整体的（-al 构成关系形容词）","example":"Global demand for lithium keeps rising.","exampleCN":"全球对锂的需求持续上升。"},{"word":"globally","structure":"global + -ly (adverb)","meaning":"across the whole world","meaningCN":"在全球范围内","example":"The product is sold globally.","exampleCN":"这款产品在全球销售。"},{"word":"globalize","structure":"global + -ize (verb)","meaning":"to make worldwide in scope","meaningCN":"使全球化（-ize 构成动词）","example":"Firms globalize to reach cheaper suppliers.","exampleCN":"企业走向全球化，以接触到更便宜的供应商。"},{"word":"globalization","structure":"globalize + -ation (process noun)","meaning":"the process of becoming worldwide","meaningCN":"全球化（-ation 构成过程名词）","example":"Globalization changed the textile industry.","exampleCN":"全球化改变了纺织业。"},{"word":"globalism","structure":"global + -ism (doctrine noun)","meaning":"a policy or ideology favouring worldwide integration","meaningCN":"全球主义（-ism 表示主张或主义）","example":"The debate contrasted globalism with local control.","exampleCN":"这场辩论把全球主义与本地控制对立起来。"},{"word":"globalist","structure":"global + -ist (person or adjective)","meaning":"a supporter of global integration","meaningCN":"全球主义者（-ist 表示人或形容词）","example":"Critics called the policy globalist.","exampleCN":"批评者称这项政策是全球主义的。"},{"word":"globalized","structure":"globalize + -ed (past participle adjective)","meaning":"made worldwide in scope","meaningCN":"已经全球化的（-ed 构成形容词）","example":"They work in a highly globalized market.","exampleCN":"他们在一个高度全球化的市场中工作。"},{"word":"globular","structure":"glob- + -ular (adjective)","meaning":"shaped like a small sphere","meaningCN":"小球状的（-ular 构成形容词）","example":"The protein forms a globular shape.","exampleCN":"这种蛋白质形成一个球状结构。"},{"word":"globe-trotter","structure":"globe + trotter (compound noun)","meaning":"a person who travels widely around the world","meaningCN":"周游世界的人（合成名词）","example":"She has been a globe-trotter since university.","exampleCN":"她从大学起就一直在周游世界。"}],"latinEntries":[{"word":"globus","structure":"Latin noun","meaning":"round mass, sphere, ball; also a throng or crowd","meaningCN":"圆团；球体；球；（也指人群、一团）"},{"word":"gleba","structure":"related Latin noun","meaning":"clod, lump of soil","meaningCN":"土块；泥土团"},{"word":"glomus","structure":"perhaps related Latin noun","meaning":"a ball, ball of yarn","meaningCN":"球；线球（与 globus 可能有关）"}]}},{"word":"goal","ipa_uk":"/ɡəʊl/","ipa_us":"/ɡoʊl/","definition_zh":"目标；目的；球门；进球得分；终点","definition_en":"the end point you aim at, whether a line to cross, a result to achieve, or a frame to put the ball into","core_image":"跑道尽头插着的一面旗，所有脚步都朝它收拢","scene":"She scored the winning goal in the last minute of the match.","sceneCN":"这里 goal 是「进球、得分」（第 4 个义项：把球送进球门所得到的一分）；句意：她在比赛最后一分钟打入了制胜的一球。场景要点：球门网、飞过门线的球、停在最后一分钟的计时器，以及看台上举起的手臂。","pos":[{"tag":"n.","zh":"目标；目的；终点"},{"tag":"n.","zh":"（体育）球门；进球得分"}],"collocations":[{"phrase":"score a goal","zh":"进球得分"},{"phrase":"achieve a goal","zh":"实现目标"},{"phrase":"set a goal","zh":"设定目标"},{"phrase":"a long-term goal","zh":"长期目标"},{"phrase":"an own goal","zh":"乌龙球"},{"phrase":"the goal line","zh":"球门线"},{"phrase":"the goal of the study","zh":"这项研究的目的"}],"forms":[{"label":"复数","form":"goals"}],"derivatives":[{"word":"goalie","pos":"n.","zh":"守门员"},{"word":"goalkeeper","pos":"n.","zh":"守门员"},{"word":"goalpost","pos":"n.","zh":"球门柱"},{"word":"goalless","pos":"adj.","zh":"没有进球的"},{"word":"goal-scorer","pos":"n.","zh":"进球者；得分者"},{"word":"goal-scoring","pos":"n./adj.","zh":"进球；得分的"}],"senses":[{"no":"01","title":"The end point of a race","titleCN":"赛跑的终点","definition":"the mark or line at which a race ends","definitionCN":"赛跑结束处的标记或界线","example":"The runners sprinted toward the goal at the far end of the track.","exampleCN":"选手们朝跑道尽头的终点冲刺。","why":"Goal is first recorded in the 1530s as the end point of a race. The word names the mark that ends motion, and its own origin is not settled.","whyCN":"goal 最早在 16 世纪 30 年代记录为赛跑的终点。这个词命名的是让运动结束的那个标记，而它自身的来源尚无定论。"},{"no":"02","title":"The object of an effort","titleCN":"努力的目标","definition":"the result or state that a person or group works toward","definitionCN":"个人或团体努力要达成的结果或状态","example":"Her goal is to finish the marathon under four hours.","exampleCN":"她的目标是在四小时内跑完马拉松。","why":"The figurative sense, also from the 1540s, treats life as a course: the result you want is the mark you run toward.","whyCN":"这一比喻义同样始于 16 世纪 40 年代：它把人生当作一段赛程，你想要的结果就是你朝它奔跑的那个标记。"},{"no":"03","title":"The frame where the ball is put","titleCN":"球门","definition":"the structure of posts and net into which players try to send the ball","definitionCN":"由门柱和球网构成、球员努力把球送进去的结构","example":"The goalkeeper stood between the posts of the goal.","exampleCN":"守门员站在球门柱之间。","why":"The sports sense, also from the 1540s, makes the end point physical: a frame marks the place where the ball must arrive.","whyCN":"同样始于 16 世纪 40 年代的体育义项，把终点变成实物：一个框架标出了球必须抵达的位置。"},{"no":"04","title":"A score made in the frame","titleCN":"进球得分","definition":"a point gained by sending the ball through or into the goal","definitionCN":"把球送过门线或送进球门而得到的一分","example":"She scored the winning goal in the last minute.","exampleCN":"她在最后一分钟打入了制胜的一球。","why":"By metonymy the frame gives its name to the event of putting the ball through it: the endpoint becomes the point gained.","whyCN":"通过转喻，框架把自己的名字借给了“把球送进去”这件事：终点变成了所得的一分。"},{"no":"05","title":"A measured target in work","titleCN":"工作指标","definition":"a figure or quota that a team or company is expected to reach","definitionCN":"团队或公司被要求达到的数字或定额","example":"The sales team missed its quarterly goal by two percent.","exampleCN":"销售团队以两个百分点的差距未能达到季度指标。","why":"A number can serve as the mark: once the target is measurable, the race endpoint becomes a quota.","whyCN":"数字也可以充当那个标记：一旦目标可以计量，赛跑的终点就变成了定额。"},{"no":"06","title":"A long-term aim in life","titleCN":"人生志向","definition":"a distant aim that gives direction to a person's life or career","definitionCN":"为人生或事业提供方向的远期追求","example":"His goal is to run a clinic in his home town.","exampleCN":"他的志向是在家乡开一家诊所。","why":"The largest version of the same image: a whole life is the course, and one distant mark gives it direction.","whyCN":"这是同一个意象的最大版本：整个人生是赛程，一个远处的标记为它提供方向。"},{"no":"07","title":"Own goal: a score against your own side","titleCN":"乌龙球","definition":"in the fixed phrase own goal, a goal scored accidentally for the opposing team","definitionCN":"在固定搭配 own goal 中，指误为对方球队打进的一球","example":"The defender's own goal decided the tie.","exampleCN":"后卫的乌龙球决定了这场平局的结果。","why":"The frame is neutral: a ball put into the wrong one still counts. English names that accident with the fixed phrase own goal.","whyCN":"球门本身是中立的：球进了错误的那一个，仍然算数。英语用固定说法 own goal 命名这种意外。"},{"no":"08","title":"Goal line and goal area","titleCN":"球门线与球门区","definition":"the line and the marked area on the field that belong to the goal","definitionCN":"场地上属于球门的那条线和被划出的区域","example":"The ball crossed the goal line by a few centimetres.","exampleCN":"球越过球门线几厘米。","why":"The frame projects a boundary onto the field; the line and the area are the ground version of the same endpoint.","whyCN":"球门把一条边界投射到场地上；球门线与球门区是同一个终点在地面上的版本。"},{"no":"09","title":"Attributive: goal-directed, goal-setting","titleCN":"作定语：目标导向的","definition":"used before another noun to describe activity organised around a target","definitionCN":"用在另一名词之前，描述围绕目标组织起来的活动","example":"Goal-setting theory treats clear targets as a motivator.","exampleCN":"目标设定理论把清晰的目标视为一种激励因素。","why":"When the word moves in front of another noun, it stops naming a mark and starts labelling the activity that is organised around one.","whyCN":"当这个词移到另一个名词前面时，它不再命名一个标记，而是给围绕某个标记组织起来的活动贴标签。"}],"etymology":{"intro":{"en":"Goal is a single noun of uncertain origin: it appears in the 1530s as the end of a race, and every later sense keeps that 'mark ahead' shape.","cn":"goal 是一个来源不确定的单词：它在 16 世纪 30 年代以“赛跑终点”出现，后来每个义项都保留着“前方有一个标记”的形状。"},"items":[{"era":"1530S","en":"First recorded as 'end point of a race'. The word appears once earlier, as gol in an early-14c poem, with an apparent sense of 'boundary, limit'.","cn":"最早记录为“赛跑的终点”。这个词更早还出现过一次，在 14 世纪早期的一首诗里写作 gol，似乎是“边界、界限”的意思。"},{"era":"UNCERTAIN ORIGIN","en":"Three origins have been proposed and none is established: Old English *gal 'obstacle, barrier', implied by gælan 'to hinder' and by compounds such as singal and widgal; Old Norse geil 'a narrow glen, a passage'; or Old French gaule 'long pole, stake', which is Germanic in origin. The source is marked source uncertain.","cn":"先后有三种来源被提出，但没有一种得到确认：一是古英语 *gal“障碍、壁垒”，由 gælan“阻碍”以及 singal、widgal 等复合词推知；二是古诺尔斯语 geil“狭窄峡谷、通道”；三是古法语 gaule“长杆、桩”，而后者本身出自日耳曼语。词源属于存疑。"},{"era":"1540S","en":"The sports sense 'place where the ball is put to score' is recorded, and in the same decade the figurative sense 'object of an effort'.","cn":"记录到体育义“把球放进去得分的位置”，同一时期还出现比喻义“努力的目标”。"},{"era":"COMPOUNDS","en":"Goal-keeper appears in the 1650s; field goal in 1889; goal-tender in 1889; goalie in 1921 as a shortening of goal-tender.","cn":"goal-keeper 出现于 17 世纪 50 年代；field goal 与 goal-tender 出现于 1889 年；goalie 于 1921 年作为 goal-tender 的缩略形式出现。"},{"era":"MODERN ENGLISH","en":"Goalpost, goal line, goal area, own goal and goalless fill out the family. Goal itself remains a noun only; there is no verb 'to goal' in standard English.","cn":"goalpost、goal line、goal area、own goal、goalless 补全了这一词族。goal 本身始终只是名词；标准英语中没有 to goal 这样的动词用法。"},{"era":"FALSE FRIEND","en":"Gold is a different word with a different history; the resemblance to goal is only in sound and spelling. German Ziel means 'goal, target' but is not the source of the English word.","cn":"gold 是另一个词，来历完全不同；它与 goal 的相似只在读音和拼写上。德语 Ziel 意为“目标、终点”，但它并不是英语这个词的来源。"}]},"similar":{"note":{"en":"The first group is sound and spelling neighbours, including two that merely look like goal; the second compares the words for what you are trying to reach.","cn":"第一组是读音与拼写上的邻居，其中两个只是看起来像 goal；第二组比较表示“你想要抵达的东西”的几个词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"gold","ipa":"/ɡəʊld/","tag":"unrelated word","definition":"the yellow metal. It has no historical link with goal; only the vowel and the final consonant resemble each other.","definitionCN":"那种黄色金属。它与 goal 没有任何历史联系，只是元音和结尾辅音相近。"},{"word":"goalpost","ipa":"/ˈɡəʊlpəʊst/","tag":"compound","definition":"one of the two uprights of a goal. It is a compound of goal plus post, not a separate root word.","definitionCN":"球门两根立柱之一。它是 goal 加 post 的合成词，不是另一个词根词。"},{"word":"goalie","ipa":"/ˈɡəʊli/","tag":"derived noun","definition":"a goalkeeper. It is a 1921 shortening of goal-tender, so it belongs to the goal family.","definitionCN":"守门员。它是 1921 年对 goal-tender 的缩略，因此属于 goal 词族。"},{"word":"goalless","ipa":"/ˈɡəʊlləs/","tag":"derived adjective","definition":"without a goal being scored, as in a goalless draw. The suffix -less marks absence, not a new sense.","definitionCN":"没有进球的，如 goalless draw。后缀 -less 标记“没有”，并不产生新义项。"}]},{"heading":"NEAR MEANING","entries":[{"word":"aim","ipa":"/eɪm/","tag":"personal intention","definition":"what you intend to achieve; also the act of pointing at something. It is close to goal but often more personal and less measurable.","definitionCN":"你打算达成的东西；也指瞄准的动作。它与 goal 接近，但往往更个人化、更不可量化。"},{"word":"objective","ipa":"/əbˈdʒektɪv/","tag":"formal and measurable","definition":"a specific result that an organisation formally sets out to achieve. It is more formal and more measurable than goal.","definitionCN":"组织正式设定要达成的具体结果。它比 goal 更正式、更可量化。"},{"word":"target","ipa":"/ˈtɑːɡɪt/","tag":"figure to hit","definition":"a level or figure to be reached, often with a deadline. It stresses the number to hit, while goal stresses the direction.","definitionCN":"需要达到的水平或数字，常带截止时间。它强调要命中的数字，而 goal 强调方向。"},{"word":"purpose","ipa":"/ˈpɜːpəs/","tag":"reason for being","definition":"the reason something exists or is done. It answers 'why', while goal answers 'where to'.","definitionCN":"某物存在或被做的理由。它回答“为什么”，而 goal 回答“往哪里去”。"}]}]},"mnemonics":{"normalIntro":{"en":"Real word parts and real relatives: the noun goal, its compounds goalpost and goalkeeper, and the 1921 shortening goalie.","cn":"只用真实构词成分与真实同族词：名词 goal，它的合成词 goalpost、goalkeeper，以及 1921 年的缩略形式 goalie。"},"normal":[{"en":"Goal first meant the end of a race: a mark you run toward.","cn":"goal 最初指赛跑的终点：一个你朝它奔跑的标记。"},{"en":"The sports frame is that same mark made visible, and the score is named after the frame.","cn":"体育中的球门就是同一个标记变成实物，而“得分”又被球门命名。"},{"en":"Gold and goal are only neighbours in sound; they have no shared history.","cn":"gold 与 goal 只是读音上的邻居，没有共同的来历。"},{"en":"Own goal is a fixed phrase: the ball goes into the frame, but the wrong one.","cn":"own goal 是固定说法：球确实进了门，只是进错了那一个。"},{"en":"Goal-setting and goal-directed show the noun working as a modifier, common in psychology and management.","cn":"goal-setting 与 goal-directed 显示这个名词可以作修饰语，这在心理学与管理学中很常见。"}],"abstract":[{"en":"Picture a flag at the end of a track: every lane converges on it.","cn":"想象跑道尽头插着一面旗：每一条跑道都朝它收拢。"},{"en":"The flag can be a line, a number, a frame or a distant plan; the word always points to one mark.","cn":"那面旗可以是一条线、一个数字、一个框架，或一个远期的计划；这个词始终指向同一个标记。"},{"en":"A goal is not the running; it is the place where the running stops being open.","cn":"目标不是奔跑本身；它是奔跑不再敞开的那一点。"}]},"examples":[{"en":"The team's goal is to cut water use by a third within five years.","cn":"这个团队的目标是在五年内把用水量削减三分之一。"},{"en":"He scored twice and set up the third goal.","cn":"他打进两球，并助攻了第三个进球。"},{"en":"Without a clear goal, the meetings drifted from topic to topic.","cn":"没有明确的目标，会议就从一个话题漂到另一个话题。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“够儿”——一路跑到尽头，够着那面旗儿 → goal 目标、终点（只借音，不表词源）","word":"goal"},"root":"词源存疑：最早指赛跑的终点（1530 年代），可能来自古英语表示“障碍、界限”的词或古法语“长杆”；核心是“所有努力都朝向的那个终点”。","sensesIntro":{"en":"Nine senses of goal, all built on one position: a mark placed ahead, which motion or effort is organised to reach.","cn":"goal 的九个义项都建立在同一个位置关系上：前方放着一个标记，运动或努力都围绕抵达它来组织。"},"semanticMap":{"core":{"en":"CORE IMAGE: a mark ahead that every step converges on.","cn":"核心意象：前方的一个标记，所有脚步都朝它收拢。"},"chain":["A LINE TO CROSS","THE END OF A RACE","SOMETHING AHEAD","AN AIM","A FRAME TO HIT","A POINT SCORED"],"branches":[{"senses":"01","en":"RACE: the original sense is the physical end point of a course.","cn":"赛跑：最初的义项就是赛程的物理终点。"},{"senses":"02 · 06","en":"AIM: the mark becomes mental, from a single task to a whole life's direction.","cn":"目标：标记变成心里的，从一项任务一直到整个人生的方向。"},{"senses":"03 · 08","en":"FRAME: in sport the mark is built of posts and line, a place the ball must reach.","cn":"球门：在体育中，标记由门柱与门线构成，是球必须抵达的位置。"},{"senses":"04 · 07","en":"SCORE: the frame lends its name to the point, including the accidental own goal.","cn":"得分：球门把名字借给那一分，也包括意外的乌龙球。"},{"senses":"05 · 09","en":"MEASURE: a number can be the mark, and the noun can label activity organised around it.","cn":"计量：数字可以成为标记，这个名词也能给围绕标记组织的活动贴标签。"}]},"affixes":{"intro":{"en":"Goal is not built from prefixes or suffixes; it is one noun whose family is made of compounds and a few endings such as -ie, -less and the plural -s.","cn":"goal 不是由前缀或后缀构成的；它是一个单词名词，其词族由合成词和 -ie、-less、复数 -s 等少数词尾组成。"},"latinIntro":{"en":"No Latin source is known. The word appears in English in the 1530s with an uncertain origin, and the three candidates are Old English, Old Norse and Old French.","cn":"没有已知的拉丁语来源。这个词在 16 世纪 30 年代出现于英语，来源不确定，三个候选分别来自古英语、古诺尔斯语与古法语。"},"items":[{"word":"goal","structure":"single noun, origin uncertain","meaning":"an end point, aim, or frame for scoring","meaningCN":"终点；目标；球门","example":"The goal is to finish before noon.","exampleCN":"目标是在中午之前完成。"},{"word":"goals","structure":"goal + -s (plural)","meaning":"more than one goal","meaningCN":"多个目标；多个进球（复数）","example":"The team has scored nine goals this season.","exampleCN":"这支球队本赛季已打进九球。"},{"word":"goalless","structure":"goal + -less (without)","meaning":"with no goal scored","meaningCN":"没有进球的（-less 表示“没有”）","example":"The match ended goalless.","exampleCN":"比赛以零比零结束。"},{"word":"goalie","structure":"goal + -ie (familiar shortening)","meaning":"a goalkeeper","meaningCN":"守门员（-ie 构成亲昵缩略）","example":"The goalie saved the penalty.","exampleCN":"守门员扑出了点球。"},{"word":"goalkeeper","structure":"goal + keeper (compound)","meaning":"the player who guards the goal","meaningCN":"守门员（合成词）","example":"The goalkeeper punched the ball clear.","exampleCN":"守门员把球打了出去。"},{"word":"goalpost","structure":"goal + post (compound)","meaning":"one of the uprights of a goal","meaningCN":"球门柱（合成词）","example":"The shot hit the goalpost.","exampleCN":"那脚射门打中了门柱。"},{"word":"goal line","structure":"goal + line (compound)","meaning":"the line marking the goal","meaningCN":"球门线（合成词）","example":"The ball rolled over the goal line.","exampleCN":"球滚过了球门线。"},{"word":"goal area","structure":"goal + area (compound)","meaning":"the marked area in front of the goal","meaningCN":"球门区（合成词）","example":"The foul happened inside the goal area.","exampleCN":"那次犯规发生在球门区内。"},{"word":"own goal","structure":"own + goal (fixed phrase)","meaning":"a goal scored accidentally against one's own team","meaningCN":"乌龙球（固定搭配）","example":"His own goal put the visitors ahead.","exampleCN":"他的乌龙球让客队领先。"},{"word":"field goal","structure":"field + goal (compound)","meaning":"a score made from the playing field, as in football","meaningCN":"射门得分（美式足球等的场上得分）","example":"They won with a field goal in the final seconds.","exampleCN":"他们在最后几秒靠一次射门得分赢下比赛。"}],"latinEntries":[]}},{"word":"grant","ipa_uk":"/ɡrɑːnt/","ipa_us":"/ɡrænt/","definition_zh":"授予；准予；同意；承认；拨款；补助金","definition_en":"to give or allow something formally, to accept a request as valid, to admit a point, or a sum of money given for a stated purpose","core_image":"一只握有权力的手，把写好的许可或款项递到另一只张开的手里","scene":"The state awarded the university a five-million-dollar grant to restore the salt marsh.","sceneCN":"这里 grant 是「拨款、补助金」（第 6 个义项：政府或机构为特定用途拨出的款项）；句意：州政府向这所大学拨付五百万美元补助金，用于修复盐沼。场景要点：一份写明金额与用途的批文、一片待修复的盐沼、递出批文的手与接住批文的手。","pos":[{"tag":"v.","zh":"授予；准予；同意；承认（某事为真）"},{"tag":"n.","zh":"拨款；补助金；授予物；授予行为"}],"collocations":[{"phrase":"grant permission","zh":"给予许可"},{"phrase":"grant a request","zh":"同意一项请求"},{"phrase":"take something for granted","zh":"认为某事理所当然"},{"phrase":"grant that","zh":"承认（某一事实或论点）"},{"phrase":"a research grant","zh":"研究拨款；科研基金"},{"phrase":"a land grant","zh":"土地授予；政府拨给的土地"},{"phrase":"grant somebody something","zh":"授予某人某物；准予某人某物"}],"forms":[{"label":"第三人称单数","form":"grants"},{"label":"过去式","form":"granted"},{"label":"过去分词","form":"granted"},{"label":"现在分词","form":"granting"}],"derivatives":[{"word":"grantee","pos":"n.","zh":"受让人；被授予者（法律用语）"},{"word":"grantor","pos":"n.","zh":"授予人；让与人（法律用语）"},{"word":"grant-in-aid","pos":"n.","zh":"补助金；财政援助拨款"},{"word":"grantsmanship","pos":"n.","zh":"申请科研经费的技巧；争取拨款的本事"},{"word":"granted","pos":"adj.","zh":"被授予的；（作副词）诚然、不错"}],"senses":[{"no":"01","title":"Hand over a right or privilege","titleCN":"授予权利或特权","definition":"to give a right, privilege, or power to someone in a formal and authoritative way","definitionCN":"以正式而有权威的方式把某项权利、特权或权力给予某人","example":"The crown granted the town the right to hold a weekly market.","exampleCN":"王室授予该镇每周举办集市的特权。","why":"The core act is a handover: whoever holds power writes down what is allowed and passes the document to the receiver. The right now sits in the receiver's hand, but it came from above.","whyCN":"核心动作是一次递交：掌握权力的人把允许的内容写下来，把文书递到接受者手里。权利从此握在接受者手中，但来源在上方。"},{"no":"02","title":"Say yes to a request","titleCN":"准予请求：答应下来","definition":"to agree to give someone what they have asked for, especially in an official setting","definitionCN":"同意给某人其所请求之物，尤指在正式场合","example":"The committee granted her request for an extra week.","exampleCN":"委员会同意了她延长一周的请求。","why":"A request is a hand held out and waiting. Granting is the moment the other hand puts the permission into it, so the answer stops being a word and becomes a thing received.","whyCN":"请求是一只伸出来等待的手。准予就是另一只手把许可放进这只手里，于是答复不再是一句话，而成为被接住的东西。"},{"no":"03","title":"Admit a point in argument","titleCN":"承认：把论点让给对方","definition":"to admit that something is true, often before making a contrasting point","definitionCN":"承认某事为真，常在同之后提出相反论点之前使用","example":"I grant that the evidence is incomplete, but the pattern is clear.","exampleCN":"我承认证据并不完整，但规律已经很清楚。","why":"In an argument a point is something you can own. To grant it is to hand that piece of property to the opponent instead of fighting for it, which is why the word sounds like a concession.","whyCN":"在争论中，一个论点像是可以占有的东西。grant 就是把这件“财物”递给对手，而不是继续争夺，所以这个词听起来像让步。"},{"no":"04","title":"Take for granted: assume without question","titleCN":"视为理所当然：不再追问","definition":"in the phrase take for granted, to accept something as true or available without checking or valuing it","definitionCN":"用于 take for granted，表示不加核实、不加珍惜地认定某事为真或理应存在","example":"Most residents take clean water for granted until the pipes fail.","exampleCN":"多数居民把清洁供水视为理所当然，直到管道出问题才意识到它的可贵。","why":"Something granted once and never questioned is treated as already lying in your hand. Because no new request is made, the gift stops being noticed.","whyCN":"一旦被授予、又从不被追问的东西，就被当作早已握在自己手里。因为不再提出新的请求，这份给予也就不再被看见。"},{"no":"05","title":"Transfer property by legal instrument","titleCN":"以法律文书转让财产","definition":"to transfer the ownership of land or property formally, especially by deed","definitionCN":"以正式文书尤其契据转让土地或财产的所有权","example":"The owner granted the land to the trust in a single deed.","exampleCN":"业主以一纸契据把这块土地转让给了信托机构。","why":"This is the most literal branch: possession itself is handed over, and the deed is the written record of the handover. The word entered English law with exactly this sense around 1300.","whyCN":"这是最字面的一支：被递交的是占有本身，契据则是这次递交的书面记录。这个词在 1300 年前后正是以这个法律义进入英语的。"},{"no":"06","title":"A sum of money given for a purpose","titleCN":"拨款：为特定用途给的钱","definition":"a sum of money given by a government, foundation, or institution for a specific purpose such as research or building","definitionCN":"政府、基金会或机构为研究、建设等特定用途给出的款项","example":"She won a two-year grant to study coastal erosion.","exampleCN":"她获得了一笔为期两年的拨款，用于研究海岸侵蚀。","why":"Money granted by an authority is the same handover in cash. From about 1800 the noun specialised to funds formally voted or awarded for a stated purpose.","whyCN":"权威方拨出的钱是同一场递交，只是交出去的是现金。约从 1800 年起，这个名词专门指正式表决或批给特定用途的资金。"},{"no":"07","title":"The thing granted: land, rights, charters","titleCN":"授予物：土地、权利、特许状","definition":"something that has been granted, such as a piece of land, a charter, or a legal right","definitionCN":"被授予的东西，如一块土地、一份特许状或一项法定权利","example":"The family still farms the land grant given to their ancestor in 1790.","exampleCN":"这家人仍在耕种 1790 年授予其祖先的那块土地。","why":"As a noun the word names what lies in the receiver's hand after the handover. In American English land grants became the dominant example from about 1700.","whyCN":"作名词时，这个词命名递交之后躺在接受者手里的东西。在美式英语中，约从 1700 年起“土地授予”成了最主要的例子。"},{"no":"08","title":"The act of granting: formal bestowal","titleCN":"授予行为：正式的给予","definition":"the act of giving a right, permission, or benefit, especially when spoken of as an official procedure","definitionCN":"给予权利、许可或利益的行为，尤指作为正式程序被提及","example":"The grant of a visa depends on a background check.","exampleCN":"签证的批给取决于背景审查。","why":"The noun can name the action rather than the object: not the paper in the hand but the opening of the hand. This abstract use is recorded from the late 14th century.","whyCN":"这个名词也可以命名动作而非物件：不是手里的那张纸，而是手张开的那一下。这一抽象用法从 14 世纪晚期就有记录。"}],"etymology":{"intro":{"en":"Grant looks like a simple English word but comes from Latin credere 'to believe, trust', through Old French. It is not related to grand. Dates are approximate.","cn":"grant 看起来像个简单的英语词，实际经由古法语来自拉丁语 credere“相信、信任”。它与 grand 没有词源关系。年代为大致估计。"},"items":[{"era":"EARLY 13C.","en":"First recorded as a verb meaning 'to allow, permit; consent to a prayer or request'. The older spelling was graunt.","cn":"最早记录于 13 世纪早期，动词义为“允许、准许；同意一项祈祷或请求”，早期拼作 graunt。"},{"era":"OLD FRENCH","en":"From Old French graanter, a variant of creanter 'to assure, promise, guarantee, swear; confirm, authorize, approve'. The change of c- to g- in Old French is perhaps due to the influence of garantir.","cn":"来自古法语 graanter，是 creanter 的变体，意为“保证、许诺、担保、发誓；确认、授权、批准”。古法语中 c- 变 g- 也许是受 garantir 影响。"},{"era":"LATIN","en":"Old French creanter goes back to Latin credentem, present participle of credere 'to believe, to trust'. A grant was originally something you let someone have because you believed they could be trusted with it.","cn":"古法语 creanter 可追溯到拉丁语 credentem，即 credere“相信、信任”的现在分词。最初，grant 是你因为相信对方可靠而让其拿走的东西。"},{"era":"PROTO-INDO-EUROPEAN","en":"Credere is often traced to the PIE compound *kerd-dhe-, literally 'to put one's heart', from *kerd- 'heart'. The same root gives credo, creed and credible; reconstructed forms are not directly attested.","cn":"credere 常被追溯到原始印欧语复合形式 *kerd-dhe-，字面意为“把心放进去”，来自 *kerd-“心”。同一词根给出 credo、creed、credible；重构形式没有直接文献记录。"},{"era":"C. 1300 · LATE 14C.","en":"Two new senses are recorded around 1300: 'to transfer possession in a formal way' and 'to admit to be true'. Law and argument both borrowed the image of handing something over. By the late 14th century the noun appears meaning 'something granted; authoritative bestowal of a privilege'; an earlier noun use, c. 1200, meant 'allowance, permission'.","cn":"约 1300 年记录到两个新义项：“以正式方式转让占有”和“承认某事为真”。法律与论辩都借用了“把东西递过去”这个意象。到 14 世纪晚期，名词出现，意为“被授予之物；特权之权威授予”；更早的名词用法约在 1200 年，意为“允许、许可”。"},{"era":"1610S · 1700 · 1800","en":"Take for granted is recorded from the 1610s. American land grants become prominent c. 1700, and 'money formally granted by an authority' is recorded c. 1800.","cn":"take for granted 从 17 世纪 10 年代起有记录。美式英语的土地授予约在 1700 年变得突出，“由权威正式拨出的款项”约在 1800 年有记录。"}]},"similar":{"note":{"en":"The first group separates spelling and sound neighbours from the word's real relatives; the second group compares verbs of giving. Grant is not related to grand, whatever the letters suggest.","cn":"第一组把拼写、读音上的邻居与真正的同族词分开；第二组比较表示“给予”的动词。无论字母多像，grant 与 grand 都没有词源关系。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"grand","ipa":"/ɡrænd/","tag":"spelling only","definition":"large, impressive, or most important. It comes from Latin grandis 'big', while grant comes from Latin credere 'believe', so the two words are not related.","definitionCN":"宏大的、壮丽的、重要的。它来自拉丁语 grandis“大”，而 grant 来自拉丁语 credere“相信”，两词并无亲缘关系。"},{"word":"guarantee","ipa":"/ˌɡærənˈtiː/","tag":"look-alike, different root","definition":"a formal promise that something will be done or will work. It comes from a Germanic root meaning 'guard, protect', not from Latin credere, though both words can translate a French garantir.","definitionCN":"保证某事会做到或能正常使用的正式承诺。它来自日耳曼语表示“守护、保护”的词根，并非拉丁语 credere，尽管两者都可能对应法语 garantir。"},{"word":"grantee","ipa":"/ɡrɑːnˈtiː/","tag":"derived form","definition":"the person to whom something is granted. It is grant plus the legal suffix -ee, naming the receiver rather than the act.","definitionCN":"受让人，即被授予某物的人。它是 grant 加法律后缀 -ee，命名接受者而不是动作。"}]},{"heading":"NEAR MEANING","entries":[{"word":"give","ipa":"/ɡɪv/","tag":"plain transfer","definition":"to hand something to someone without payment. Give is the broad everyday verb; grant is formal and implies authority, permission, or a formal procedure.","definitionCN":"把东西无偿交给别人。give 是广义的日常动词；grant 更正式，隐含权威、许可或正式程序。"},{"word":"award","ipa":"/əˈwɔːd/","tag":"after judgment","definition":"to give something officially after a decision, as a prize, contract, or compensation. Award stresses the decision that selects a winner; grant stresses the permission or funding that is handed over.","definitionCN":"经过裁定后正式给予奖品、合同或赔偿。award 强调选出赢家的裁定；grant 强调被递交的许可或资金。"},{"word":"confer","ipa":"/kənˈfɜː/","tag":"formal honour or right","definition":"to give a title, honour, or right formally. It is narrower and more ceremonial than grant, and often collocates with dignity, degree, or benefit.","definitionCN":"正式授予头衔、荣誉或权利。它比 grant 更窄、更典礼化，常与尊严、学位、利益搭配。"},{"word":"bestow","ipa":"/bɪˈstəʊ/","tag":"literary giving","definition":"to give something valuable as a gift, often in a ceremonial or literary tone. Bestow highlights the generosity of the giver; grant highlights the authority behind the giving.","definitionCN":"把珍贵之物作为礼物赠予，常带典礼或文学语气。bestow 突出给予者的慷慨；grant 突出给予背后的权威。"}]}]},"mnemonics":{"normalIntro":{"en":"Real word parts and real relatives: Latin credere 'to believe', the cred- family, and the fixed phrase take for granted.","cn":"只用真实的构词成分与真实同族词：拉丁语 credere“相信”、cred- 词族，以及固定短语 take for granted。"},"normal":[{"en":"Grant and grand are false friends in spelling only: a grand building is big, but a grant is something handed over on trust.","cn":"grant 与 grand 只是拼写上的假朋友：grand 的建筑是宏大的，grant 则是基于信任递出去的东西。"},{"en":"The -ee in grantee marks the receiver and the -or in grantor marks the giver, a pair that also appears in employee / employer.","cn":"grantee 的 -ee 标记接受者，grantor 的 -or 标记给予者，这对后缀也出现在 employee／employer 中。"},{"en":"Take for granted is a real fixed phrase: what you never have to ask for again stops being noticed.","cn":"take for granted 是真正的固定短语：不再需要开口索取的东西，也就不再被看见。"},{"en":"A research grant is money handed over for a stated purpose, usually after a written application.","cn":"research grant 是为明确用途递出的一笔钱，通常要经过书面申请。"},{"en":"Unrelated fact worth knowing: grant shares its root with credible and creed, so a grant was once a thing you could believe in.","cn":"值得知道的不相关事实：grant 与 credible、creed 共享词根，所以 grant 最初是一件“可以相信”的事。"}],"abstract":[{"en":"Picture two hands and one sheet of paper: the upper hand holds the seal, the lower hand is open. Grant is the paper changing hands.","cn":"想象两只手和一张纸：上面的手拿着印章，下面的手张开。grant 就是那张纸换手的一刻。"},{"en":"The same handover can carry a right, an answer to a request, a point in an argument, a piece of land, or a sum of money. The object changes; the gesture does not.","cn":"同一场递交可以送出权利、对请求的答复、争论中的一个论点、一块土地或一笔钱。对象在变，动作不变。"},{"en":"When the handover is repeated so often that no one asks anymore, the gift turns invisible: that is what it means to take something for granted.","cn":"当这场递交重复到无人再开口，礼物就变得看不见了：这就是 take something for granted 的意思。"}]},"examples":[{"en":"The court granted the company a licence to drill, but only for two years.","cn":"法院授予这家公司钻探许可，但期限只有两年。"},{"en":"I grant that the plan is expensive; that does not make it wrong.","cn":"我承认这个计划花费高昂，但这并不等于它是错的。"},{"en":"The grant covered equipment, travel and a full-time research assistant.","cn":"这笔拨款覆盖了设备、差旅和一名全职研究助理的费用。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“格兰特”——格兰特将军大笔一挥，把经费批给实验室 → grant 授予、拨款","word":"grant"},"root":"经古法语来自拉丁语 credere“相信、信任”，核心是“因为信得过，所以把权利、许可或钱正式交到对方手里”。","sensesIntro":{"en":"Eight senses of grant, all grown from one gesture: a hand with authority opens and passes something over — a right, a permission, a conceded point, a piece of land, a sum of money.","cn":"grant 的八个义项都从同一个动作长出来：一只握有权力的手张开，把某样东西递过去——权利、许可、让步的论点、土地或一笔钱。"},"semanticMap":{"core":{"en":"CORE IMAGE: an authorised hand passes a written permission, right or sum to an open hand.","cn":"核心意象：一只获得授权的手，把写好的许可、权利或款项递到张开的手里。"},"chain":["AUTHORITY HOLDS","REQUEST MADE","PERMISSION GIVEN","POSSESSION TRANSFERRED","MONEY ALLOCATED","ASSUMED AS GIVEN"],"branches":[{"senses":"01 · 02","en":"PERMISSION: a right or a request is answered by the same handover, and the receiver now holds what power allowed.","cn":"许可：权利与请求由同一次递交获得答复，接受者现在握有权力所允许的东西。"},{"senses":"03 · 04","en":"ARGUMENT: a point handed to the opponent is a concession; a gift never asked for again becomes invisible and is taken for granted.","cn":"论辩：递给对手的论点就是让步；不再被索取的好意变得隐形，于是被视为理所当然。"},{"senses":"05","en":"PROPERTY: the literal branch, where the deed records possession itself changing hands.","cn":"财产：最字面的一支，契据记录的就是占有本身换了手。"},{"senses":"06 · 07","en":"FUNDING: money or land lies in the receiver's hand after the handover, and the word names that object.","cn":"资金：递交之后，钱或土地躺在接受者手里，名词便命名这件东西。"},{"senses":"08","en":"THE ACT: with the definite article the noun names the opening of the hand rather than the object it carried.","cn":"行为：加定冠词时，名词命名的是手张开的那一下，而不是被递出的物件。"}]},"affixes":{"intro":{"en":"Grant is a verb borrowed whole from Old French, so it has no live English prefix. English adds only legal and everyday suffixes, and the same Latin root supplies a large cred- family.","cn":"grant 是从古法语整体借入的动词，没有活的英语前缀。英语只加法律与日常后缀，而同一拉丁词根又提供了庞大的 cred- 词族。"},"latinIntro":{"en":"The Latin source is credere 'to believe, trust', with participle credens / credentem. Its family includes credo, creed, credit, credible and incredible; the grant branch came through French, where c- turned to g-.","cn":"拉丁语源头是 credere“相信、信任”，分词为 credens／credentem。其词族包括 credo、creed、credit、credible、incredible；grant 这一支经法语传入，并在法语中由 c- 变为 g-。"},"items":[{"word":"grantee","structure":"grant + -ee (person who receives)","meaning":"the person to whom a grant or property is given","meaningCN":"受让人；被授予者（-ee 表示接受动作的人）","example":"The grantee must submit a report every year.","exampleCN":"受让人必须每年提交一份报告。"},{"word":"grantor","structure":"grant + -or (person who gives)","meaning":"the person or body that grants something","meaningCN":"授予人；让与人（-or 表示做出动作的人）","example":"The grantor kept a copy of the deed.","exampleCN":"授予人保留了一份契据副本。"},{"word":"granted","structure":"grant + -ed (past participle, also sentence adverb)","meaning":"given formally; or, as an adverb, 'it is true that'","meaningCN":"被授予的；作副词时表示“诚然、不错”","example":"Granted, the deadline is tight, but the team is ready.","exampleCN":"诚然，截止日期很紧，但团队已经准备好了。"},{"word":"grant-in-aid","structure":"grant + in + aid (compound noun)","meaning":"a sum given by a higher body to support a lower one","meaningCN":"补助金；上级机构给下级机构的财政援助","example":"The university depends on a state grant-in-aid.","exampleCN":"这所大学依赖州政府的补助金。"},{"word":"grantsmanship","structure":"grant + -s + -manship (skill noun)","meaning":"the skill of writing successful funding applications","meaningCN":"争取拨款的本事；申请科研经费的技巧","example":"Her grantsmanship brought the lab three new projects.","exampleCN":"她争取经费的本事为实验室带来了三个新项目。"},{"word":"ungranted","structure":"un- (not) + granted","meaning":"not formally given or allowed","meaningCN":"未获准的；未被授予的（un- 表示否定）","example":"The ungranted request was returned with a short note.","exampleCN":"未获批准的申请被附上一张短笺退回。"},{"word":"credible","structure":"cred- (believe) + -ible (able to be)","meaning":"able to be believed","meaningCN":"可信的；可相信的（同一拉丁词根）","example":"The witness gave a credible account of the night.","exampleCN":"那名证人给出了对当晚可信的叙述。"},{"word":"credit","structure":"cred- (believe) + -it (Latin noun ending)","meaning":"belief or trust; also the system of deferred payment","meaningCN":"信任；信誉；赊购制度（同一词根）","example":"The bank refused to extend further credit.","exampleCN":"银行拒绝再提供赊贷。"},{"word":"creed","structure":"Latin credo 'I believe', nativised","meaning":"a formal statement of belief","meaningCN":"信条；教义（由拉丁语 credo“我相信”演变）","example":"The club's creed is written above the door.","exampleCN":"俱乐部的信条写在门的上方。"},{"word":"incredible","structure":"in- (not) + credible","meaning":"impossible to believe","meaningCN":"难以置信的；不可信的","example":"The scale of the flood was almost incredible.","exampleCN":"洪水的规模几乎令人难以置信。"}],"latinEntries":[{"word":"credere","structure":"cred- + -ere (infinitive)","meaning":"to believe, trust; to entrust","meaningCN":"相信；信任；托付"},{"word":"credens / credentem","structure":"credere + present participle ending","meaning":"believing, trusting (the form behind Old French creanter)","meaningCN":"相信的、信任的（古法语 creanter 背后的形式）"},{"word":"credibilis","structure":"credere + -ibilis (able to be)","meaning":"worthy of belief, believable","meaningCN":"值得相信的；可信的"}]}},{"word":"guarantee","ipa_uk":"/ˌɡærənˈtiː/","ipa_us":"/ˌɡærənˈtiː/","definition_zh":"保证；担保；保修；保修单；担保金","definition_en":"to promise that something will be done or will work, to take responsibility for another's debt, or a formal promise or document that does this","core_image":"一个人把手掌按在契约上，另一只手在背后托底：出了事我来承担","scene":"The manufacturer guarantees the battery for five years, and a written warranty card is printed inside the box.","sceneCN":"这里 guarantee 是「保证（商品质量）」（第 1 个义项：承诺商品在约定时间内正常使用）；句意：厂商为这块电池保证五年，书面保修单就印在包装盒内。场景要点：一块电池、一份写明年限的保修单、厂商按在契约上的手。","pos":[{"tag":"v.","zh":"保证；担保；确保；为……作保"},{"tag":"n.","zh":"保证；保修单；担保；担保金"}],"collocations":[{"phrase":"a money-back guarantee","zh":"退款保证；不满意可退款"},{"phrase":"guarantee against something","zh":"对某种风险提供担保"},{"phrase":"under guarantee","zh":"在保修期内"},{"phrase":"guarantee somebody something","zh":"向某人保证某事物"},{"phrase":"guarantee that","zh":"保证（某事会发生）"},{"phrase":"a written guarantee","zh":"书面保证；保修单"},{"phrase":"guarantee quality","zh":"保证质量"}],"forms":[{"label":"第三人称单数","form":"guarantees"},{"label":"过去式","form":"guaranteed"},{"label":"过去分词","form":"guaranteed"},{"label":"现在分词","form":"guaranteeing"}],"derivatives":[{"word":"guarantor","pos":"n.","zh":"担保人；保证人"},{"word":"guaranty","pos":"n.","zh":"担保；保证书（法律用语）"},{"word":"guaranteed","pos":"adj.","zh":"有保证的；保证的"},{"word":"unguaranteed","pos":"adj.","zh":"无担保的；无保证的"}],"senses":[{"no":"01","title":"Promise that a product will work","titleCN":"保证商品能用：质量承诺","definition":"to promise that a product or service will work properly for a stated period, and to offer repair or replacement if it does not","definitionCN":"承诺商品或服务在约定期间内正常运作，若不能则提供修理或更换","example":"The company guarantees its headphones for two years.","exampleCN":"这家公司为耳机提供两年保证。","why":"The core image is a hand pressed on a contract with another hand supporting it from behind. Applied to goods, the seller puts his hand on the product and says: if it fails, the cost lands on me.","whyCN":"核心意象是一只手按在契约上，另一只手在背后托底。用在商品上，就是卖家把手按在产品上说：若它坏了，代价落在我身上。"},{"no":"02","title":"Stand behind another person's debt","titleCN":"为他人的债务作保","definition":"to accept legal responsibility for another person's debt or obligation if that person fails to pay or perform","definitionCN":"若他人未能付款或履约，则依法承担其债务或义务的责任","example":"Her uncle guaranteed the loan so the bank would approve it.","exampleCN":"她叔叔为这笔贷款作保，银行才肯批准。","why":"Here the supporting hand becomes legal: the guarantor stands behind the borrower, and the lender may reach the guarantor when the borrower defaults. This is the financial and legal centre of the word.","whyCN":"这里托底的手变成了法律责任：担保人站在借款人身后，借款人违约时债权人可以伸手找他。这是这个词在金融和法律上的中心义。"},{"no":"03","title":"Make a result certain","titleCN":"确保结果：使必然发生","definition":"to make something certain to happen or to ensure that a condition is met","definitionCN":"使某事必然发生，或确保某一条件得到满足","example":"Careful planning does not guarantee success, but it improves the odds.","exampleCN":"周密计划不能确保成功，但能提高胜算。","why":"The promise is now directed at an outcome rather than a product: the speaker puts his hand behind the future and says the result will not be allowed to fail.","whyCN":"这时承诺指向的不是产品而是结果：说话者把手托在未来背后，表示不会让这个结果落空。"},{"no":"04","title":"The document: a warranty card","titleCN":"保修单：写在纸上的保证","definition":"a written document in which a seller promises to repair or replace a product within a fixed period","definitionCN":"卖方承诺在固定期限内修理或更换产品的书面文件","example":"Keep the guarantee; you will need it if the screen breaks.","exampleCN":"把保修单留着；屏幕要是坏了就用得上。","why":"The hand on the contract leaves a mark: the promise becomes a paper you can hold. In British usage this everyday sense is usually spelled guarantee rather than guaranty.","whyCN":"按在契约上的手会留下痕迹：承诺变成一张可以握在手里的纸。在英式用法中，这个日常义通常写作 guarantee，而不是 guaranty。"},{"no":"05","title":"The promise itself","titleCN":"保证：承诺本身","definition":"a firm promise that something will be done, given, or will happen","definitionCN":"关于某事会被做到、给予或发生的坚定承诺","example":"There is no guarantee that the train will arrive on time.","exampleCN":"无法保证火车会准点到达。","why":"The noun can name the promise without any paper or money attached. The hands are still there, but what they hold is only the word given.","whyCN":"名词可以命名没有任何纸张或金钱附着的承诺。手仍在，但手里握着的只是给出的那句话。"},{"no":"06","title":"The person who gives security","titleCN":"担保人：最早的名词义","definition":"a person who gives security for another's obligation; the original 17th-century sense of the noun","definitionCN":"为他人的义务提供担保的人；这是 17 世纪名词的最初义","example":"In the old contract, the guarantee was the merchant who stood surety for the shipment.","exampleCN":"在那份旧合同里，担保人是为这批货物作保的商人。","why":"English borrowed the word first as a name for a person, not a thing: the one who stands behind. The modern 'pledge' sense of the noun developed only in the 18th century.","whyCN":"英语最初借入这个词时，它指的是人而不是物：站在后面托底的那一位。名词现代“保证、担保”的义项到 18 世纪才发展出来。"},{"no":"07","title":"Security deposited: the guaranty","titleCN":"担保金：交出的保证金","definition":"money or property deposited as security that an obligation will be met","definitionCN":"为保证义务得到履行而交存的金钱或财产","example":"Under the lease, the tenant's deposit serves as a guarantee for unpaid rent.","exampleCN":"根据租约，租客的押金用作欠租的担保。","why":"The supporting hand is replaced by something tangible left with the other side. What is held as security is the physical form of standing behind someone.","whyCN":"托底的手被换成留在对方手里的实物。被扣押作为担保的东西，就是“站在某人身后”的实体形态。"},{"no":"08","title":"Colloquial certainty: I guarantee you","titleCN":"口语断定：我敢肯定","definition":"in informal speech, used to express strong confidence that something is true or will happen","definitionCN":"在口语中表达对某事为真或将会发生的强烈确信","example":"I guarantee you she will change her mind before Friday.","exampleCN":"我敢肯定，周五之前她会改变主意。","why":"The same promise is reduced to a conversational flourish: no contract, no money, only the speaker's hand behind the statement. It signals confidence rather than legal liability.","whyCN":"同一个承诺被压缩成口语里的强调：没有契约、没有钱，只有说话者托在陈述背后的那只手。它传达的是确信，而不是法律责任。"}],"etymology":{"intro":{"en":"Guarantee is a Germanic word that entered English through Old French, then was reshaped by legal spelling habits. It is not from Latin, and its history is tangled with guaranty, warrant and warranty.","cn":"guarantee 是一个经由古法语进入英语的日耳曼词，后来又被法律拼写习惯改写。它并非来自拉丁语，其历史与 guaranty、warrant、warranty 纠缠在一起。"},"items":[{"era":"EARLY 15C.","en":"The earlier form garrant is recorded meaning 'a warrant that the title to a property is true'. Its business was real estate, not consumer goods.","cn":"更早的形式 garrant 有记录，意为“证明财产所有权真实的保证书”。它最初处理的是不动产，而不是消费品。"},{"era":"OLD FRENCH","en":"From Old French garant 'defender, protector; warranty; pledge; justifying evidence'. The word named a person before it named a promise.","cn":"来自古法语 garant，意为“保护者、辩护者；保证；担保物；可作为依据的证据”。这个词先指人，后指承诺。"},{"era":"GERMANIC ROOT","en":"The French word goes back to a Germanic source, Proto-Germanic *war- 'to warn, guard, protect', from PIE *wer- 'to cover'. The same family gives warrant, warranty, ward, warden and guard.","cn":"这个法语词可追溯到日耳曼语源，原始日耳曼语 *war-“警告、守护、保护”，来自原始印欧语 *wer-“覆盖”。同一词族给出 warrant、warranty、ward、warden 和 guard。"},{"era":"1590S · GUARANTY","en":"Guaranty is recorded in the 1590s as 'the act of guaranteeing, being answerable for another's obligations', influenced by French garantie.","cn":"guaranty 在 16 世纪 90 年代有记录，意为“担保行为、为他人的义务负责”，受法语 garantie 影响。"},{"era":"1670S · GUARANTEE","en":"Guarantee appears in the 1670s meaning 'person that gives security'. It was altered, perhaps through Spanish garante or by confusion with the legal ending -ee, from the older garrant.","cn":"guarantee 于 17 世纪 70 年代出现，意为“提供担保的人”。它由较早的 garrant 改写而来，也许经由西班牙语 garante，或受法律后缀 -ee 的混淆影响。"},{"era":"18C. · 1791 · 1811","en":"The sense 'pledge given as security' developed in the 18th century, properly the territory of guaranty. The verb 'to be surety for' is recorded from 1791, though garanten in that sense dates from the early 15th century. Guarantor is coined in 1811 by replacing the -ee of guarantee with the Latin agent ending -or, which restored a clear word for the person who guarantees.","cn":"“作为担保的承诺”这一义项在 18 世纪发展出来，这本来是 guaranty 的领地。动词“为……作保”记录于 1791 年，尽管 garanten 的这个义项可追溯到 15 世纪早期。guarantor 于 1811 年被造出，用拉丁语施事后缀 -or 替换 guarantee 的 -ee，从而恢复了一个明确指“担保人”的词。"}]},"similar":{"note":{"en":"The first group is a legal spelling trap: four words that all sound like 'a promise about risk'. The second group compares promises by strength and by who carries the cost.","cn":"第一组是法律拼写陷阱：四个词听起来都像“关于风险的承诺”。第二组按承诺的强度与“谁承担代价”来比较。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"guaranty","ipa":"/ˈɡærənti/","tag":"legal twin","definition":"the legal noun for the act of guaranteeing or the security given. In modern usage it survives mainly in law and in fixed phrases, while guarantee covers both the promise and the document.","definitionCN":"表示担保行为或所给担保物的法律名词。现代用法中它主要留在法律文本与固定短语里，而 guarantee 同时覆盖承诺与文件。"},{"word":"warranty","ipa":"/ˈwɒrənti/","tag":"product document","definition":"a seller's written promise to repair or replace a product. It is the usual word for the document in North American English, while British shops often say guarantee.","definitionCN":"卖方修理或更换产品的书面承诺。在北美英语中它是这类文件最常用的词，而英国商店常说 guarantee。"},{"word":"warrant","ipa":"/ˈwɒrənt/","tag":"authorisation, not promise","definition":"a document giving official authority, such as a search or arrest warrant. It shares the same Germanic root but names permission to act, not a promise to bear a loss.","definitionCN":"授予官方权力的文书，如搜查令或逮捕令。它共享同一日耳曼词根，但命名的是行动授权，而不是承担损失的承诺。"},{"word":"guarantor","ipa":"/ˌɡærənˈtɔː/","tag":"person, not thing","definition":"the person or institution that stands behind a debt. Guarantee can also mean this in older texts, but guarantor is now the unambiguous term.","definitionCN":"站在债务背后的人或机构。较早文本中 guarantee 也可指此，但 guarantor 现在是不会歧义的词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"assure","ipa":"/əˈʃʊə/","tag":"remove doubt","definition":"to tell someone confidently that something is true, so as to remove their worry. Assure works on a person's mind; guarantee adds responsibility for the outcome.","definitionCN":"有把握地告诉某人某事为真，以消除其担忧。assure 作用于人的心理；guarantee 则追加了对结果的责任。"},{"word":"pledge","ipa":"/pledʒ/","tag":"solemn promise","definition":"to make a serious or public promise, often to give money or support. Pledge is about the honour of the promise; guarantee is about the liability behind it.","definitionCN":"作出严肃或公开的承诺，常指捐款或支持。pledge 关乎承诺的道义；guarantee 关乎承诺背后的责任。"},{"word":"promise","ipa":"/ˈprɒmɪs/","tag":"general word","definition":"to say that one will do something. It is the broad everyday verb; guarantee is stronger and usually carries legal or financial weight.","definitionCN":"表示自己将会做某事。它是最宽泛的日常动词；guarantee 更强，通常带有法律或金钱上的分量。"},{"word":"vouch","ipa":"/vaʊtʃ/","tag":"testify for someone","definition":"to confirm from personal knowledge that someone or something is reliable. Vouch speaks about character or truth; guarantee speaks about performance or payment.","definitionCN":"凭亲身了解确认某人或某物可靠。vouch 说的是品行或真实性；guarantee 说的是性能或付款。"}]}]},"mnemonics":{"normalIntro":{"en":"Real word parts and real relatives: Old French garant, the Germanic war- family (warrant, ward, guard), and the legal pair guaranty / guarantor.","cn":"只用真实构词成分与真实同族词：古法语 garant、日耳曼语 war- 词族（warrant、ward、guard），以及法律成对的 guaranty／guarantor。"},"normal":[{"en":"Guarantee and warranty are relatives: both descend from a Germanic word for guarding, so both describe someone standing guard behind a promise.","cn":"guarantee 与 warranty 是亲戚：两者都出自日耳曼语表示“守护”的词，因此都描述有人守在承诺背后。"},{"en":"Guaranty is the legal twin: when a contract says guaranty, a lawyer sees the obligation; when a shop says guarantee, a customer sees the promise.","cn":"guaranty 是法律上的孪生词：合同写 guaranty 时，律师看到的是义务；商店说 guarantee 时，顾客看到的是承诺。"},{"en":"The -ee of guarantee first marked a person, which is why the 17th-century noun meant 'the one who gives security'. Guarantor was later coined to make that sense clear again.","cn":"guarantee 的 -ee 最初标记的是人，所以 17 世纪的名词义是“提供担保的人”。后来才造出 guarantor 重新把这个意思说清楚。"},{"en":"Under guarantee is a real shop phrase: the product is still inside the period during which the seller bears the cost.","cn":"under guarantee 是真实的商店用语：产品仍处在卖方承担代价的期限之内。"},{"en":"A money-back guarantee is the clearest everyday form: if the thing fails, the money comes back to your hand.","cn":"money-back guarantee 是最清晰的日常形式：东西不行，钱就回到你手里。"}],"abstract":[{"en":"Picture two people signing: the one in front signs, the one behind rests a hand on his shoulder. Guarantee is that hand on the shoulder.","cn":"想象两个人签字：前面的人落笔，后面的人把手搭在他肩上。guarantee 就是那只搭在肩上的手。"},{"en":"The supporting hand can take three forms: a promise in words, a paper in the box, or money left on the table. All three say the same thing — the loss will not stop with you.","cn":"这只托底的手可以有三副样子：口头承诺、盒里的纸、留在桌上的钱。三者说的都是同一句话——损失不会停在你这里。"},{"en":"When the hand is withdrawn, the promise is still spoken but no one stands behind it: that is the difference between a guarantee and a mere hope.","cn":"当这只手撤走，承诺仍被说出，但身后无人托底：这就是 guarantee 与单纯希望的区别。"}]},"examples":[{"en":"The bank will not lend to the startup unless a parent company guarantees the debt.","cn":"除非有母公司为这笔债务作保，否则银行不会借钱给这家初创企业。"},{"en":"A fixed diet does not guarantee weight loss if sleep is ignored.","cn":"如果忽视睡眠，固定饮食也不能确保体重下降。"},{"en":"She kept every receipt and guarantee in a folder labelled by appliance.","cn":"她把每张收据和保修单都放在按电器分类的文件夹里。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“瓜兰替”——瓜兰替你把货款垫上，坏了算他的 → guarantee 保证、担保","word":"guarantee"},"root":"经古法语 garant“保护者、保证”上溯到日耳曼语 *war-“守护、警告”，核心是“站在别人身后替他兜底”。","sensesIntro":{"en":"Eight senses of guarantee, all grown from one posture: someone stands behind a promise with a hand ready to take the loss, whether the promise covers a product, a debt, a result, or a spoken claim.","cn":"guarantee 的八个义项都从同一个姿态长出来：有人站在承诺背后，手伸出来准备接住损失——不论承诺覆盖的是产品、债务、结果，还是一句口头断言。"},"semanticMap":{"core":{"en":"CORE IMAGE: a second hand rests behind the hand that signs, ready to take the loss.","cn":"核心意象：第二只手搭在签字那只手的背后，随时准备接住损失。"},"chain":["PROMISE MADE","SOMEONE STANDS BEHIND","LOSS ACCEPTED","DEBT SECURED","RESULT MADE CERTAIN","DOCUMENT OR DEPOSIT"],"branches":[{"senses":"01 · 05","en":"PROMISE: a product or a general claim is backed by a word given, and the seller accepts the cost if the word fails.","cn":"承诺：产品或一般性断言由一句给出的保证支撑，若承诺落空，卖方接受代价。"},{"senses":"02 · 06 · 07","en":"SECURITY: the supporting hand becomes a legal person, then a sum of money, standing behind another's debt.","cn":"担保：托底的手先变成法律上的人，再变成一笔钱，站在他人债务的背后。"},{"senses":"03","en":"CERTAINTY: the hand moves from a thing to a future result, making the outcome impossible to fail.","cn":"确定：手从物件移向未来结果，使结局不可能落空。"},{"senses":"04","en":"PAPER: the hand leaves its mark, and the promise becomes a document kept in the box.","cn":"纸张：手留下痕迹，承诺变成一张收在盒里的文件。"},{"senses":"08","en":"SPEECH: with no contract or money, only the tone of confidence remains: 'I guarantee you.'","cn":"口语：没有契约也没有钱，只剩确信的语气：“我敢肯定。”"}]},"affixes":{"intro":{"en":"Guarantee has no Latin prefix to unpack; it arrived from Old French as a whole word. English adds -or, -y and un-, while the Germanic root spreads across a large family of guarding words.","cn":"guarantee 没有可拆解的拉丁前缀；它是作为整词从古法语进入英语的。英语加上 -or、-y 和 un-，而日耳曼词根散布在一个庞大的“守护”词族里。"},"latinIntro":{"en":"There is no native Latin ancestor. Medieval Latin legal texts borrowed the Germanic stem as garantia or warantia, and those spellings fed both guarantee and warranty.","cn":"它没有本土的拉丁语祖先。中世纪拉丁法律文本把这一日耳曼词干借作 garantia 或 warantia，这两种拼写同时滋养了 guarantee 与 warranty。"},"items":[{"word":"guarantor","structure":"guarantee + -or (agent noun, replacing -ee)","meaning":"the person who guarantees another's obligation","meaningCN":"担保人；保证人（-or 表示施事者）","example":"The guarantor must sign every page of the loan.","exampleCN":"担保人必须在贷款的每一页上签字。"},{"word":"guaranty","structure":"guarant- + -y (abstract noun)","meaning":"the act of guaranteeing, or the security given","meaningCN":"担保行为；担保物（-y 构成抽象名词）","example":"The treaty of guaranty was registered with the court.","exampleCN":"这份担保契约已在法院登记。"},{"word":"guaranteed","structure":"guarantee + -ed (past participle and adjective)","meaning":"covered by a guarantee; certain to happen","meaningCN":"有保证的；必定发生的（-ed 构成分词与形容词）","example":"The seat is guaranteed once the deposit is paid.","exampleCN":"一旦付了定金，座位就有保证。"},{"word":"unguaranteed","structure":"un- (not) + guaranteed","meaning":"not covered by any guarantee","meaningCN":"无担保的；无保证的（un- 表示否定）","example":"Unguaranteed loans carry a much higher interest rate.","exampleCN":"无担保贷款的利率要高得多。"},{"word":"warrant","structure":"Old French warant, same Germanic root","meaning":"official authorisation; to justify or guarantee","meaningCN":"授权令；使有正当理由（同一日耳曼词根）","example":"The judge issued a warrant for the search.","exampleCN":"法官签发了搜查令。"},{"word":"warranty","structure":"warrant + -y (noun)","meaning":"a seller's written promise about a product","meaningCN":"保修单；质量保证书（同一词根加 -y）","example":"The warranty does not cover accidental damage.","exampleCN":"保修单不涵盖意外损坏。"},{"word":"guardian","structure":"Old French gardien, from the same guard- family","meaning":"a person who legally protects another","meaningCN":"监护人；保护者","example":"Her aunt became her legal guardian.","exampleCN":"她的姑妈成了她的法定监护人。"},{"word":"warden","structure":"Old French wardein, from ward- 'guard'","meaning":"an official who guards a place or group","meaningCN":"看守人；管理员","example":"The park warden closed the trail after the storm.","exampleCN":"风暴过后，公园管理员关闭了那条步道。"},{"word":"wary","structure":"ware + -y (careful, from the same 'guard' sense)","meaning":"cautious because of possible danger","meaningCN":"警惕的；谨慎的","example":"Investors are wary of promises that sound too easy.","exampleCN":"投资者对听起来太容易的承诺保持警惕。"},{"word":"beware","structure":"be- + ware (to be on one's guard)","meaning":"to be careful of a danger","meaningCN":"当心；提防","example":"Beware of contracts with no named guarantor.","exampleCN":"当心没有写明担保人的合同。"}],"latinEntries":[{"word":"garantia","structure":"Medieval Latin, from Germanic *war-","meaning":"warranty, security, a pledge given in law","meaningCN":"担保；保证；法律上给出的承诺（中世纪拉丁借自日耳曼语）"},{"word":"warantia","structure":"Medieval Latin variant of garantia","meaning":"a warrant or warranty; a defending pledge","meaningCN":"保证书；辩护性的担保（garantia 的中世纪拉丁变体）"}]}},{"word":"guideline","ipa_uk":"/ˈɡaɪdlaɪn/","ipa_us":"/ˈɡaɪdlaɪn/","definition_zh":"指导方针；准则；指导原则；（裁剪或施工用的）基准线","definition_en":"an official or advisory principle that suggests how something should be done, or a line marked to guide cutting or placement","core_image":"有人在地上先画出一条浅线，后来的人顺着它走，却仍可略微偏离","scene":"The agency issued new guidelines on boat speed near the reef, but they remain advisory.","sceneCN":"这里 guideline 是「建议性的指导原则」（第 1 个义项：提出应当如何做的建议，而非强制命令）；句意：该机构就礁石附近船只速度发布了新指导原则，但这些原则仍属建议性质。场景要点：一张写着建议航速的说明、礁石附近的水道、可被越过的浅色参考线。","pos":[{"tag":"n.","zh":"指导方针；准则；指导原则（常用复数）"},{"tag":"n.","zh":"基准线；参考线（裁剪、制图或施工用语）"}],"collocations":[{"phrase":"follow the guidelines","zh":"遵循指导方针"},{"phrase":"issue guidelines","zh":"发布准则"},{"phrase":"guidelines on something","zh":"关于某事的指导原则"},{"phrase":"safety guidelines","zh":"安全准则"},{"phrase":"clinical guidelines","zh":"临床指南"},{"phrase":"draw a guideline","zh":"画一条基准线"},{"phrase":"guidelines recommend that","zh":"指南建议（应当……）"}],"forms":[{"label":"复数","form":"guidelines"}],"derivatives":[{"word":"guidance","pos":"n.","zh":"指导；引导；导航"},{"word":"guidebook","pos":"n.","zh":"指南；旅行手册"},{"word":"guidepost","pos":"n.","zh":"路标；指示标志"},{"word":"guided","pos":"adj.","zh":"有指导的；制导的"},{"word":"guiding","pos":"adj.","zh":"指导性的；起引导作用的"},{"word":"misguide","pos":"v.","zh":"误导；把……引错方向"}],"senses":[{"no":"01","title":"Advisory principle, not a command","titleCN":"建议性指导原则：不是命令","definition":"a principle or piece of advice that indicates the preferred way to act but does not legally compel it","definitionCN":"指出较可取做法但并不具法律强制力的原则或建议","example":"The guidelines suggest limiting screen time, but schools may set their own rules.","exampleCN":"指导原则建议限制屏幕时间，但各校可以自定规则。","why":"The image is a faint line drawn on a surface: it shows where to go, but a steady hand can still cut slightly beside it. That is why a guideline advises rather than orders.","whyCN":"这个意象是表面上一道浅线：它指出该往哪走，但稳当的手仍可以在旁边一点下刀。因此 guideline 是建议而非命令。"},{"no":"02","title":"An institution's operating rules","titleCN":"机构的操作准则","definition":"a set of written points produced by an organisation to make its procedures consistent","definitionCN":"由组织制定的一组书面要点，用以统一其操作程序","example":"The lab's guidelines require two people to sign before a sample is stored.","exampleCN":"实验室的准则要求样本入库前须有两人签字。","why":"Once many hands work on the same task, the line has to be drawn by someone in authority so that everyone follows the same path. The metaphor moves from a single cutter to an organisation.","whyCN":"当许多人在同一件事上动手，这条线就必须由有权威的人来画，大家才能走同一条路。比喻从单个下刀的人移到了组织。"},{"no":"03","title":"Government policy guidance","titleCN":"政府的政策指导方针","definition":"official advice issued by a government or regulator that shapes how a policy is applied in practice","definitionCN":"政府或监管机构发布的正式建议，影响某项政策在实际中如何执行","example":"New guidelines on air quality tell cities how to measure pollution.","exampleCN":"新的空气质量指导方针告诉各城市如何测量污染。","why":"The line is now drawn across a whole country: it does not itself make law, but it steers thousands of local decisions into one direction.","whyCN":"这道线现在画遍全国：它本身不制定法律，却把成千上万个地方决定引向同一个方向。"},{"no":"04","title":"Clinical guidelines in medicine","titleCN":"医学临床指南","definition":"a systematically developed statement that helps doctors decide on appropriate care for specific conditions","definitionCN":"系统编写的陈述，帮助医生就特定病情决定适当的诊疗方案","example":"The clinical guidelines recommend antibiotics only for confirmed bacterial cases.","exampleCN":"临床指南建议只对确诊的细菌性病例使用抗生素。","why":"Here the line is drawn through a body of evidence: it marks the path that studies support, while leaving room for a doctor to judge the individual patient.","whyCN":"这里这条线是穿过一堆证据画出的：它标出研究支持的路径，同时给医生留出判断具体病人的余地。"},{"no":"05","title":"A reference line in design","titleCN":"设计中的参考线","definition":"a visible or invisible line used in layout, typography, or drawing to align elements","definitionCN":"在版式、字体或绘图中用来对齐元素的可见或不可见线条","example":"The designer moved the logo until it sat exactly on the guideline.","exampleCN":"设计师移动标志，直到它正好落在参考线上。","why":"This is the visual version of the original sense: not advice about behaviour but a literal line that tells the eye where an edge should fall.","whyCN":"这是原义在视觉上的版本：不是关于行为的建议，而是一条字面的线，告诉眼睛边缘应当落在哪里。"},{"no":"06","title":"The original craft line","titleCN":"最初的工艺基准线","definition":"a line marked on paper, wood, or cloth before cutting, so that the cut stays straight","definitionCN":"在纸、木或布上先画出的线，以便下刀时保持笔直","example":"The tailor chalked a guideline before cutting the wool.","exampleCN":"裁缝在剪羊毛料之前先用粉笔画了一条基准线。","why":"This is the 1785 sense, and the source of the whole metaphor: a line exists before the work begins, so that the hand has something to follow.","whyCN":"这是 1785 年的义项，也是整个比喻的源头：线在工作开始之前就存在，让手有东西可以跟随。"},{"no":"07","title":"A boundary for judgment","titleCN":"判断的准绳与界限","definition":"a standard used to judge whether an action or claim has gone too far","definitionCN":"用来判断某一行为或说法是否越界的标准","example":"Honesty is the guideline he applies when a story begins to grow in the telling.","exampleCN":"当故事在讲述中开始添枝加叶时，诚实就是他用来衡量的准绳。","why":"The faint line becomes a limit: it does not tell you every step, but it shows where the acceptable area ends. Guideline and boundary meet in this figurative sense.","whyCN":"浅线在这里变成界限：它不规定每一步，却显示可接受的范围到哪里为止。guideline 与「界限」在这个比喻义上相遇。"},{"no":"08","title":"Historical: a balloon's steering rope","titleCN":"历史义：热气球的操纵绳","definition":"in 19th-century ballooning, a rope used to steer or control the craft; now historical","definitionCN":"在 19 世纪热气球飞行中用来操纵或控制飞行器的绳索；现已成历史义","example":"The old print shows a crew hauling on the guideline to shift the balloon's course.","exampleCN":"那幅旧版画描绘机组人员拉动手中的操纵绳，以改变气球航向。","why":"For a while the word meant a real rope that guided a real vehicle. The 1846 balloon sense shows the compound still being used for physical steering before it turned abstract.","whyCN":"有一个时期，这个词指的是一条真正牵引真实交通工具的绳子。1846 年的热气球义显示，这个复合词在转向抽象之前仍用于物理操纵。"}],"etymology":{"intro":{"en":"Guideline is a transparent English compound of guide and line, first used for a craft line and only later for advice. Dates are from dictionary records and are approximate.","cn":"guideline 是 guide 与 line 构成的透明英语复合词，最初指工艺上的线，后来才指建议。年代取自词典记录，为大致估计。"},"items":[{"era":"1785","en":"First recorded as 'a line marked on a surface before cutting'. The word belonged to tailoring, carpentry and drawing, not to policy.","cn":"最早记录为“在表面上先画出的、供下刀时遵循的线”。这个词属于裁缝、木工与制图，而不属于政策。"},{"era":"1846","en":"Recorded meaning 'a rope for steering a hot-air balloon'. The compound was still physical: a line that actually turned something.","cn":"记录到“操纵热气球的绳索”这一义项。复合词仍是物理的：一条真正能让东西转向的线。"},{"era":"LATE 14C. · GUIDE","en":"Guide comes from Old French guider 'to lead, direct, conduct', earlier guier, probably from Frankish *witan 'show the way', from PIE *weid- 'to see'.","cn":"guide 来自古法语 guider“引领、指引、带领”，更早作 guier，可能出自法兰克语 *witan“指路”，可追溯到原始印欧语 *weid-“看见”。"},{"era":"LATIN · LINE","en":"Line comes from Latin linea 'linen thread, string, plumb-line', also 'a mark, bound, limit'. A builder's cord was the first instrument for keeping work straight.","cn":"line 来自拉丁语 linea“亚麻线、绳、铅垂线”，也指“标记、边界、界限”。工匠的绳是让工程保持笔直的最初工具。"},{"era":"1948","en":"The figurative sense 'principle or advice' is recorded by 1948. After the Second World War, institutions needed a word for rules that guided without commanding.","cn":"“原则或建议”的比喻义到 1948 年有记录。二战后，机构需要一个词来描述“引导但不强制”的规则。"},{"era":"LATE 20C.","en":"Guidelines become a standard genre: clinical guidelines, safety guidelines, style guidelines. The plural is usual because such documents come as a set of points.","cn":"guideline 在 20 世纪后期成为一种标准文体：临床指南、安全准则、体例指南。通常用复数，因为这类文件总是以一组要点出现。"}]},"similar":{"note":{"en":"The first group separates the compound from the words built on the same guide element; the second group compares four words that all tell people how to act, with very different force.","cn":"第一组把复合词与由同一 guide 成分构成的词分开；第二组比较四个都告诉人该怎么做的词，但强制力差别很大。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"guide","ipa":"/ɡaɪd/","tag":"base word, person or verb","definition":"a person who leads others, or the verb 'to lead'. A guide can be a human being; a guideline is never a person and never acts.","definitionCN":"领路的人，或动词“引导”。guide 可以指活人；guideline 永远不是人，也不会行动。"},{"word":"guidance","ipa":"/ˈɡaɪdns/","tag":"abstract noun","definition":"the act or process of guiding, especially advice given to someone who is deciding. Guidance is the help; a guideline is one written item of that help.","definitionCN":"引导的行为或过程，尤指给正在做决定的人的建议。guidance 是帮助本身；guideline 是这类帮助中一条写下来的内容。"},{"word":"guidepost","ipa":"/ˈɡaɪdpəʊst/","tag":"physical sign","definition":"a post marking a route or direction. It is a physical object, whereas guideline is usually a principle and only rarely a drawn line.","definitionCN":"标示路线或方向的柱子。它是实物，而 guideline 通常是原则，只有少数情况下才指画出的线。"},{"word":"line","ipa":"/laɪn/","tag":"second element","definition":"a long thin mark, or a boundary. Guideline borrows this element, but line alone carries no advice.","definitionCN":"细长的标记，或边界。guideline 借用了这个成分，但单说 line 并不含建议。"}]},{"heading":"NEAR MEANING","entries":[{"word":"rule","ipa":"/ruːl/","tag":"binding","definition":"a stated instruction about what is allowed, usually enforced. A rule can be broken and punished; a guideline can be departed from without penalty.","definitionCN":"关于允许做什么的明确规定，通常会被执行。违反 rule 可能受罚；偏离 guideline 通常不受处罚。"},{"word":"standard","ipa":"/ˈstændəd/","tag":"measure of quality","definition":"a level of quality or a technical specification that something is measured against. A standard is a benchmark; a guideline is a suggested path.","definitionCN":"用来衡量事物的质量水平或技术规范。standard 是基准；guideline 是建议的路径。"},{"word":"principle","ipa":"/ˈprɪnsəpl/","tag":"underlying value","definition":"a basic truth or value that underlies many decisions. A principle is general and internal; a guideline is specific and often published.","definitionCN":"支撑许多决定的基本真理或价值。principle 是一般性的、内在的；guideline 是具体的，且往往被公开发布。"},{"word":"recommendation","ipa":"/ˌrekəmenˈdeɪʃn/","tag":"advice","definition":"a suggestion that something would be good to do. It is close to guideline in force, but a recommendation is one piece of advice, not a published set of principles.","definitionCN":"认为某事值得去做的建议。它在强制力上与 guideline 接近，但 recommendation 是单条建议，不是一整套公开发布的原则。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: guide + line, the guide family, and the Latin linea behind line.","cn":"只用真实成分与真实同族词：guide + line、guide 词族，以及 line 背后的拉丁语 linea。"},"normal":[{"en":"Guideline is literally 'guide line': a line that guides. Keep that picture and the difference from rule becomes easy — a line can be stepped over.","cn":"guideline 字面就是“引导的线”。记住这幅图，它与 rule 的差别就清楚了——线是可以跨过去的。"},{"en":"The word is almost always plural in policy writing because guidance comes as a list of numbered points.","cn":"在政策文本里这个词几乎总用复数，因为指导内容总是以一组编号要点出现。"},{"en":"Guidance is the help, guide is the helper, guideline is one written item of help: three roles of the same root.","cn":"guidance 是帮助，guide 是帮助者，guideline 是帮助中的一条书面内容：同一词根的三种角色。"},{"en":"A guidepost is a physical post by a road; a guideline is the same idea turned into advice for behaviour.","cn":"guidepost 是路边的实物柱子；guideline 则是同一想法转成了行为建议。"},{"en":"In design software a guideline is a draggable line that does not print: it guides placement without becoming part of the picture.","cn":"在设计软件里，guideline 是一条可拖动、不会被打印出来的线：它引导摆放，却不成为画面的一部分。"}],"abstract":[{"en":"Picture a tailor's chalk line on dark cloth: bright enough to follow, faint enough to be ignored. Guideline is that line promoted into language.","cn":"想象深色布料上一道粉笔线：亮到足以跟随，淡到可以被忽略。guideline 就是这条线被提升成了语言。"},{"en":"The line never carries the cutter's hand. It only shows where the edge should fall, which is exactly what advice can and cannot do.","cn":"这条线从不替下刀的手用力，它只显示边缘应落在哪里——这正是建议能做到和不能做到的事。"},{"en":"When an authority draws the line for thousands of people, the craft line becomes policy: the same faint mark, now steering institutions.","cn":"当权威替成千上万人画这条线，工艺线就变成了政策：仍是那道浅痕，如今却在引导机构。"}]},"examples":[{"en":"The ministry's guidelines are not law, but hospitals that ignore them must explain why.","cn":"该部的指导方针不是法律，但无视它们的医院必须说明理由。"},{"en":"She drew a guideline along the edge of the page before ruling the margin.","cn":"她在页边画了一条基准线，然后再画页边线。"},{"en":"Ethical guidelines cannot decide every case; they mark where the argument should begin.","cn":"伦理准则无法裁定每个个案，它们标出讨论应当从哪里开始。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“盖德莱恩”——导游盖德在地上画一条浅线，大家顺着走 → guideline 指导方针、基准线","word":"guideline"},"root":"由 guide“引导”+ line“线”构成的英语复合词，核心是“先画一条让人顺着走的浅线”。","sensesIntro":{"en":"Eight senses of guideline, all grown from one mark: a faint line drawn before the work begins, which later becomes a principle, a policy, a clinical recommendation and a limit for judgment.","cn":"guideline 的八个义项都从同一道痕迹长出来：工作开始前画下的一条浅线，后来变成原则、政策、临床建议与判断的界限。"},"semanticMap":{"core":{"en":"CORE IMAGE: a faint line is drawn ahead of the work, and later hands follow it without being forced.","cn":"核心意象：工作在开始前先画下一条浅线，后来的手顺着它走，却不受强迫。"},"chain":["MARK THE SURFACE","FOLLOW THE LINE","CUT STRAIGHT","ADVISE OTHERS","SET INSTITUTIONAL POLICY","MARK THE LIMIT"],"branches":[{"senses":"01 · 02","en":"ADVICE: a personal principle or an institution's procedure is a line that recommends a path without legally compelling it.","cn":"建议：个人原则或机构程序都是一条线，推荐一条路径，却不具法律强制力。"},{"senses":"03 · 04","en":"PUBLIC GUIDANCE: the line is drawn across a country or a body of evidence, steering policy and clinical decisions.","cn":"公共指引：这条线画遍全国或穿过一堆证据，引导政策与临床决定。"},{"senses":"05 · 06","en":"LITERAL LINE: in design and craft the mark is visible on the surface, telling the eye or the blade where the edge falls.","cn":"字面线条：在设计与工艺中，痕迹可见于表面，告诉眼睛或刀刃边缘该落在哪里。"},{"senses":"07","en":"LIMIT: the faint line turns into a boundary, showing where acceptable judgment ends.","cn":"界限：浅线变成边界，显示可接受的判断到哪里为止。"},{"senses":"08","en":"HISTORICAL ROPE: for 19th-century balloonists the line was a real cord that steered a real craft.","cn":"历史绳索：对 19 世纪的热气球驾驶员来说，这条线是真正操纵飞行器的绳索。"}]},"affixes":{"intro":{"en":"Guideline is an English compound, not a Latin derivative: guide + line. Its affix work is done by the guide family and by the line family, both of which are still productive.","cn":"guideline 是英语复合词，不是拉丁派生词：guide + line。它的构词工作由 guide 词族与 line 词族承担，两者至今仍有能产性。"},"latinIntro":{"en":"Only the second element has a Latin source: linea 'linen thread, plumb-line, boundary'. Guide itself is Germanic through French, from a root meaning 'to see, show the way'.","cn":"只有第二个成分有拉丁语源：linea“亚麻线、铅垂线、边界”。guide 本身是经法语来的日耳曼词，词根意为“看见、指路”。"},"items":[{"word":"guideline","structure":"guide (v.) + line (n.), compound","meaning":"a line or principle that guides","meaningCN":"起引导作用的线或原则（复合词）","example":"The guideline was printed on a single sheet.","exampleCN":"这条准则印在一张单页上。"},{"word":"guidance","structure":"guide + -ance (noun of action)","meaning":"the act of guiding; advice","meaningCN":"指导；引导（-ance 构成行为名词）","example":"New students receive guidance on choosing modules.","exampleCN":"新生会得到选课指导。"},{"word":"guidebook","structure":"guide + book, compound","meaning":"a book of information for travellers","meaningCN":"旅行指南；手册","example":"The guidebook lists every ferry timetable.","exampleCN":"这本指南列出了所有渡轮时刻表。"},{"word":"guidepost","structure":"guide + post, compound","meaning":"a post that marks a route","meaningCN":"路标；指示柱","example":"A weathered guidepost stood at the fork.","exampleCN":"岔路口立着一根风化的路标。"},{"word":"misguide","structure":"mis- (wrongly) + guide","meaning":"to lead someone in the wrong direction","meaningCN":"误导；把……引错方向（mis- 表示错误）","example":"The map misguides anyone who trusts the old road.","exampleCN":"这张地图会误导任何相信那条旧路的人。"},{"word":"guided","structure":"guide + -ed (past participle)","meaning":"led or directed; also of a missile, steered in flight","meaningCN":"有指导的；制导的（-ed 构成分词）","example":"The class took a guided walk through the marsh.","exampleCN":"全班在向导带领下走过湿地。"},{"word":"unguided","structure":"un- (not) + guided","meaning":"without direction or control","meaningCN":"无导引的；无指导的","example":"An unguided tour often misses the oldest stones.","exampleCN":"没有导览的参观常常错过最古老的石头。"},{"word":"outline","structure":"out- (outer) + line","meaning":"the outer edge of a shape; a summary","meaningCN":"轮廓；提纲（out- 外 + line 线）","example":"The outline of the cliff was sharp against the sky.","exampleCN":"悬崖的轮廓在天空下十分清晰。"},{"word":"underline","structure":"under- (beneath) + line","meaning":"to draw a line under; to emphasise","meaningCN":"在……下画线；强调","example":"Underline the sentence that carries the claim.","exampleCN":"在承载论点的那一句下面画线。"},{"word":"linear","structure":"line + -ar (adjective)","meaning":"arranged in a line; straight","meaningCN":"线性的；直线的（-ar 构成形容词）","example":"The garden follows a linear plan.","exampleCN":"这座花园按直线布局。"},{"word":"lineage","structure":"line + -age (collective noun)","meaning":"a line of descent","meaningCN":"血统；世系（line 的“连续序列”义加 -age）","example":"The family can trace its lineage to the 1600s.","exampleCN":"这个家族的血统可以追溯到 17 世纪。"}],"latinEntries":[{"word":"linea","structure":"from linum 'linen' + -ea","meaning":"linen thread, string, plumb-line; a mark or boundary","meaningCN":"亚麻线、绳、铅垂线；标记或边界"},{"word":"lineamentum","structure":"linea + -mentum (instrument or result)","meaning":"a line, an outline, a feature of the face","meaningCN":"线条；轮廓；面部特征"}]}},{"word":"habitat","ipa_uk":"/ˈhæbɪtæt/","ipa_us":"/ˈhæbɪtæt/","definition_zh":"栖息地；生境；（动植物的）自然生长地；居住环境","definition_en":"the natural area in which a plant, animal, or other organism normally lives and finds the conditions it needs","core_image":"一片恰好为某种生命备好条件的地方，它自己走进去住下","scene":"Biologists found that the restored marsh had become a habitat for three rare bird species.","sceneCN":"这里 habitat 是「天然栖息地」（第 1 个义项：动植物自然生活并获取所需条件的区域）；句意：生物学家发现，修复后的沼泽已成为三种珍稀鸟类的栖息地。场景要点：一片浅水与芦苇、几种在水面筑巢的鸟、鸟与这片地方之间“住进去”的关系。","pos":[{"tag":"n.","zh":"栖息地；生境；自然生长地"},{"tag":"n.","zh":"（人类或人造的）居住环境；居所（较新用法）"}],"collocations":[{"phrase":"natural habitat","zh":"天然栖息地"},{"phrase":"habitat loss","zh":"栖息地丧失"},{"phrase":"habitat destruction","zh":"栖息地破坏"},{"phrase":"habitat restoration","zh":"栖息地修复"},{"phrase":"wildlife habitat","zh":"野生动物栖息地"},{"phrase":"in its natural habitat","zh":"在它的自然栖息地中"},{"phrase":"habitat fragmentation","zh":"栖息地破碎化"}],"forms":[{"label":"复数","form":"habitats"}],"derivatives":[{"word":"habitation","pos":"n.","zh":"居住；住所；聚居地"},{"word":"inhabit","pos":"v.","zh":"居住于；栖居于"},{"word":"inhabitant","pos":"n.","zh":"居民；栖居者"},{"word":"habitable","pos":"adj.","zh":"可居住的；适宜居住的"},{"word":"uninhabited","pos":"adj.","zh":"无人居住的；荒无人烟的"},{"word":"cohabit","pos":"v.","zh":"同居；共同居住"}],"senses":[{"no":"01","title":"The natural home of a species","titleCN":"物种的天然栖息地","definition":"the natural environment in which a particular plant or animal lives and finds food, shelter and the conditions it needs","definitionCN":"某种植物或动物自然生活、并获得食物、庇护和所需条件的环境","example":"Drainage destroyed the habitat of several native frogs.","exampleCN":"排水工程毁掉了数种本地蛙类的栖息地。","why":"The Latin word is literally 'it inhabits'. A habitat is not a house that someone builds but a place an organism already occupies because the conditions suit it; the core image is a creature entering a place prepared by nature.","whyCN":"这个拉丁词字面就是“它居住”。栖息地不是谁建造的房子，而是生物因条件合适而本来就占据的地方；核心意象是一只生物走进一片由自然备好的地方。"},{"no":"02","title":"The recorded locality of a species","titleCN":"物种的产地与分布区","definition":"the specific locality recorded for a plant or animal in its scientific description, or the area over which it occurs","definitionCN":"科学描述中为某种动植物记录的特定地点，或该物种出现的区域","example":"The type specimen's habitat is a single valley in Yunnan.","exampleCN":"那份模式标本的产地是云南的一条山谷。","why":"In 1762 the word began as a technical label in Latin descriptions of plants and animals: the part of the entry that told readers where the species lives. It names a point on the map, not a way of life.","whyCN":"1762 年，这个词最初是拉丁文动植物描述中的一个技术标签：条目里告诉读者该物种住在哪里的一部分。它命名的是地图上的一点，而不是一种生活方式。"},{"no":"03","title":"A type of living space: wetland, forest, reef","titleCN":"生境类型：湿地、森林、礁区","definition":"a category of environment defined by its physical conditions and the community of organisms it supports","definitionCN":"由其物理条件及所供养的生物群落所定义的一类环境","example":"Coral reefs are the most diverse marine habitat.","exampleCN":"珊瑚礁是多样性最高的海洋生境。","why":"Once many species' places are compared, the word groups them by type. The same 'place where life fits' becomes a category, so one can speak of a wetland habitat or a forest habitat.","whyCN":"当许多物种的地方被放在一起比较，这个词就按类型把它们归类。同一个“生命得以安放之处”变成了类别，于是可以说湿地生境或森林生境。"},{"no":"04","title":"A designed home in captivity","titleCN":"圈养环境：人工布置的栖息处","definition":"an enclosure or setting designed to imitate an animal's natural conditions in a zoo, aquarium, or laboratory","definitionCN":"在动物园、水族馆或实验室中模仿动物自然条件而设计的围栏或环境","example":"The keepers rebuilt the enclosure to give the otters a more natural habitat.","exampleCN":"饲养员重建了围栏，给水獭一个更自然的栖息环境。","why":"Here humans draw the boundary and supply the conditions. The word still means 'where the animal lives', but the place is now made rather than found.","whyCN":"这里由人划定边界、提供条件。词义仍是“动物生活的地方”，但这片地方是被造出来的，而不是被找到的。"},{"no":"05","title":"Human or constructed living environment","titleCN":"人类或人造的居住环境","definition":"a place designed for humans or other organisms to live in, including space stations and imagined colonies","definitionCN":"为人类或其他生物居住而设计的地方，包括空间站与设想的定居点","example":"Engineers tested how a sealed lunar habitat would recycle water.","exampleCN":"工程师测试了一座密封的月球居住舱将如何循环用水。","why":"The word extends from animals to humans when the emphasis is on the conditions that make life possible. A space habitat is an environment engineered to keep a living community alive.","whyCN":"当重点落在“使生命得以维持的条件”上，这个词便从动物扩展到人类。太空居住舱就是一个为维持生命群落而工程化设计的环境。"},{"no":"06","title":"A micro-habitat for microbes","titleCN":"微生物的微观生境","definition":"the specific small-scale conditions in which a microorganism or a cell population lives, such as a gut or a hot spring","definitionCN":"微生物或细胞群体生活的特定小尺度条件，如肠道或温泉","example":"The acidic pool is a habitat for bacteria found nowhere else.","exampleCN":"这个酸性水潭是别处找不到的细菌的栖息地。","why":"Scale is irrelevant to the core image: a few millilitres of hot spring can be as much a home as a forest, as long as the conditions fit the organism.","whyCN":"尺度与核心意象无关：几毫升的温泉水和一片森林一样可以成为家，只要条件适合该生物。"},{"no":"07","title":"Figurative: a place where something thrives","titleCN":"比喻：某事物得以繁衍的土壤","definition":"a setting or environment in which a particular activity, idea, or group can grow and persist","definitionCN":"某种活动、观念或群体得以生长并持续的环境","example":"The old harbour became a habitat for small theatres and cheap studios.","exampleCN":"旧港区成了小剧场和廉价工作室的滋生地。","why":"The biological meaning is transferred to ideas and institutions: if a place supplies the conditions that let a thing live, then it is that thing's habitat, even without soil or water.","whyCN":"生物义被转移到观念与机构：如果一个地方提供了让某事物存活的条件，那它就是该事物的栖息地，哪怕没有土壤和水。"},{"no":"08","title":"Older general sense: a dwelling place","titleCN":"旧义：住所、居住地","definition":"in 19th-century general use, simply a place where a person or thing dwells; now mostly literary or technical","definitionCN":"在 19 世纪的一般用法中，泛指人或物居住的地方；现在多用于文学或技术语境","example":"The cottage had been his habitat for forty years.","exampleCN":"那间小屋曾是他四十年的居所。","why":"The general sense 'dwelling place' is recorded from 1854, before ecology fixed the word to non-human life. Modern usage usually keeps habitat for organisms and leaves human homes to habitation or home.","whyCN":"“居住地”这一泛义从 1854 年就有记录，早于生态学把这个词固定用于非人类生命。现代用法通常把 habitat 留给生物，把人的住所交给 habitation 或「住所」一类的词。"}],"etymology":{"intro":{"en":"Habitat is a Latin verb form that English borrowed as a scientific noun: literally 'it inhabits'. Dates and the ecological extension are approximate.","cn":"habitat 是一个被英语当作科学名词借入的拉丁语动词形式，字面意为“它居住”。年代与生态学扩展的时间为大致估计。"},"items":[{"era":"1762","en":"First recorded as a technical term in Latin texts on English flora and fauna. It was the Modern Latin word beginning the part of a species description that told its locality.","cn":"最早记录于 1762 年，是英国动植物拉丁文志书中的技术术语。它是现代拉丁语词，用在物种描述中说明产地的那一部分开头。"},{"era":"MODERN LATIN","en":"Habitat is literally 'it inhabits', the third person singular present indicative of Latin habitare 'to live, dwell, inhabit'.","cn":"habitat 字面就是“它居住”，是拉丁语 habitare“生活、居住、栖居”的第三人称单数现在时直陈式。"},{"era":"LATIN","en":"Habitare is a frequentative of habere 'to have, hold, possess', so dwelling was pictured as holding a place. English also took habit, inhabit and habitation from the same stem.","cn":"habitare 是 habere“拥有、握有、占有”的反复动词，因此“居住”被想象成“握有一个地方”。英语也从同一词干借入 habit、inhabit 与 habitation。"},{"era":"PROTO-INDO-EUROPEAN","en":"Habere is reconstructed to PIE *ghabh- 'to give or receive', whose basic sense was probably 'to hold'. The root is reconstructed, not attested in writing.","cn":"habere 被重构为原始印欧语 *ghabh-“给予或接受”，其基本义很可能是“握有”。该词根是重构的，没有书面文献直接记录。"},{"era":"1854","en":"The general sense 'dwelling place' is first attested in 1854, showing the word escaping from purely botanical and zoological writing.","cn":"“居住地”这一泛义最早见于 1854 年，说明这个词开始越出纯粹的植物学与动物学写作。"},{"era":"20TH C.","en":"Ecology turns habitat into a central countable noun: habitat loss, habitat fragmentation, habitat restoration. The compounds belong to modern conservation language rather than to the Latin source.","cn":"生态学把 habitat 变成核心的可数名词：habitat loss、habitat fragmentation、habitat restoration。这些复合词属于现代保护生物学语言，而不是拉丁语源。"}]},"similar":{"note":{"en":"The first group separates habitat from the words built on the same habere stem, since they look close but describe different things; the second group compares the scales and units of the living environment.","cn":"第一组把 habitat 与同一 habere 词干上的词分开，因为它们形近却描述不同事物；第二组比较“生存环境”的不同尺度与单位。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"habitation","ipa":"/ˌhæbɪˈteɪʃn/","tag":"human dwelling","definition":"the act of living in a place, or a place to live in, especially a human dwelling. Habitat is where a species lives; habitation is the human act or building of living there.","definitionCN":"居住的行为，或居住的地方，尤指人的住所。habitat 是物种生活之处；habitation 是人居住的行为或建筑。"},{"word":"inhabit","ipa":"/ɪnˈhæbɪt/","tag":"verb","definition":"to live or dwell in a place. It is the verb that habitat presupposes: a habitat is the place that a species inhabits.","definitionCN":"居住于某地。它是 habitat 所预设的动词：栖息地就是某物种栖居的地方。"},{"word":"inhabitant","ipa":"/ɪnˈhæbɪtənt/","tag":"person or animal","definition":"one who lives in a place, as opposed to a visitor. It names the occupant, while habitat names the occupied place.","definitionCN":"居住在某地者，区别于访客。它命名占据者，而 habitat 命名被占据的地方。"},{"word":"habit","ipa":"/ˈhæbɪt/","tag":"same stem, different noun","definition":"a settled practice or tendency; also an old word for dress. It shares the 'hold' root but has nothing to do with where a species lives.","definitionCN":"固定的习惯或倾向；也可旧指衣着。它共享“握有”词根，但与物种住在哪里无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"environment","ipa":"/ɪnˈvaɪrənmənt/","tag":"surrounding conditions","definition":"the whole set of surrounding conditions, physical and social, that affect an organism. Environment is broader than habitat: it includes climate, neighbours and human pressure, not only the place occupied.","definitionCN":"影响某一生物的全部周围条件，包括物理的与社会的。environment 比 habitat 更广：它包含气候、邻近生物与人类压力，而不只是被占据的地点。"},{"word":"ecosystem","ipa":"/ˈiːkəʊsɪstəm/","tag":"community plus place","definition":"a community of organisms together with the physical surroundings they interact with. An ecosystem is a working system; a habitat is one species' address inside it.","definitionCN":"生物群落与其相互作用的物理环境之整体。ecosystem 是一个运转的系统；habitat 则是其中某一物种的“地址”。"},{"word":"niche","ipa":"/niːʃ/","tag":"role, not address","definition":"the role and position a species occupies in an ecosystem, including what it eats and when it is active. Niche is the job; habitat is the workplace.","definitionCN":"某物种在生态系统中的角色与位置，包括吃什么、何时活动。niche 是“职业”，habitat 是“工作场所”。"},{"word":"range","ipa":"/reɪndʒ/","tag":"whole distribution","definition":"the entire geographical area over which a species occurs. A range may contain many habitats; a habitat is one patch of suitable conditions inside it.","definitionCN":"某物种出现的整个地理区域。range 可以包含许多栖息地；habitat 则是其中一个条件合适的斑块。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: Latin habitare 'to dwell', habere 'to hold', and the English family inhabit / inhabitant / habitation.","cn":"只用真实成分与真实同族词：拉丁语 habitare“居住”、habere“握有”，以及英语词族 inhabit／inhabitant／habitation。"},"normal":[{"en":"Habitat is a whole Latin sentence compressed into a noun: habitat = 'it lives here'. The animal is the subject, the place is the object.","cn":"habitat 是一个压成名词的完整拉丁句子：habitat＝“它住在这里”。动物是主语，地方是宾语。"},{"en":"Inhabit is the verb, inhabitant is the person or animal, habitation is the act or building, and habitat is the place itself: four roles from one stem.","cn":"inhabit 是动词，inhabitant 是居住者，habitation 是居住行为或住所，habitat 是地方本身：同一词干的四种角色。"},{"en":"A habit is something you hold onto and repeat; a habitat is a place a species holds. The shared idea is 'holding', not 'living'.","cn":"habit 是你反复握持的习惯；habitat 是一个物种握有的地方。共同的想法是“握有”，而不是“居住”。"},{"en":"Habitat loss is the standard conservation phrase: the place disappears, and the species has nowhere to be its subject.","cn":"habitat loss 是保护生物学的标准说法：地方消失了，物种也就无处可做那个主语。"},{"en":"In a zoo, the enclosure is called a habitat only when it imitates the natural conditions closely enough.","cn":"在动物园里，只有足够逼真地模仿自然条件的围栏才被称为 habitat。"}],"abstract":[{"en":"Picture a marsh at dawn: reeds, shallow water, three birds already there. Nobody invited them; the place simply fits, and that fit is habitat.","cn":"想象清晨的沼泽：芦苇、浅水、三只已经在那里的鸟。没人邀请它们，地方只是恰好合适，而这种“合适”就是 habitat。"},{"en":"Scale does not matter: a forest, a reef, a puddle, or a length of intestine can all be a habitat if the conditions let a life continue there.","cn":"尺度无关紧要：森林、礁区、水洼或一段肠道，只要条件能让生命在那里延续，都可以是栖息地。"},{"en":"Move the word from biology to culture and the same logic holds: whatever supplies the conditions for a thing to live is that thing's habitat.","cn":"把这个词从生物学移到文化上，逻辑仍然成立：凡是提供某事物存活条件的地方，就是该事物的栖息地。"}]},"examples":[{"en":"The dam cut the river's flow and dried out the habitat downstream.","cn":"大坝截断了河流的水量，使下游的栖息地干涸。"},{"en":"Polar bears are hard to study in their habitat because the ice is moving.","cn":"北极熊在自然栖息地中很难研究，因为冰面一直在移动。"},{"en":"The abandoned rail yard became a habitat for foxes, moths and rare grasses.","cn":"废弃的铁路场成了狐狸、飞蛾与稀有草类的栖息地。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“哈比塔特”——哈比（鸟）塔（搭）特（别）舒服的窝，住进去就不走了 → habitat 栖息地","word":"habitat"},"root":"拉丁语 habitat 字面意为“它居住”，源自 habitare“居住”、habere“握有”，核心是“生命自己走进并占住的一片合适之地”。","sensesIntro":{"en":"Eight senses of habitat, all grown from one relation: a living thing and a place whose conditions fit it, so that the place becomes where it lives.","cn":"habitat 的八个义项都从同一种关系长出来：一个生命与一片条件合适的地方，于是这片地方成为它生活之处。"},"semanticMap":{"core":{"en":"CORE IMAGE: a creature enters a place whose conditions already suit it and settles there.","cn":"核心意象：一只生物走进一片条件本就适合它的地方，并在那里安顿下来。"},"chain":["CONDITIONS FIT","THE ORGANISM ENTERS","IT DWELLS THERE","A PLACE IS NAMED","TYPES ARE COMPARED","THE TERM IS EXTENDED"],"branches":[{"senses":"01 · 03","en":"NATURAL HOME: one species' place and a whole class of places such as wetland or reef both answer the same question — where does life fit?","cn":"天然家园：单一物种的地方与湿地、礁区等整类地方，回答的都是同一个问题——生命在哪里合适？"},{"senses":"02","en":"LOCALITY: in a scientific description the word narrows to a point on the map, the recorded place where the species was found.","cn":"产地：在科学描述中，这个词收窄为地图上的一点，即记录到该物种的地点。"},{"senses":"04 · 06","en":"MADE AND MICRO: a zoo enclosure or a hot spring is still a habitat if the conditions, however constructed or small, let the organism live.","cn":"人造与微观：动物园围栏或温泉仍是栖息地，只要条件——无论多么人工或微小——能让该生物存活。"},{"senses":"05","en":"HUMAN: the word moves to engineered living environments such as space stations, where the point is keeping a community alive.","cn":"人类：这个词移到空间站等工程化居住环境，重点在于维持一个生命群落的存续。"},{"senses":"07 · 08","en":"EXTENSION: ideas can have a habitat too, and the old general sense simply called any dwelling place a habitat.","cn":"扩展：观念也可以有栖息地；旧有的泛义则把任何居住地都称作 habitat。"}]},"affixes":{"intro":{"en":"Habitat is not built from an English prefix at all: it is a Latin verb ending borrowed as a noun. Its apparent parts belong to Latin, and English later adds -ant, -ation, -able and in- to the same stem.","cn":"habitat 根本不是由英语前缀构成的：它是把拉丁语动词词尾当作名词借入。它表面上的成分属于拉丁语，英语后来又在同一词干上加 -ant、-ation、-able 与 in-。"},"latinIntro":{"en":"The family rests on habere 'to have, hold, possess' and its frequentative habitare 'to dwell'. Habitare gives habitat, habitation and inhabit; habere also gives habit, able and exhibit through older French and Latin paths.","cn":"这个词族建立在 habere“拥有、握有、占有”及其反复动词 habitare“居住”上。habitare 给出 habitat、habitation、inhabit；habere 还经由较早的法语和拉丁语路径给出 habit、able、exhibit。"},"items":[{"word":"inhabit","structure":"in- (in) + habitare (dwell)","meaning":"to live in a place","meaningCN":"居住于；栖居于（in- 在内 + habitare 居住）","example":"Few fish can inhabit water this warm.","exampleCN":"很少有鱼能栖居在这么温暖的水里。"},{"word":"inhabitant","structure":"inhabit + -ant (person or thing doing)","meaning":"one who lives in a place","meaningCN":"居民；栖居者（-ant 表示施事者）","example":"The island's only inhabitants are seabirds.","exampleCN":"岛上唯一的居民是海鸟。"},{"word":"habitation","structure":"habitare + -ion (action or place noun)","meaning":"the act of dwelling, or a dwelling place","meaningCN":"居住；住所（-ion 构成行为或地点名词）","example":"The valley shows signs of human habitation for centuries.","exampleCN":"这条山谷显示出数百年人类居住的痕迹。"},{"word":"habitable","structure":"habitare + -able (able to be)","meaning":"suitable for living in","meaningCN":"可居住的；适宜居住的（-able 表示能够被）","example":"The planet lies just inside the habitable zone.","exampleCN":"这颗行星恰好位于宜居带内侧。"},{"word":"uninhabited","structure":"un- (not) + inhabited","meaning":"having no residents","meaningCN":"无人居住的；荒无人烟的","example":"The island was uninhabited for most of the year.","exampleCN":"这座岛一年中大部分时间无人居住。"},{"word":"cohabit","structure":"co- (together) + habitare (dwell)","meaning":"to live together, especially as a couple","meaningCN":"同居；共同居住（co- 共同 + 居住）","example":"The two species cohabit in the same cave.","exampleCN":"这两个物种共同栖息在同一洞穴中。"},{"word":"habit","structure":"Latin habitus 'condition, demeanour, dress', from habere","meaning":"a settled practice; also an old word for clothing","meaningCN":"习惯；旧指衣着（来自拉丁语 habitus“状态、举止、衣着”）","example":"Reading before sleep had become a habit.","exampleCN":"睡前阅读已成了一种习惯。"},{"word":"habitual","structure":"habit + -ual (adjective)","meaning":"done regularly, as a habit","meaningCN":"习惯性的；惯常的（-ual 构成形容词）","example":"His habitual lateness annoyed the group.","exampleCN":"他惯常的迟到让全组不满。"},{"word":"habituate","structure":"habit + -uate (verb)","meaning":"to accustom someone or something to a condition","meaningCN":"使习惯于；使适应","example":"Animals habituate quickly to the sound of the generator.","exampleCN":"动物很快会习惯发电机的声音。"},{"word":"exhibit","structure":"ex- (out) + habere (hold)","meaning":"to hold out for others to see; to display","meaningCN":"展出；显示（ex- 向外 + habere 握有）","example":"The museum exhibits specimens from the same habitat.","exampleCN":"博物馆展出来自同一栖息地的标本。"},{"word":"able","structure":"hab- (hold) + -ilis (able to be), through French","meaning":"having the power or skill to do something","meaningCN":"能够的；有能力的（同一“握有”词根经法语演变）","example":"The team was able to map the whole habitat.","exampleCN":"团队得以绘制整个栖息地的地图。"}],"latinEntries":[{"word":"habitare","structure":"habere 'hold' + frequentative -itare","meaning":"to live, dwell, inhabit","meaningCN":"生活；居住；栖居"},{"word":"habere","structure":"from PIE *ghabh- 'to give or receive'","meaning":"to have, hold, possess","meaningCN":"拥有；握有；占有"},{"word":"habitatio","structure":"habitare + -io (action noun)","meaning":"a dwelling; the act of dwelling","meaningCN":"住所；居住的行为"},{"word":"habitabilis","structure":"habitare + -bilis (able to be)","meaning":"fit to be lived in","meaningCN":"适宜居住的"}]}},{"word":"hierarchy","ipa_uk":"/ˈhaɪərɑːki/","ipa_us":"/ˈhaɪrɑːrki/","definition_zh":"等级制度；层级体系；统治集团；阶层","definition_en":"a system in which people or things are arranged in ranks, with each level ranking above or below another","core_image":"一座一级一级向上收窄的金字塔，每层只对紧挨着的上一层负责","scene":"In the hospital, a strict hierarchy decides who may overrule whom during an emergency.","sceneCN":"这里 hierarchy 是「等级体系」（第 1 个义项：组织内部按上下级排列的层级结构）；句意：在医院里，一套严格的等级体系决定紧急情况下谁可以否决谁。场景要点：手术台旁不同颜色的工牌、由下向上的汇报链、每一层只对紧挨着的上一层负责。","pos":[{"tag":"n.","zh":"等级制度；层级体系；阶层"},{"tag":"n.","zh":"（生物学）分类层级；（计算机）层次结构"}],"collocations":[{"phrase":"a social hierarchy","zh":"社会等级体系"},{"phrase":"a hierarchy of needs","zh":"需求层次"},{"phrase":"the corporate hierarchy","zh":"公司的层级结构"},{"phrase":"a strict hierarchy","zh":"严格的等级制度"},{"phrase":"the top of the hierarchy","zh":"层级体系的顶端"},{"phrase":"a hierarchy of importance","zh":"重要性的层级排序"},{"phrase":"taxonomic hierarchy","zh":"生物分类层级"}],"forms":[{"label":"复数","form":"hierarchies"}],"derivatives":[{"word":"hierarchical","pos":"adj.","zh":"等级制的；按等级划分的"},{"word":"hierarchic","pos":"adj.","zh":"等级的；层级式的"},{"word":"hierarch","pos":"n.","zh":"等级体系中的高层人物；高级教士"},{"word":"hierarchically","pos":"adv.","zh":"按等级地；按层级地"},{"word":"hierarchal","pos":"adj.","zh":"等级体系的（较少用变体）"}],"senses":[{"no":"01","title":"A ranked organisation of people","titleCN":"组织的等级体系","definition":"a system in which people or positions are arranged in ranks, so that each rank has authority over the one below it","definitionCN":"把人或职位按等级排列的体系，每一级对下一级拥有权威","example":"The firm's hierarchy puts every decision through three levels of approval.","exampleCN":"这家公司的等级体系让每项决定都要经过三层审批。","why":"The core image is a pyramid that narrows as it rises: each level holds authority over the level beneath it, and the shape of the whole depends on that step-by-step arrangement.","whyCN":"核心意象是一座向上收窄的金字塔：每一级对下面一级拥有权威，整体的形状就取决于这种逐级排列。"},{"no":"02","title":"A ranking by importance","titleCN":"按重要性排列的层级","definition":"an ordering of things from most to least important, powerful, or urgent","definitionCN":"按重要、强大或紧急程度从高到低排列的顺序","example":"The report sets out a hierarchy of risks, from flooding to noise.","exampleCN":"报告列出了一个风险层级，从洪水一直到噪音。","why":"The pyramid can also be built from things rather than people: what sits near the top matters more, and what sits below can wait. The vertical order becomes a scale of value.","whyCN":"这座金字塔也可以由事物而不是人来搭建：靠近顶端的更重要，下面的可以等。垂直顺序由此变成价值尺度。"},{"no":"03","title":"The ruling group at the top","titleCN":"顶端的统治集团","definition":"the small group of people who hold the highest positions and control an organisation or society","definitionCN":"占据最高位置、控制某一组织或社会的一小群人","example":"Reform was blocked by the party hierarchy.","exampleCN":"改革被党的上层集团阻挠了。","why":"By a common shift, the name of the structure comes to mean the people at its narrow top. The pyramid is reduced to its peak, and 'the hierarchy' becomes 'those who decide'.","whyCN":"一种常见的转喻：结构的名称变成了结构顶端那一小群人。金字塔被缩减为塔尖，the hierarchy 也就成了“决定者”。"},{"no":"04","title":"Biological classification ranks","titleCN":"生物分类层级","definition":"the nested series of categories used to classify organisms, from kingdom down to species","definitionCN":"用于对生物分类的一整套嵌套范畴，从界一直到种","example":"Linnaeus arranged living things in a hierarchy of kingdom, class, order, genus and species.","exampleCN":"林奈把生物安排进界、纲、目、属、种这样的层级中。","why":"Taxonomy is a pyramid of sets: each rank contains the ranks below it, so a species sits inside a genus, a genus inside a family. The word's vertical shape fits nested classification exactly.","whyCN":"分类学是一个集合的金字塔：每一级都包含下面几级，所以种在属内，属在科内。这个词的垂直形状恰好适合嵌套分类。"},{"no":"05","title":"A layered structure in computing","titleCN":"计算机中的层次结构","definition":"an arrangement of files, data, or system layers in which each level is contained in or depends on the level above","definitionCN":"文件、数据或系统层次的安排方式，每一层被上一层包含或依赖上一层","example":"The folder hierarchy puts every image under its project year.","exampleCN":"这个文件夹层级把每张图片放在对应的项目年份之下。","why":"A file tree is a pyramid drawn sideways: one root, branching levels, each item belonging to exactly one parent. The social image survives as containment and dependence rather than authority.","whyCN":"文件树是把金字塔横着画：一个根、逐层分支、每一项只属于一个父项。社会意象在这里保存为包含与依赖，而不是权威。"},{"no":"06","title":"The nine orders of angels","titleCN":"天使九阶：最初的神学义","definition":"in Christian theology, the ranked divisions of angels described by Dionysius the Areopagite; the word's earliest English sense","definitionCN":"基督教神学中由伪丢尼修描述的天使等级划分；这是该词最早的英语义项","example":"Medieval writers mapped the nine angelic hierarchy onto the nine spheres of heaven.","exampleCN":"中世纪作家把天使九阶对应到九重天球上。","why":"The word entered English in the late 14th century as a name for the sacred order of angels. Its first hierarchy was not a company but a cosmos: ranks of being, each closer to the divine than the one below.","whyCN":"这个词在 14 世纪晚期进入英语时，是天使神圣秩序的名称。它最初的层级不是公司，而是宇宙：存在的等级，每一级都比下一级更接近神。"},{"no":"07","title":"The order of the clergy","titleCN":"教会教阶制度","definition":"the ranked order of clergy, from deacon and priest up to bishop and pope","definitionCN":"神职人员的等级秩序，从执事、司铎一直向上到主教与教宗","example":"A bishop's place in the hierarchy was fixed by canon law.","exampleCN":"主教在教阶体系中的位置由教会法规定。","why":"The Greek source means 'rule of a high priest', so the church is where the word feels most at home. Each rank holds sacred office over the rank below, and the ladder runs up to a single summit.","whyCN":"希腊语源头意为“大祭司的统治”，因此教会是这个词最如鱼得水的地方。每一级对下一级拥有圣职权威，阶梯一直通向唯一的顶端。"},{"no":"08","title":"A hierarchy of knowledge or values","titleCN":"知识或价值的层级","definition":"an abstract ordering in which ideas, laws, or values are ranked as more fundamental than others","definitionCN":"把观念、法律或价值按根本程度排列的抽象秩序","example":"In legal theory, the constitution sits at the top of a hierarchy of norms.","exampleCN":"在法律理论中，宪法位于规范层级的顶端。","why":"Once the image is abstract, anything that can be 'higher' or 'lower' in rank can form a hierarchy: norms, needs, genres, values. The pyramid becomes a way of saying that some things rest on others.","whyCN":"一旦意象抽象化，任何能在等级上分“高下”的东西都能构成 hierarchy：规范、需求、文类、价值。金字塔变成一种说法，表示某些事物依托于另一些事物。"}],"etymology":{"intro":{"en":"Hierarchy began as a word for the ranks of angels, built from Greek words for 'sacred' and 'rule'. Its modern organisational sense is much later. Dates are approximate.","cn":"hierarchy 最初是天使等级的名称，由希腊语“神圣”与“统治”两个词构成。它现代的组织义要晚得多。年代为大致估计。"},"items":[{"era":"LATE 14C.","en":"First recorded in English as jerarchie / ierarchie, meaning 'rank in the sacred order' and 'one of the three divisions of the nine orders of angels'; loosely also 'rule, dominion'.","cn":"最早以 jerarchie／ierarchie 记录于 14 世纪晚期，意为“神圣秩序中的等级”以及“天使九阶中三大划分之一”；宽泛地也指“统治、管辖”。"},{"era":"OLD FRENCH","en":"From Old French ierarchie (14c., Modern French hiérarchie), from Medieval Latin hierarchia 'ranked division of angels', the system of Dionysius the Areopagite.","cn":"来自古法语 ierarchie（14 世纪，现代法语 hiérarchie），再来自中世纪拉丁语 hierarchia“天使的等级划分”，即伪丢尼修的体系。"},{"era":"GREEK","en":"Greek hierarkhia meant 'rule of a high priest', from hierarkhēs 'high priest, leader of sacred rites': ta hiera 'the sacred rites' (from hieros 'sacred') plus arkhein 'to lead, rule'.","cn":"希腊语 hierarkhia 意为“大祭司的统治”，来自 hierarkhēs“大祭司、圣礼的主持者”：ta hiera“圣礼”（出自 hieros“神圣”）加 arkhein“引领、统治”。"},{"era":"1610S","en":"The sense 'ranked organisation of persons or things' is recorded in English by the 1610s, at first of the clergy. It was probably reinforced by the unrelated English word higher, which sounds like the start of hierarchy.","cn":"“人或事物的等级组织”这一义项在 17 世纪 10 年代有记录，最初用于神职人员。它很可能被无关的英语词 higher 强化，因为 higher 听起来像 hierarchy 的开头。"},{"era":"18C.–19C.","en":"The word extends to secular institutions, then to natural classification. Taxonomy, army ranks and civil service grades all become hierarchies in ordinary speech.","cn":"这个词扩展到世俗机构，再扩展到自然分类。分类学、军衔与文官等级在日常语言中都成了 hierarchy。"},{"era":"20TH C.","en":"Management theory, linguistics and computing adopt it: chain of command, syntactic hierarchy, folder hierarchy. The Greek sacred order becomes a general model of layered structure.","cn":"管理学、语言学与计算机科学采用它：指挥链、句法层级、文件夹层级。希腊的神圣秩序变成了分层结构的一般模型。"}]},"similar":{"note":{"en":"The first group separates the noun from its adjective and person forms, and warns about the unrelated word higher; the second group compares ways of ordering people and things.","cn":"第一组把名词与它的形容词、指人形式分开，并提醒注意无关的 higher；第二组比较排列人与事物的不同说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"hierarchical","ipa":"/ˌhaɪəˈrɑːkɪkl/","tag":"adjective","definition":"arranged in ranks, or organised by levels of authority. It describes the shape; hierarchy is the shape itself.","definitionCN":"按等级排列的，或按权威层级组织的。它描述形状；hierarchy 是形状本身。"},{"word":"hierarch","ipa":"/ˈhaɪərɑːk/","tag":"person","definition":"a person at the top of a hierarchy, especially a senior cleric. It names one holder of rank, not the system of ranks.","definitionCN":"等级体系顶端的人，尤指高级教士。它命名一位占据等级的人，而不是等级体系。"},{"word":"hierarchal","ipa":"/ˌhaɪəˈrɑːkl/","tag":"rare adjective","definition":"an uncommon variant of hierarchical. It is best avoided when hierarchical is available, since the two are easily confused in writing.","definitionCN":"hierarchical 的不常见变体。既然有 hierarchical，最好避免使用，因为两者在书面上极易混淆。"},{"word":"higher","ipa":"/ˈhaɪə/","tag":"unrelated look-alike","definition":"the comparative of high. It is not related to hierarchy, though its sound probably helped the modern sense of ranked organisation take hold.","definitionCN":"high 的比较级。它与 hierarchy 没有词源关系，但它的读音很可能帮助了现代“等级组织”义项扎根。"}]},{"heading":"NEAR MEANING","entries":[{"word":"rank","ipa":"/ræŋk/","tag":"one position","definition":"a single level or position in an order. Rank is one rung; hierarchy is the whole ladder and the rule that connects its rungs.","definitionCN":"秩序中的单个级别或位置。rank 是一级横档；hierarchy 是整架梯子以及连接各横档的规则。"},{"word":"order","ipa":"/ˈɔːdə/","tag":"general arrangement","definition":"the way things are arranged, or a sequence. Order can be flat and neutral, like alphabetical order; hierarchy always implies higher and lower.","definitionCN":"事物被安排的方式，或序列。order 可以是平铺中性的，如字母顺序；hierarchy 总含高下之分。"},{"word":"pecking order","ipa":"/ˈpekɪŋ ɔːdə/","tag":"informal social ranking","definition":"the informal ranking of status within a group, originally observed in hens. It is vivid and colloquial; hierarchy is neutral and structural.","definitionCN":"群体内部非正式的位次排序，最初来自对鸡群的观察。它形象而口语化；hierarchy 中性且结构化。"},{"word":"chain of command","ipa":"/tʃeɪn əv kəˈmɑːnd/","tag":"authority path","definition":"the line through which orders pass from superior to subordinate. It stresses communication and obedience, while hierarchy stresses the whole ranked structure.","definitionCN":"命令由上级传到下级的线路。它强调传达与服从，hierarchy 则强调整个等级结构。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: Greek hieros 'sacred' plus arkhein 'to rule', and the arch- family that still marks rule in English.","cn":"只用真实成分与真实同族词：希腊语 hieros“神圣”加 arkhein“统治”，以及英语中仍标记“统治”的 arch- 词族。"},"normal":[{"en":"Hierarchy literally joins 'sacred' and 'rule': its first home was the order of angels, not the office org chart.","cn":"hierarchy 字面上把“神圣”与“统治”连在一起：它最初的家是天使的秩序，而不是办公室的组织图。"},{"en":"The arch- in hierarchy is the same arch- that rules in monarchy, anarchy and patriarch: arkhein means 'to lead, rule'.","cn":"hierarchy 里的 arch- 与 monarchy、anarchy、patriarch 中表示统治的 arch- 相同：arkhein 意为“引领、统治”。"},{"en":"Hierarchy and higher are not related. The resemblance is a coincidence that probably helped the modern meaning feel natural.","cn":"hierarchy 与 higher 没有词源关系。这种相似是巧合，但它很可能让现代词义显得更自然。"},{"en":"A hierarchy of needs is a real fixed phrase from psychology: needs are stacked, with basic ones below and refined ones above.","cn":"hierarchy of needs 是心理学中真实的固定说法：需求被堆叠起来，基本需求在下，精致需求在上。"},{"en":"In computing, a folder hierarchy is a tree: one root, many branches, every item with exactly one parent.","cn":"在计算机中，文件夹层级是一棵树：一个根、许多分支，每一项只有一个父项。"}],"abstract":[{"en":"Picture a pyramid of stone steps: the base is wide, the top is narrow, and each step exists only because the one below holds it up.","cn":"想象一座石阶金字塔：底部宽，顶端窄，每一级之所以存在，是因为下面一级托着它。"},{"en":"The same pyramid can be made of people, ranks, species, files or values. What stays constant is that some things rest on others and none may float.","cn":"同一座金字塔可以由人、军衔、物种、文件或价值搭成。不变的是：某些事物依托于另一些事物，没有谁能悬空。"},{"en":"When people say 'the hierarchy', they mean the narrow top of the pyramid: the structure has shrunk to the few who decide.","cn":"当人们说 the hierarchy，指的是金字塔狭窄的顶端：整个结构被缩减为少数做决定的人。"}]},"examples":[{"en":"The old monastery kept a hierarchy so precise that even the order of seating was recorded.","cn":"那座古老修道院的等级秩序精确到连座次都被记录下来。"},{"en":"Flat teams often claim to have no hierarchy, yet informal rankings reappear within weeks.","cn":"扁平化团队常声称没有等级，但非正式的位次几周内就会重新出现。"},{"en":"The database stores every page in a hierarchy of folders rather than a single list.","cn":"这个数据库把每个页面存放在文件夹层级中，而不是一张单层列表里。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“海尔拉基”——海尔把员工拉成一级一级的基座，越往上人越少 → hierarchy 等级制度","word":"hierarchy"},"root":"源自希腊语 hierarkhia“大祭司的统治”，由 hieros“神圣”+ arkhein“统治”构成，核心是“按等级层层向上、每层对下层拥有权威”。","sensesIntro":{"en":"Eight senses of hierarchy, all grown from one shape: a pyramid of ranks in which each level rests on the one below and answers to the one above.","cn":"hierarchy 的八个义项都从同一个形状长出来：一座等级金字塔，每一级依托下一级，并向上一级负责。"},"semanticMap":{"core":{"en":"CORE IMAGE: a narrowing pyramid of ranks, each level resting on the one below and answering to the one above.","cn":"核心意象：一座逐级收窄的等级金字塔，每层依托下层，并对上层负责。"},"chain":["MANY AT THE BASE","FEWER ABOVE","EACH LEVEL OBEYS","AUTHORITY CONCENTRATES","THE TOP RULES","THE SHAPE IS ABSTRACTED"],"branches":[{"senses":"01 · 03","en":"ORGANISATION AND POWER: a ranked body of people, and then the narrow group at its top who actually decide.","cn":"组织与权力：先是按等级排列的人群，再是位于塔尖、真正做决定的那一小群。"},{"senses":"02 · 08","en":"ORDERING: the same vertical shape ranks risks, needs, norms and values by importance or fundamentality.","cn":"排序：同一垂直形状按重要性或根本性排列风险、需求、规范与价值。"},{"senses":"04","en":"BIOLOGY: nested sets reproduce the pyramid exactly, since each taxonomic rank contains the ranks below it.","cn":"生物学：嵌套集合精确复制了金字塔，因为每个分类层级都包含下面几级。"},{"senses":"05","en":"COMPUTING: a tree is the pyramid laid on its side, with containment and dependency instead of obedience.","cn":"计算机：树是横放的金字塔，用包含与依赖替代了服从。"},{"senses":"06 · 07","en":"THE SACRED SOURCE: angels and clergy are the word's first home, where rank means proximity to the divine.","cn":"神圣源头：天使与神职人员是这个词最初的家，等级意味着与神更近。"}]},"affixes":{"intro":{"en":"Hierarchy is a Greek compound borrowed through Latin and French: hieros 'sacred' + arkhein 'to rule'. English adds -al, -ic, -ically and -arch to the same stem.","cn":"hierarchy 是经拉丁语和法语借入的希腊语复合词：hieros“神圣”+ arkhein“统治”。英语在同一词干上加 -al、-ic、-ically 与 -arch。"},"latinIntro":{"en":"Medieval Latin hierarchia and hierarcha carried the Greek word into church writing. The second element, arkhein, is the source of the productive English combining form -arch, meaning 'ruler'.","cn":"中世纪拉丁语 hierarchia 与 hierarcha 把这个希腊词带进教会写作。第二个成分 arkhein 是英语能产后缀 -arch（意为“统治者”）的来源。"},"items":[{"word":"hierarchical","structure":"hierarchy + -ical (adjective)","meaning":"arranged in ranks or levels","meaningCN":"等级制的；按层级划分的（-ical 构成形容词）","example":"The archive uses a hierarchical system of folders.","exampleCN":"这个档案库使用层级化的文件夹系统。"},{"word":"hierarchic","structure":"hierarchy + -ic (adjective)","meaning":"of or relating to a hierarchy","meaningCN":"等级体系的；层级式的（-ic 构成形容词）","example":"The diagram shows the hierarchic links between teams.","exampleCN":"这张图显示各团队之间的层级联系。"},{"word":"hierarch","structure":"Greek hierarkhēs, shortened","meaning":"a chief ruler in sacred matters; a high-ranking member of a hierarchy","meaningCN":"高级教士；等级体系中的高层人物","example":"The hierarch blessed the new chapel.","exampleCN":"这位高级教士为新礼拜堂祝圣。"},{"word":"hierarchically","structure":"hierarchical + -ly (adverb)","meaning":"in a ranked or layered way","meaningCN":"按等级地；按层级地","example":"The data is organised hierarchically, from region to street.","exampleCN":"数据按层级组织，从大区一直到街道。"},{"word":"hierarchal","structure":"hierarchy + -al (adjective, rare)","meaning":"another adjective meaning hierarchical","meaningCN":"等级体系的（较少使用的形容词变体）","example":"Older texts prefer hierarchal to hierarchical.","exampleCN":"较早的文本更爱用 hierarchal 而不是 hierarchical。"},{"word":"monarchy","structure":"mono- (one) + -archy (rule)","meaning":"rule by a single sovereign","meaningCN":"君主制；一人统治（mono- 单一 + -archy 统治）","example":"The monarchy survived the revolution in a ceremonial form.","exampleCN":"君主制以礼仪形式在革命后存续下来。"},{"word":"anarchy","structure":"an- (without) + -archy (rule)","meaning":"a state without government or order","meaningCN":"无政府状态；混乱（an- 无 + -archy 统治）","example":"The power cut left the station in near anarchy.","exampleCN":"停电让车站几乎陷入无秩序状态。"},{"word":"oligarchy","structure":"oligo- (few) + -archy (rule)","meaning":"rule by a small group","meaningCN":"寡头统治；少数人掌权","example":"The company drifted into an oligarchy of three directors.","exampleCN":"这家公司逐渐变成三位董事的寡头统治。"},{"word":"patriarch","structure":"patri- (father) + -arch (ruler)","meaning":"the male head of a family or church","meaningCN":"家长；宗主教（patri- 父 + -arch 统治者）","example":"The patriarch led the procession.","exampleCN":"宗主教带领了游行队伍。"},{"word":"archbishop","structure":"arch- (chief) + bishop","meaning":"a bishop of the highest rank","meaningCN":"大主教；首席主教","example":"The archbishop convened the council.","exampleCN":"大主教召集了会议。"},{"word":"archon","structure":"Greek arkhein 'to rule' + -on (person)","meaning":"a chief magistrate in ancient Athens","meaningCN":"古希腊雅典的执政官","example":"The archon was chosen by lot each year.","exampleCN":"执政官每年以抽签方式选出。"}],"latinEntries":[{"word":"hierarchia","structure":"Greek hierarkhia, borrowed into Medieval Latin","meaning":"the ranked division of angels; sacred rule","meaningCN":"天使的等级划分；神圣统治"},{"word":"hierarcha","structure":"Greek hierarkhēs, Latinised","meaning":"a high priest, one who rules in sacred things","meaningCN":"大祭司；掌管圣事者"}]}},{"word":"highlight","ipa_uk":"/ˈhaɪlaɪt/","ipa_us":"/ˈhaɪlaɪt/","definition_zh":"突出；强调；使显眼；高光（最亮处）；最精彩的部分；挑染","definition_en":"to draw attention to something or make it stand out; the brightest point in an image, or the best part of an event","core_image":"一束光落在画面最亮的那一点，四周都退到暗处","scene":"The restorer switched on the lamp, and the highlight on the brass kettle jumped out while the dim kitchen fell away behind it.","sceneCN":"这里 highlight 是「画面上最亮的那一块」（第 1 个义项：绘画、照片或实景中最明亮的部位）；句意：修复师打开灯，铜壶上的高光一下子跳了出来，昏暗的厨房退到了它身后。场景要点：一盏灯、一件铜器、一块被照得最亮的反光面，其余部分相对变暗。","pos":[{"tag":"v.","zh":"强调；使突出；用荧光笔标出；挑染"},{"tag":"n.","zh":"高光（最亮处）；最精彩的部分；挑染"}],"collocations":[{"phrase":"highlight the importance of","zh":"强调……的重要性"},{"phrase":"highlight a problem","zh":"突出一个问题"},{"phrase":"the highlight of the trip","zh":"旅程中最精彩的部分"},{"phrase":"highlight reel","zh":"精彩片段集锦"},{"phrase":"highlight the text","zh":"把文字标成高亮"},{"phrase":"hair highlights","zh":"头发挑染"}],"forms":[{"label":"第三人称单数","form":"highlights"},{"label":"过去式","form":"highlighted"},{"label":"过去分词","form":"highlighted"},{"label":"现在分词","form":"highlighting"},{"label":"名词复数（与动词三单同形）","form":"highlights"}],"derivatives":[{"word":"highlighter","pos":"n.","zh":"荧光笔；高光笔"},{"word":"highlighted","pos":"adj.","zh":"被突出的；标成高亮的"},{"word":"highlighting","pos":"n.","zh":"高亮处理；挑染"},{"word":"highlights","pos":"n.","zh":"（复数）精彩片段；挑染的发缕"}],"senses":[{"no":"01","title":"The brightest patch in a picture","titleCN":"画面最亮的一块：高光","definition":"the brightest area in a painting, photograph, or real scene, where light falls most directly","definitionCN":"绘画、照片或实景中最明亮的区域，即光线最直接落下的地方","example":"The restorer switched on the lamp, and the highlight on the brass kettle jumped out.","exampleCN":"修复师打开灯，铜壶上的高光一下子跳了出来。","why":"The noun began in 1650s painting talk as high light, the lightest paint laid on a surface so that it seems to catch the sun; the word names the spot where the light is highest.","whyCN":"这个名词最早见于 17 世纪 50 年代的绘画用语，写作 high light，指涂在表面上、让该处仿佛受日光的最亮颜料；它命名的正是光位最高的那一点。"},{"no":"02","title":"The best part of an event","titleCN":"最精彩的部分：全场的高点","definition":"the most memorable, enjoyable, or important part of an event, journey, or period","definitionCN":"一次活动、旅程或一段时间中最难忘、最愉快或最重要的部分","example":"The night dive was the highlight of our trip to the island.","exampleCN":"那次夜潜是我们海岛之行中最精彩的部分。","why":"By 1855 the bright patch had turned figurative: highlights give a whole picture its effect, so the brightest moment gives an event its effect.","whyCN":"到 1855 年，这块亮斑已转为比喻义：高光让整幅画出效果，于是一场活动里最亮的时刻也让整场活动出效果。"},{"no":"03","title":"Hair: strands painted lighter","titleCN":"头发：染浅的发缕","definition":"lighter streaks made in hair by bleaching or dyeing, so that the strands catch the light","definitionCN":"用漂白或染色在头发上做出的较浅条纹，使发丝更容易受光","example":"She asked the stylist for soft highlights around her face.","exampleCN":"她请发型师在脸旁做柔和的挑染。","why":"Hairdressing borrowed the word in 1941: strands are painted lighter, exactly as a painter adds high lights to a canvas.","whyCN":"美发业在 1941 年借用了这个词：发丝被染浅，正如画家在画布上加高光。"},{"no":"04","title":"Mark with a bright pen","titleCN":"用亮色笔标出","definition":"to cover words or lines with a bright transparent colour so that they stand out on the page","definitionCN":"用明亮的透明色覆盖词句或行，使它们在纸面上显眼","example":"He highlighted every sentence that mentioned the deadline.","exampleCN":"他把每一句提到截止日期的句子都标了高亮。","why":"The verb arrived in 1861 meaning 'to put high lights into a picture'. A fluorescent pen does the same thing on paper: it lays a band of light over the important words.","whyCN":"动词于 1861 年出现，意为“在画上加高光”。荧光笔在纸上做的是同一件事：在重要的词句上铺一条亮带。"},{"no":"05","title":"Make prominent: emphasize","titleCN":"使突出：强调","definition":"to draw special attention to a point, fact, or quality in speech or writing","definitionCN":"在讲话或写作中把某个要点、事实或性质特别提出来引人注意","example":"The mayor highlighted the need for more nurses in her speech.","exampleCN":"市长在演讲中强调了增加护士的必要性。","why":"The figurative verb is recorded by 1944: to highlight a point is to paint it as the bright patch, so the listener's eye goes there first.","whyCN":"比喻义的动词到 1944 年有记录：highlight 一个要点，就是把它画成那块亮斑，让听者的目光先落到那里。"},{"no":"06","title":"Throw into relief: expose a problem","titleCN":"使问题显形：照出裂痕","definition":"to make a weakness, gap, or danger clearly visible by putting it against a contrasting background","definitionCN":"把弱点、缺口或危险放在对比鲜明的背景前，使其清晰可见","example":"The outage highlighted how fragile the old grid had become.","exampleCN":"这次停电暴露出旧电网已经多么脆弱。","why":"Light does not only decorate; it also reveals. When the beam falls on a crack, the crack becomes the brightest thing in the room.","whyCN":"光不只装饰，也会揭露。当光束打到一道裂缝上，裂缝就成了屋里最亮的东西。"},{"no":"07","title":"News focus: single out for coverage","titleCN":"报道聚焦：被选为题材","definition":"of a report, film, or programme, to make one subject the centre of attention among many","definitionCN":"指报道、影片或节目把众多题材中的一个置于注意中心","example":"The documentary highlights the workers who built the dam.","exampleCN":"这部纪录片把修建大坝的工人放在焦点上。","why":"An editor chooses which part of the picture gets the light. Selecting a subject for coverage is the journalistic version of the same act.","whyCN":"编辑决定画面的哪一部分被打光。选定报道对象，正是同一个动作在新闻里的版本。"},{"no":"08","title":"Highlight reel: collected bright moments","titleCN":"精彩集锦：亮斑被剪成一卷","definition":"a short film or list that gathers only the best moments of a longer event","definitionCN":"只把较长活动中最好的时刻收集起来的短片或清单","example":"The coach showed the team a two-minute highlight reel before the final.","exampleCN":"决赛前，教练给队伍放了一段两分钟的精彩集锦。","why":"Once moments can be called highlights, they can be cut out and spliced together; the reel is a box holding only the bright patches.","whyCN":"一旦某些时刻可以被称为高光，它们就能被剪下来拼在一起；集锦就是一只只装亮斑的盒子。"},{"no":"09","title":"Screen: a selected block shown in colour","titleCN":"屏幕：被选中的色块","definition":"of software, to show chosen text or data in a contrasting colour so the user can see what is selected","definitionCN":"指软件把选中的文字或数据以对比色显示，让用户看见选中了什么","example":"The search tool highlights the matching phrase in yellow.","exampleCN":"搜索工具用黄色标出匹配的短语。","why":"The screen repeats the painter's gesture: the chosen text is covered with a bright field while everything else stays plain.","whyCN":"屏幕重复了画家的动作：被选中的文字被铺上一块亮色，其余部分保持素净。"}],"etymology":{"intro":{"en":"Highlight is an English compound of two Old English words, high and light, and every sense still keeps the same picture: one spot receives more light than its surroundings. Dates are approximate.","cn":"highlight 是由两个古英语词 high 与 light 构成的英语复合词，所有义项都保留同一幅画面：某一点比周围受到更多的光。年代为大致估计。"},"items":[{"era":"1650s","en":"The noun is first recorded in painting, meaning 'the brightest part of a subject'. Earlier the plural high lights named the lightest paints used to build up such parts, as opposed to middle tints and shade tints.","cn":"名词最早记录于 17 世纪 50 年代的绘画语境，意为“主体上最亮的部分”。更早的复数形式 high lights 指用来堆出这种亮部的最浅颜料，与中间色、暗部色相对。"},{"era":"1855","en":"The figurative sense 'outstanding feature or characteristic' is recorded, since highlights give a picture its effect; it remained uncommon until about 1920.","cn":"比喻义“突出的特征或特点”有记录，因为高光让一幅画出效果；这一用法直到约 1920 年才变得常见。"},{"era":"1861","en":"The verb appears with the literal sense 'to give high lights to' a painting or engraving, formed directly from the noun.","cn":"动词出现，字面义为“给绘画或版画加上高光”，直接由名词构成。"},{"era":"1941 · 1942","en":"Hairdressing takes up both noun and verb: highlights are lighter strands, and to highlight is to make them.","cn":"美发业同时吸收了名词与动词：highlights 指较浅的发缕，to highlight 指做出这种发缕。"},{"era":"1944","en":"The figurative verb 'to give prominence to, emphasize' is recorded, completing the move from paint to speech.","cn":"动词的比喻义“使突出、强调”有记录，完成了从颜料到言辞的转移。"},{"era":"MODERN ENGLISH","en":"Highlighter, the marking pen with transparent ink, is recorded from 1963 as an agent noun of the verb. Highlight reel and screen highlighting are later extensions of the same bright-patch image.","cn":"highlighter 指装透明墨水的标记笔，1963 年作为该动词的施事名词有记录。精彩集锦与屏幕高亮则是同一“亮斑”意象的后续延伸。"}]},"similar":{"note":{"en":"The first group separates the pen, the reel, and the participle from the base word; the second group compares verbs that also try to make something stand out.","cn":"第一组把荧光笔、集锦与分词形式和原词分开；第二组比较同样想让某物显眼的动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"highlighter","ipa":"/ˈhaɪlaɪtə(r)/","tag":"agent noun: the tool","definition":"the pen itself, filled with transparent fluorescent ink. The -er suffix names the instrument, so a highlighter is what does the highlighting.","definitionCN":"指笔本身，内装透明荧光墨水。-er 后缀命名工具，所以荧光笔是执行高亮动作的东西。"},{"word":"highlight reel","ipa":"/ˈhaɪlaɪt riːl/","tag":"fixed compound","definition":"a short compilation of the best moments, mostly in sport and broadcasting. It is a noun phrase, not a verb, and it contains many highlights rather than one.","definitionCN":"把最佳时刻剪成的短片，多用于体育与广播。它是名词短语，不是动词，而且里面装的是许多高光而非一个。"},{"word":"highlighted","ipa":"/ˈhaɪlaɪtɪd/","tag":"participle form","definition":"the past tense or past participle, also used as an adjective for text or hair that has been marked. It describes a finished state, not the act.","definitionCN":"过去式或过去分词，也作形容词指已被标亮的文字或头发。它描述完成后的状态，而不是动作。"}]},{"heading":"NEAR MEANING","entries":[{"word":"emphasize","ipa":"/ˈemfəsaɪz/","tag":"stress in words","definition":"to give special force or importance to a point. Emphasize works mainly through wording, tone, or repetition; highlight works through contrast, as if lighting one spot.","definitionCN":"给某个要点特别的力度或重要性。emphasize 主要靠措辞、语气或重复；highlight 靠对比，像给一处打光。"},{"word":"stress","ipa":"/stres/","tag":"weight on one point","definition":"to put weight on a point so that it is not missed. It is close to emphasize but can also mean to pronounce a syllable with force, a sense highlight does not have.","definitionCN":"把重量压在某个要点上，使人不会漏掉。它接近 emphasize，但也指重读一个音节，这是 highlight 没有的义项。"},{"word":"underline","ipa":"/ˌʌndəˈlaɪn/","tag":"literal line beneath","definition":"to draw a line under words, or figuratively to stress them. The image is a line at the foot of the text, while highlight is a band of light over it.","definitionCN":"在词句下画一条线，或比喻地强调它们。它的意象是文字脚下的一条线，而 highlight 是覆在文字上的一条光带。"},{"word":"spotlight","ipa":"/ˈspɒtlaɪt/","tag":"public attention","definition":"to turn a strong beam on someone, literally or in public attention. It is more dramatic and more often about people and publicity than highlight.","definitionCN":"把强光束打在某人身上，字面或指公众注意。它比 highlight 更戏剧化，也更常指人物与曝光度。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: high plus light, the agent noun highlighter, and the fixed compound highlight reel.","cn":"只用真实成分与真实同族词：high 加 light、施事名词 highlighter，以及固定复合词 highlight reel。"},"normal":[{"en":"High means 'raised, at the top' and light means 'brightness'. Highlight is literally the light at the top of the picture.","cn":"high 表示“高的、在上方的”，light 表示“光”。highlight 字面就是画面上位置最高的那道光。"},{"en":"Add -er and you get the tool: a highlighter is the pen that performs the highlighting.","cn":"加上 -er 就得到工具：highlighter 就是执行高亮动作的那支笔。"},{"en":"A highlight reel is a fixed compound, not a verb phrase: it reels together many bright moments.","cn":"highlight reel 是固定复合名词，不是动词短语：它把许多高光时刻卷到一起。"},{"en":"The noun is older than the verb: painters had highlights in 1650s, but the verb 'to highlight' waited until 1861.","cn":"名词比动词年长：画家在 17 世纪 50 年代就有高光，而动词“加高光”直到 1861 年才出现。"},{"en":"The path from paint to speech is short: a bright patch on a canvas becomes the best part of a trip, then a point a speaker wants you to see.","cn":"从颜料到言辞的路很短：画布上的亮斑变成旅程中最好的部分，再变成说话人想让你看见的要点。"}],"abstract":[{"en":"Picture a dark room and one lamp. Everything the lamp touches becomes the highlight, and everything else becomes background.","cn":"想象一间暗室和一盏灯。灯碰到的一切都成为高光，其余一切退成背景。"},{"en":"The same lamp can be moved: onto a paragraph, onto a problem, onto a person, onto a row of pixels. The word never changes, only the surface does.","cn":"同一盏灯可以挪动：挪到一段文字、一个难题、一个人、一行像素上。词没有变，只是被照的表面变了。"},{"en":"To highlight is also to choose. The bright spot is an argument about what matters, which is why a highlight can expose as much as it praises.","cn":"highlight 同时也是一种选择。亮斑是关于“什么重要”的论证，所以它既能彰显，也能暴露。"}]},"examples":[{"en":"Her report highlights three gaps between policy and practice.","cn":"她的报告突出了政策与实践之间的三处缺口。"},{"en":"The critic called the final scene the highlight of an otherwise slow film.","cn":"评论家称结尾那场戏是这部原本节奏缓慢的影片中最精彩的部分。"},{"en":"Students who highlight almost every line usually remember none of them.","cn":"把几乎每一行都标亮的学生，通常一行也记不住。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“嗨，来照”——嗨，来一束光把它照亮，别处就暗下去 → highlight 高光、强调","word":"highlight"},"root":"由英语 high“高”与 light“光”合成，核心是“光落得最高的那一处，其余部分相对退暗”。","sensesIntro":{"en":"Nine senses of highlight, all grown from one beam: light lands on a single spot, that spot becomes the brightest thing, and whatever we want seen is placed under the same beam.","cn":"highlight 的九个义项都从同一束光长出来：光落在某一点，那一点成为最亮处；凡是我们想让人看见的，都被放到同一束光下。"},"semanticMap":{"core":{"en":"CORE IMAGE: one beam lands on one spot and the rest falls into shadow.","cn":"核心意象：一束光落在一点，其余部分落入阴影。"},"chain":["A BEAM FALLS","ONE SPOT SHINES","THE BRIGHTEST PATCH","THE BEST MOMENT","MARK IT BRIGHT","CALL ATTENTION TO"],"branches":[{"senses":"01 · 03","en":"SURFACE: the beam marks a bright patch on a painting, a photograph, or a head of hair.","cn":"表面：光束在画、照片或头发上留下亮斑。"},{"senses":"02 · 08","en":"BEST MOMENTS: the brightest patch becomes the best part of an event, and many such parts are reeled together.","cn":"最佳时刻：最亮的一块变成活动中最好的部分，许多这样的部分再被卷成集锦。"},{"senses":"04","en":"MARKING: a bright pen lays the same band of light over words on paper.","cn":"标记：亮色笔在纸上给词句铺上同一条光带。"},{"senses":"05 · 06 · 07","en":"ATTENTION: the beam is aimed at a point, a weakness, or a subject, so that others look there first.","cn":"注意：光束被对准一个要点、一处弱点或一个题材，让别人先看那里。"},{"senses":"09","en":"SCREEN: software repeats the painter's gesture, lighting selected text while the rest stays plain.","cn":"屏幕：软件重复画家的动作，把选中的文字照亮，其余保持素净。"}]},"affixes":{"intro":{"en":"Highlight is a native English compound rather than a Latin borrowing: high plus light, later extended by -er, -ed, and -ing, and fixed into compounds such as highlight reel.","cn":"highlight 是英语本土复合词，不是拉丁借词：high 加 light，后来由 -er、-ed、-ing 扩展，并固定成 highlight reel 这类复合词。"},"latinIntro":{"en":"The word itself has no Latin stem, but the idea of 'lighting something up' has Latin-born cousins that English also owns: illustrate, illuminate, and elucidate all go back to Latin words for light.","cn":"这个词本身没有拉丁词干，但“把某物照亮”这一观念有拉丁出身的表亲，英语同样收下了它们：illustrate、illuminate、elucidate 都可追溯到拉丁语中表示“光”的词。"},"items":[{"word":"highlight","structure":"high (adj.) + light (n.)","meaning":"the brightest part; to make something stand out","meaningCN":"最亮的部分；使某物突出（high 高 + light 光）","example":"The highlight of the evening was her short speech.","exampleCN":"那晚最精彩的部分是她那段简短的讲话。"},{"word":"highlights","structure":"highlight + -s (plural or third person)","meaning":"the bright parts; he, she or it highlights","meaningCN":"多处高光；动词第三人称单数（-s 表示复数或三单）","example":"The report's highlights are collected on one page.","exampleCN":"报告的要点被汇总在一页上。"},{"word":"highlighter","structure":"highlight + -er (agent noun)","meaning":"a pen with transparent bright ink","meaningCN":"荧光笔（-er 表示施事工具）","example":"She lent me a yellow highlighter for the exam notes.","exampleCN":"她把一支黄色荧光笔借给我做考试笔记。"},{"word":"highlighted","structure":"highlight + -ed (past participle)","meaning":"marked bright; given prominence","meaningCN":"被标亮的；被突出的（-ed 构成过去分词）","example":"The highlighted names are the ones already confirmed.","exampleCN":"被标亮的名字是已经确认过的那些。"},{"word":"highlighting","structure":"highlight + -ing (gerund or noun)","meaning":"the act of marking bright, or the lighter strands in hair","meaningCN":"标亮的动作；头发的挑染（-ing 构成动名词或名词）","example":"Too much highlighting can damage the ends of the hair.","exampleCN":"挑染过多会损伤发梢。"},{"word":"highlight reel","structure":"highlight + reel (compound noun)","meaning":"a short film of the best moments","meaningCN":"精彩片段集锦（名词复合：高光 + 卷盘）","example":"The league posted a highlight reel within an hour of the match.","exampleCN":"比赛结束一小时内，联盟就发布了精彩集锦。"},{"word":"high","structure":"Old English heh, heah","meaning":"raised, tall, at the top","meaningCN":"高的；在上方的（古英语 heh／heah）","example":"The shelf is too high for the child to reach.","exampleCN":"这个架子太高，孩子够不到。"},{"word":"light","structure":"Old English leoht, from PIE *leuk- 'light, brightness'","meaning":"brightness; that which makes things visible","meaningCN":"光；亮（古英语 leoht，原始印欧语 *leuk-“光、明亮”）","example":"Morning light filled the studio.","exampleCN":"晨光充满了工作室。"},{"word":"enlighten","structure":"en- (make) + lighten (give light)","meaning":"to give someone knowledge or understanding","meaningCN":"启发；使明白（en- 使 + lighten 给光）","example":"The lecture enlightened us about the cause of the crisis.","exampleCN":"这场讲座让我们看清了危机的成因。"},{"word":"illustrate","structure":"Latin in- + lustrare 'to make bright'","meaning":"to make clear by pictures or examples","meaningCN":"说明；图解（拉丁语“使明亮”的另一种走法）","example":"A simple diagram illustrates the water cycle.","exampleCN":"一张简图说明了水循环。"},{"word":"illuminate","structure":"Latin in- + luminare 'to light'","meaning":"to light up; to make clear","meaningCN":"照亮；阐明（拉丁语“给光”）","example":"Lanterns illuminate the narrow street at night.","exampleCN":"夜里灯笼照亮了这条窄街。"},{"word":"elucidate","structure":"Latin e- (out) + lucidus (clear, bright)","meaning":"to explain so that a matter becomes clear","meaningCN":"阐明；解释清楚（拉丁语 lucidus“明亮”）","example":"She elucidated the rules in three sentences.","exampleCN":"她用三句话把规则讲清楚了。"}],"latinEntries":[{"word":"illustrare","structure":"in- (in) + lustrare (make bright)","meaning":"to light up, make bright; figuratively to make clear or distinguished","meaningCN":"照亮；使明亮；比喻为阐明或使显赫"},{"word":"illuminare","structure":"in- (in) + luminare (to light), from lumen (light)","meaning":"to throw light into; to illuminate","meaningCN":"把光投入；照亮"},{"word":"lucidus","structure":"lux, luc- (light) + -idus (adjective)","meaning":"full of light; clear","meaningCN":"明亮的；清楚的"}]}},{"word":"hypothesis","ipa_uk":"/haɪˈpɒθəsɪs/","ipa_us":"/haɪˈpɑːθəsɪs/","definition_zh":"假设；假说；前提；待验证的猜想","definition_en":"a proposed explanation or premise that is put forward as a starting point and still has to be tested or proved","core_image":"先在下面垫一块地基，再把论点垒在上面","scene":"实验室的白板上写着一句可以被实验推翻的预测，旁边是涂层样本。 Before the experiment began, the team wrote one sentence on the whiteboard: the new coating should halve the rate of corrosion. That sentence was their hypothesis.","sceneCN":"这里 hypothesis 是「科学假说」（第 1 个义项：提出一个可检验的候选解释）；句意：实验开始前，团队在白板上写下一句话：新涂层应能把腐蚀速度减半。这句话就是他们的假说。","pos":[{"tag":"n.","zh":"假设；假说（尤指可检验的科学解释）"},{"tag":"n.","zh":"前提；被当作论证起点的命题"}],"collocations":[{"phrase":"formulate a hypothesis","zh":"提出假说"},{"phrase":"test a hypothesis","zh":"检验假说"},{"phrase":"a working hypothesis","zh":"工作假设；暂用假设"},{"phrase":"the null hypothesis","zh":"原假设；零假设"},{"phrase":"on the hypothesis that","zh":"假定……"},{"phrase":"competing hypotheses","zh":"彼此竞争的多种假说"},{"phrase":"support a hypothesis","zh":"支持某一假说"}],"forms":[{"label":"名词复数（希腊语式，-is 变 -es）","form":"hypotheses"}],"derivatives":[{"word":"hypothesize","pos":"v.","zh":"假设；提出假说"},{"word":"hypothetical","pos":"adj.","zh":"假设的；假想的"},{"word":"hypothetically","pos":"adv.","zh":"在假设情况下；假想地"},{"word":"hypothetic","pos":"adj.","zh":"假设的（较少用，与 hypothetical 同义）"}],"senses":[{"no":"01","title":"Scientific hypothesis: a testable explanation","titleCN":"科学假说：可被检验的解释","definition":"a proposed explanation for observed facts that can be tested by experiment or further evidence","definitionCN":"针对观察到的事实提出的解释，可通过实验或进一步证据来检验","example":"The hypothesis that the coating slows corrosion will be tested on twenty steel plates.","exampleCN":"“涂层能减缓腐蚀”这一假说将在二十块钢板上接受检验。","why":"A hypothesis is laid under a question the way a foundation is laid under a building: it is put in place first, and the experiment is built on top of it.","whyCN":"假说被垫在一个问题下面，就像地基被垫在房屋下面：它先被放好，实验再在它上面搭建。"},{"no":"02","title":"Logical premise: assumed as a base","titleCN":"逻辑前提：被当作论证底座","definition":"a proposition taken as true for the sake of an argument, so that other statements can be built on it","definitionCN":"为了进行论证而被当作真的命题，其他陈述可建立在它之上","example":"The proof rests on the hypothesis that every finite set has a largest element.","exampleCN":"这个证明建立在“每个有限集都有最大元素”这一前提之上。","why":"In logic the word keeps its Greek shape: something is placed underneath the reasoning and left there while the argument stands on it.","whyCN":"在逻辑学里，这个词保留了希腊语的形态：某物被放在推理的下方并留在那里，论证则站在它上面。"},{"no":"03","title":"Everyday conjecture: an unproved guess","titleCN":"日常猜想：未经证实的推测","definition":"a guess or suggestion offered without enough evidence, in ordinary speech","definitionCN":"日常言谈中在证据不足时提出的猜测或设想","example":"My hypothesis is that the keys are still in the car.","exampleCN":"我猜钥匙还在车里。","why":"The scientific word has loosened into daily use: any explanation put forward before proof counts as a hypothesis, even when no experiment will follow.","whyCN":"这个科学词已经松动到日常用法里：任何在证实之前提出的解释都算假设，即使后面并不会做实验。"},{"no":"04","title":"Working hypothesis: a temporary guide","titleCN":"工作假设：临时的行动依据","definition":"a provisional explanation accepted for the time being because it guides investigation, even if it may later be replaced","definitionCN":"因能指导调查而暂时接受的解释，即使以后可能被替换","example":"As a working hypothesis, we assume the leak comes from the north pipe.","exampleCN":"作为工作假设，我们先假定泄漏来自北侧管道。","why":"A foundation can be temporary. The working hypothesis is laid down not because it is proved, but because building can start on it today.","whyCN":"地基可以是临时的。工作假设之所以被铺下，不是因为它已被证明，而是因为今天就能在它上面开工。"},{"no":"05","title":"Statistics: the null hypothesis","titleCN":"统计学：原假设","definition":"in statistics, the default proposition that there is no effect or no difference, which a test tries to reject","definitionCN":"统计学中默认“没有效应、没有差异”的命题，检验试图将它推翻","example":"The null hypothesis states that the two groups perform equally well.","exampleCN":"原假设称两组表现同样好。","why":"Here the word is used backwards: the hypothesis laid underneath the test is the dull one, and the whole apparatus is built to knock it down.","whyCN":"这里的用法是反向的：垫在检验下面的假设是最平淡的那一个，整套装置却是为了把它推倒而搭起来的。"},{"no":"06","title":"Plural hypotheses: rival explanations","titleCN":"复数假说：并排的候选解释","definition":"the plural form hypotheses, used when several candidate explanations are held side by side","definitionCN":"复数形式 hypotheses，用于同时持有多个候选解释时","example":"The team listed three hypotheses and designed one test to separate them.","exampleCN":"团队列出三个假说，并设计了一项能区分它们的检验。","why":"The Greek plural keeps the original -is to -es shift. Once several foundations are laid, the question is which one the evidence will stand on.","whyCN":"希腊语式复数保留了 -is 变 -es 的变化。一旦铺下好几块地基，问题就变成证据会站在哪一块上。"},{"no":"07","title":"Mathematics: a conjecture awaiting proof","titleCN":"数学：等待证明的猜想","definition":"in mathematics, a statement believed to be true but not yet proved, such as a named conjecture","definitionCN":"数学中相信为真但尚未证明的陈述，如以人名命名的猜想","example":"The Riemann hypothesis has resisted proof for more than a century.","exampleCN":"黎曼猜想已有一个多世纪未能被证明。","why":"The mathematical hypothesis is a foundation laid under a whole building that does not yet exist: if it holds, a large structure of proofs can be raised.","whyCN":"数学猜想是垫在一整座尚未存在的建筑下面的地基：只要它成立，一大片证明就能被垒起来。"},{"no":"08","title":"On the hypothesis that: a supposition for argument","titleCN":"以假设为前提：为了推论而假定","definition":"in the phrase 'on the hypothesis that', used to grant a supposition temporarily and then reason from it","definitionCN":"在短语 on the hypothesis that 中，暂时承认某一设想并由此推理","example":"On the hypothesis that demand stays flat, the new factory would still lose money.","exampleCN":"假定需求保持不变，新工厂仍然会亏损。","why":"The phrase marks the foundation being laid on purpose: everyone agrees to stand on it for the length of the argument, and no longer.","whyCN":"这个短语标记的是有意铺下的地基：大家同意在论证期间站上去，论证一结束就不再站了。"},{"no":"09","title":"Original sense: a groundwork","titleCN":"本义：垫在下面的基础","definition":"in the earliest English use, a particular statement or groundwork on which other statements rest","definitionCN":"在最早的英语用法中，指承载其他陈述的某一说法或基础","example":"The old logic text calls the first principle the hypothesis of the whole argument.","exampleCN":"那本旧逻辑教材把第一原理称为整个论证的基础。","why":"Greek hypothesis literally meant 'a placing under', the base or groundwork of a building. The logical sense grew from that physical picture.","whyCN":"希腊语 hypothesis 字面意为“放在下面”，即建筑的地基或底座。逻辑义正是从这幅物理画面长出来的。"}],"etymology":{"intro":{"en":"Hypothesis is a Greek word borrowed through French and Latin, and its parts are still visible: hypo- 'under' plus thesis 'a placing'. Dates are approximate.","cn":"hypothesis 是经法语和拉丁语借入的希腊词，构词成分至今可见：hypo-“在下”加 thesis“放置”。年代为大致估计。"},"items":[{"era":"1590s","en":"First recorded in English meaning 'a particular statement'. The word entered through French hypothese and directly from Late Latin hypothesis.","cn":"英语中最早记录于 16 世纪 90 年代，意为“某一具体陈述”。这个词经法语 hypothese 并直接由晚期拉丁语 hypothesis 进入英语。"},{"era":"1650s","en":"The sense 'a proposition assumed and taken for granted, used as a premise' is recorded, the sense that still governs logic and argument.","cn":"记录到“被假定并视为当然、用作前提的命题”这一义项，这也是至今支配逻辑与论证的义项。"},{"era":"GREEK","en":"Greek hypothesis meant 'base, groundwork, foundation', and in extended use 'basis of an argument, supposition', literally 'a placing under'.","cn":"希腊语 hypothesis 意为“底座、地基、基础”，引申为“论证的基础、设想”，字面即“放在下面”。"},{"era":"GREEK hypo- + thesis","en":"The word joins hypo- 'under' and thesis 'a placing, proposition'. Thesis goes back to a reduplicated form of PIE *dhe- 'to set, put', the root also behind do, deed, and theme.","cn":"这个词由 hypo-“在下”与 thesis“放置、命题”组合而成。thesis 可追溯到原始印欧语 *dhe-“放置、安放”的重复形式，该词根也是 do、deed、theme 的来源。"},{"era":"1640s","en":"The narrower scientific sense, an explanation to be tested, is recorded. From this point the word belongs to experiment as much as to logic.","cn":"较窄的科学义“待检验的解释”有记录。自此这个词既属于逻辑，也属于实验。"},{"era":"MODERN ENGLISH","en":"The Greek plural hypotheses is kept unchanged, unlike most English nouns. Hypothetical (1580s) and hypothesize (1738) build the rest of the family; theory and thesis remain distinct neighbours.","cn":"希腊语式复数 hypotheses 原样保留，与大多数英语名词不同。hypothetical（16 世纪 80 年代）与 hypothesize（1738）补足了词族；theory 与 thesis 仍是各自独立的邻词。"}]},"similar":{"note":{"en":"The first group separates the plural, the adjective, and the verb built on hypothesis; the second group compares words for explanations and for premises.","cn":"第一组把复数、形容词和由 hypothesis 构成的动词分开；第二组比较表示“解释”与“前提”的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"hypotheses","ipa":"/haɪˈpɒθəsiːz/","tag":"irregular plural","definition":"the plural of hypothesis, not a different word. Greek nouns in -is regularly become -es, so one hypothesis becomes two hypotheses.","definitionCN":"hypothesis 的复数，不是另一个词。以 -is 结尾的希腊语名词通常变 -es，所以一个假说变成两个假说。"},{"word":"hypothetical","ipa":"/haɪˈpɒθetɪkl/","tag":"adjective","definition":"based on a hypothesis or imagined for the sake of argument. It describes a situation, not a scientific claim, and is often close to 'imaginary'.","definitionCN":"基于假设的，或为论证而设想的。它描述一种情形，而不是一条科学主张，常接近“虚构的”。"},{"word":"hypothesize","ipa":"/haɪˈpɒθəsaɪz/","tag":"verb","definition":"to form a hypothesis. The verb names the act of laying the foundation; the noun names the foundation itself.","definitionCN":"提出假说。动词命名“铺地基”的动作，名词命名地基本身。"}]},{"heading":"NEAR MEANING","entries":[{"word":"theory","ipa":"/ˈθiəri/","tag":"built system of explanation","definition":"a coherent set of principles that explains a broad class of facts. A theory is a finished building; a hypothesis is the foundation stone laid before the building is tested.","definitionCN":"解释一大类事实的连贯原理体系。theory 是建成的房屋；hypothesis 是房屋受检前铺下的奠基石。"},{"word":"thesis","ipa":"/ˈθiːsɪs/","tag":"statement to be defended","definition":"a proposition put forward and defended in argument, or a long research essay. It shares Greek thesis 'a placing' with hypothesis, but stands on its own rather than under something else.","definitionCN":"在论证中提出并加以辩护的命题，或长篇研究论文。它与 hypothesis 共享希腊语 thesis“放置”，但它是自己站着的，而不是垫在别物之下。"},{"word":"supposition","ipa":"/ˌsʌpəˈzɪʃn/","tag":"assumption for argument","definition":"something assumed to be true for the sake of reasoning. It is a near translation of Greek hypothesis and carries less scientific weight.","definitionCN":"为推理而假定为真的事。它几乎是希腊语 hypothesis 的译法，科学分量更轻。"},{"word":"conjecture","ipa":"/kənˈdʒektʃə(r)/","tag":"guess from incomplete evidence","definition":"an opinion formed from incomplete evidence. A conjecture is openly a guess; a hypothesis is a guess set up so that it can be tested.","definitionCN":"根据不完整证据形成的看法。conjecture 明说是猜测；hypothesis 则是为了让其可被检验而搭起来的猜测。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: hypo- 'under', thesis 'a placing', the Greek plural hypotheses, and the family hypothetical / hypothesize.","cn":"只用真实成分与真实同族词：hypo-“在下”、thesis“放置”、希腊语式复数 hypotheses，以及 hypothetical／hypothesize 词族。"},"normal":[{"en":"hypo- means 'under' and thesis means 'a placing'. A hypothesis is something placed under a question so that reasoning can stand on it.","cn":"hypo- 表示“在下”，thesis 表示“放置”。hypothesis 就是被放在问题下面、让推理可以站上去的东西。"},{"en":"The plural is hypotheses, not hypothesises: Greek -is becomes -es, as in analysis and basis.","cn":"复数是 hypotheses，不是 hypothesises：希腊语式 -is 变 -es，如 analysis、basis 一样。"},{"en":"Hypothetical means 'assumed for the sake of argument', and hypothesize means 'to lay that foundation down'.","cn":"hypothetical 意为“为论证而假设的”，hypothesize 意为“把这块地基铺下去”。"},{"en":"A hypothesis and a thesis share thesis 'a placing', but a thesis stands up to be defended while a hypothesis lies underneath to be tested.","cn":"hypothesis 与 thesis 共享 thesis“放置”，但 thesis 立起来供人辩护，hypothesis 则躺在下面等着被检验。"},{"en":"The null hypothesis is the dull foundation: it says there is no effect, and the experiment is built to knock it down.","cn":"原假设是最平淡的地基：它宣称没有效应，而实验正是为了把它推倒而搭起来的。"}],"abstract":[{"en":"Picture a stone slab laid in soft ground. Nothing is built yet, and the slab may sink or hold, but every later brick depends on it.","cn":"想象一块石板被铺进软土里。上面还没有建筑，石板可能下沉也可能撑住，但后来的每一块砖都依赖它。"},{"en":"A hypothesis is a bet you can lose: the good ones are laid where a test can reach them, not where they are safe from evidence.","cn":"假说是一场你可以输掉的赌：好的假说被铺在检验够得着的地方，而不是铺在证据碰不到的安全角落。"},{"en":"When several foundations lie side by side, the experiment is not looking for support but for separation: which slab alone can carry the building?","cn":"当好几块地基并排铺着，实验要找的不是支撑而是区分：哪一块独自能承起这座建筑？"}]},"examples":[{"en":"Every experiment begins with a hypothesis, but few survive the first week.","cn":"每个实验都从一个假说开始，但很少有假说能熬过第一周。"},{"en":"She treated the rumour as a working hypothesis and went to check the records.","cn":"她把这个传闻当作工作假设，然后去查记录。"},{"en":"The two hypotheses predict different results, which is exactly why the test is worth running.","cn":"两个假说预测出不同的结果，这正是这项检验值得做的原因。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“嗨，破塞西斯”——嗨，先破开地面、塞一块石板在下面当底座，上面再放待验的想法 → hypothesis 假设、前提","word":"hypothesis"},"root":"源自希腊语 hypothesis“垫在下面的地基”，由 hypo-“在下”+ thesis“放置”构成，核心是“先垫一块地基，让论点立在上面”。","sensesIntro":{"en":"Nine senses of hypothesis, all from one gesture: something is placed underneath — a question, an argument, a test, a proof — so that reasoning can stand on it and later be knocked down.","cn":"hypothesis 的九个义项都来自同一个动作：把某物垫在下面——问题、论证、检验、证明——让推理站上去，并在以后被推倒。"},"semanticMap":{"core":{"en":"CORE IMAGE: a slab laid under a structure that is still to be built and tested.","cn":"核心意象：一块石板铺在尚待建造、尚待检验的结构之下。"},"chain":["PUT UNDER","A BASE LAID","A PROPOSITION SET DOWN","TREATED AS A STARTING POINT","PUT TO THE TEST","PROVED OR DROPPED"],"branches":[{"senses":"01 · 07","en":"TESTABLE CLAIMS: science and mathematics lay a claim underneath and then try to break it with evidence or proof.","cn":"可检验的主张：科学与数学把一条主张垫在下面，再用证据或证明去击打它。"},{"senses":"02 · 08 · 09","en":"FOUNDATION: logic, argumentative supposition, and the oldest sense all keep the literal groundwork.","cn":"地基：逻辑前提、论证中的假定与最古老的义项，都保留了字面上的“垫在下面”。"},{"senses":"03 · 04","en":"GUESS AND TOOL: daily conjecture has no test attached, while a working hypothesis is laid down so that work can start today.","cn":"猜想与工具：日常猜测后面没有检验，而工作假设被铺下是为了今天就能开工。"},{"senses":"05","en":"STATISTICS: the null hypothesis is the plain foundation that the whole test is built to demolish.","cn":"统计学：原假设是最朴素的地基，整套检验却是为了拆掉它而建。"},{"senses":"06","en":"RIVALS: several hypotheses stand side by side, and the evidence must choose which slab to stand on.","cn":"竞争者：多个假说并排而立，证据必须选择站上哪一块石板。"}]},"affixes":{"intro":{"en":"Hypothesis is a Greek compound borrowed whole: hypo- 'under' plus thesis 'a placing'. English adds -ical, -ly, and -ize, and the same two Greek pieces build a large family.","cn":"hypothesis 是整体借入的希腊语复合词：hypo-“在下”加 thesis“放置”。英语加上 -ical、-ly、-ize，同样两个希腊成分还构成一大群词。"},"latinIntro":{"en":"Late Latin took the Greek word unchanged as hypothesis, and Latin thesis came from the same Greek noun. Medieval Latin suppositio was used to translate hypothesis, which is why supposition still feels like its twin.","cn":"晚期拉丁语原样吸收了希腊词 hypothesis，拉丁语 thesis 也来自同一个希腊名词。中世纪拉丁语用 suppositio 翻译 hypothesis，所以 supposition 至今像是它的双胞胎。"},"items":[{"word":"hypothesis","structure":"hypo- (under) + thesis (a placing)","meaning":"a proposition placed under an argument; a testable explanation","meaningCN":"垫在论证下面的命题；可检验的解释（hypo- 在下 + thesis 放置）","example":"The hypothesis was rejected after the second trial.","exampleCN":"第二次试验之后，这个假说被否定了。"},{"word":"hypotheses","structure":"hypothesis + Greek plural -es","meaning":"two or more hypotheses","meaningCN":"两个或更多假说（希腊语式复数 -es）","example":"Both hypotheses assume the same starting temperature.","exampleCN":"两个假说都假定相同的初始温度。"},{"word":"hypothetical","structure":"hypothet- + -ical (adjective)","meaning":"based on a hypothesis; imagined for argument","meaningCN":"假设的；为论证而假想的（-ical 构成形容词）","example":"Consider a hypothetical case in which no one answers.","exampleCN":"设想一个无人应答的假想情形。"},{"word":"hypothetically","structure":"hypothetical + -ly (adverb)","meaning":"in an assumed or imagined situation","meaningCN":"在假设或假想的情况下（-ly 构成副词）","example":"Hypothetically, the plan could work if costs fell.","exampleCN":"假定成本下降，这个计划理论上可行。"},{"word":"hypothesize","structure":"hypothesis + -ize (verb)","meaning":"to form a hypothesis","meaningCN":"提出假说（-ize 构成动词）","example":"Researchers hypothesize that the sound guides the fish home.","exampleCN":"研究者假设这种声音能引导鱼回到出生地。"},{"word":"hypodermic","structure":"hypo- (under) + derma (skin) + -ic","meaning":"under the skin, as an injection","meaningCN":"皮下的（如皮下注射；hypo- 在下 + derma 皮肤）","example":"The nurse prepared a hypodermic needle.","exampleCN":"护士准备好了一支皮下注射针。"},{"word":"hypothermia","structure":"hypo- (under) + therme (heat) + -ia","meaning":"a body temperature dangerously below normal","meaningCN":"低体温；体温过低（hypo- 在下 + therme 热）","example":"The climbers were treated for hypothermia.","exampleCN":"登山者接受了低体温治疗。"},{"word":"thesis","structure":"Greek thesis 'a placing, proposition'","meaning":"a proposition to be defended; a long research essay","meaningCN":"待辩护的命题；长篇研究论文（希腊语“放置、命题”）","example":"Her thesis argues that the two reforms were one process.","exampleCN":"她的论文主张这两场改革其实是一个过程。"},{"word":"antithesis","structure":"anti- (against) + thesis (placing)","meaning":"the direct opposite of a proposition","meaningCN":"对立命题；正相反的说法（anti- 反对 + thesis 放置）","example":"His calm manner is the antithesis of her urgency.","exampleCN":"他的从容正是她那种急切的对照。"},{"word":"synthesis","structure":"syn- (together) + thesis (placing)","meaning":"a putting together of parts into a whole","meaningCN":"综合；合成（syn- 一起 + thesis 放置）","example":"The book is a synthesis of history and economics.","exampleCN":"这本书是历史学与经济学的综合。"},{"word":"parenthesis","structure":"para- (beside) + en- (in) + thesis (placing)","meaning":"a phrase placed beside the main sentence; a bracket","meaningCN":"插入语；圆括号（para- 旁 + en- 内 + thesis 放置）","example":"The date appears in parentheses at the end.","exampleCN":"日期放在末尾的圆括号里。"}],"latinEntries":[{"word":"hypothesis","structure":"Greek hypo- (under) + thesis (a placing)","meaning":"base, groundwork; basis of an argument","meaningCN":"地基、基础；论证的依据（晚期拉丁语原样借入）"},{"word":"thesis","structure":"Greek thesis, from PIE *dhe- 'to set, put'","meaning":"a placing; a proposition","meaningCN":"放置；命题"},{"word":"suppositio","structure":"sub- (under) + positio (a placing)","meaning":"a putting under; assumption, used to translate Greek hypothesis","meaningCN":"放在下面；假定（中世纪拉丁语用来翻译希腊语 hypothesis）"}]}},{"word":"identify","ipa_uk":"/aɪˈdentɪfaɪ/","ipa_us":"/aɪˈdentɪfaɪ/","definition_zh":"辨认；识别；确认身份；找出（根源）；认同","definition_en":"to establish who or what something is, to point to its source, or to feel oneself to be the same as another","core_image":"把两枚指纹并排对齐，确认它们属于同一个人","scene":"边检柜台前，工作人员把护照照片放在乘客旁边。 The border officer put the passport photo beside the passenger and asked her to identify the person in the photo as herself.","sceneCN":"这里 identify 是「辨认出、确认身份」（第 1 个义项：确认某人或某物究竟是谁、是什么）；句意：边检人员把护照照片放在乘客旁边，请她辨认照片上的人就是她本人。","pos":[{"tag":"v.","zh":"辨认出；识别；确认身份"},{"tag":"v.","zh":"找出；确定（原因、来源）；认同（与 identify with 连用）"}],"collocations":[{"phrase":"identify the cause","zh":"查明原因"},{"phrase":"identify a suspect","zh":"指认嫌疑人"},{"phrase":"identify with someone","zh":"与某人产生共鸣；认同某人"},{"phrase":"identify oneself","zh":"表明自己的身份"},{"phrase":"identify a species","zh":"鉴定物种"},{"phrase":"identify a trend","zh":"识别出一种趋势"},{"phrase":"be identified as","zh":"被认定为"}],"forms":[{"label":"第三人称单数","form":"identifies"},{"label":"过去式","form":"identified"},{"label":"过去分词","form":"identified"},{"label":"现在分词","form":"identifying"}],"derivatives":[{"word":"identity","pos":"n.","zh":"身份；同一性；特性"},{"word":"identification","pos":"n.","zh":"识别；身份证明；认同"},{"word":"identifier","pos":"n.","zh":"标识符；识别符号"},{"word":"identifiable","pos":"adj.","zh":"可辨认的；可识别的"},{"word":"unidentified","pos":"adj.","zh":"身份不明的；未经确认的"},{"word":"misidentify","pos":"v.","zh":"误认；错误地识别"}],"senses":[{"no":"01","title":"Establish who or what something is","titleCN":"确认是谁、是什么","definition":"to establish the identity of a person or thing, especially by checking it against known information","definitionCN":"确认某人或某物的身份，尤指通过与已知信息比对来确认","example":"The officer identified the passenger from her passport photo.","exampleCN":"边检人员根据护照照片确认了这位乘客的身份。","why":"Identity comes from Latin idem, 'the same'. To identify is to hold up two things and find that they are one, so a face and a photograph are matched into a single person.","whyCN":"identity 来自拉丁语 idem“同一个”。identify 就是把两样东西举起来比对，发现它们其实是一个，于是一张脸与一张照片被配成同一个人。"},{"no":"02","title":"Regard as the same: the original sense","titleCN":"认定同一：最早的义项","definition":"to treat two things as being the same thing, or as belonging to the same class","definitionCN":"把两样东西视为同一物，或视为属于同一类","example":"Early critics identified the two paintings as copies of one original.","exampleCN":"早期的评论者认定这两幅画是同一原作的两件摹本。","why":"The word entered English in the 1640s meaning 'regard as the same'. The judgement of sameness came first; recognising a particular person came a century later.","whyCN":"这个词在 17 世纪 40 年代进入英语时意为“视为同一”。“判断相同”先出现，辨认某个具体的人则晚了一个世纪。"},{"no":"03","title":"Pinpoint: find the source or cause","titleCN":"找出根源：锁定位置","definition":"to find or determine exactly where a problem, source, or cause lies","definitionCN":"准确找出问题、来源或原因所在之处","example":"Engineers identified the leak as a cracked joint under the floor.","exampleCN":"工程师查明泄漏来自地板下的一处裂口接缝。","why":"If identity is sameness, tracing an effect back to its cause is a matching too: the fault on the floor is found to be the same thing as the fault in the system.","whyCN":"如果身份就是“相同”，那么把结果追溯回原因也是一种配对：地板下的那处缺陷被确认与系统里的那处缺陷是同一个。"},{"no":"04","title":"Recognise a pattern or opportunity","titleCN":"识别出模式或机会","definition":"to notice and name a pattern, trend, or chance that is not obvious at first","definitionCN":"察觉并说出一个起初并不明显的模式、趋势或机会","example":"The analyst identified a shift in how young buyers spend.","exampleCN":"分析师识别出年轻买家花钱方式上的一个转变。","why":"A pattern is a sameness across separate cases. Once scattered instances are seen as one shape, the shape has been identified.","whyCN":"模式是分散个案之间的“相同”。一旦散落的实例被看成一个形状，这个形状就被识别出来了。"},{"no":"05","title":"Identify with: feel the same as another","titleCN":"产生共鸣：把自己放进对方","definition":"in the phrase 'identify with', to feel that you share another person's experience or character","definitionCN":"在 identify with 这一说法中，感到自己与另一个人的经历或性格相通","example":"Many readers identify with the narrator's fear of being watched.","exampleCN":"许多读者对叙述者那种被注视的恐惧产生共鸣。","why":"The sense 'make oneself one with' is recorded from 1780. Here the sameness is felt rather than proved: the boundary between self and other temporarily thins.","whyCN":"“使自己与……成为一体”的义项从 1780 年起有记录。这里的“相同”是被感受到的，而不是被证明的：自我与他者的边界暂时变薄。"},{"no":"06","title":"Identify oneself: state who you are","titleCN":"表明身份：主动报出自己","definition":"to say or show who you are, especially to an official or at an entrance","definitionCN":"说出或出示自己是谁，尤指向官员或在入口处","example":"Visitors must identify themselves at the front desk.","exampleCN":"访客必须在前台表明身份。","why":"The same matching is now performed by the person: you supply the name or badge that lets the other side complete the pair.","whyCN":"这一次配对由本人完成：你提供姓名或证件，让对方把这一对信息配齐。"},{"no":"07","title":"Identify A with B: treat as equivalent","titleCN":"把甲等同于乙","definition":"to treat one thing as the same as another, or to see one as the cause or symbol of the other","definitionCN":"把一物视为与另一物相同，或把一物看作另一物的原因或象征","example":"The old theory identified heat with motion of particles.","exampleCN":"旧理论把热等同于粒子的运动。","why":"Here sameness is asserted rather than discovered: two categories are declared to be one, and the sentence says where the equals sign goes.","whyCN":"这里的“相同”是被宣告的，而不是被发现的：两个范畴被宣布为一个，句子所做的就是指明等号该放在哪里。"},{"no":"08","title":"Serve as a means of identification","titleCN":"用作识别标志","definition":"of a mark, number, or feature, to make it possible for others to tell what something is","definitionCN":"指标记、编号或特征使别人能够判断某物是什么","example":"Each bird is tagged with a band that identifies its colony.","exampleCN":"每只鸟都戴着一个标明其群体的环志。","why":"This sense, recorded by 1886, shifts the work to the object: the mark does the matching on your behalf, so identification can happen without a person doing it.","whyCN":"这一义项到 1886 年有记录，把工作交给了物件：标记代替你完成配对，于是识别可以在无人操作的情况下发生。"},{"no":"09","title":"Biology: determine a species","titleCN":"生物分类：鉴定物种","definition":"to determine which species or category an organism or specimen belongs to","definitionCN":"确定某生物或标本属于哪个物种或类别","example":"The students identified the beetle with a key and a hand lens.","exampleCN":"学生们用检索表和放大镜鉴定了那只甲虫。","why":"A species is a class defined by shared traits. Naming the specimen is a formal matching of one individual against the class it is the same as.","whyCN":"物种是由共同特征定义的类别。为标本命名，就是把一个个体与它所相同的那个类别做一次正式配对。"}],"etymology":{"intro":{"en":"Identify is a French-shaped verb built on identity, whose Latin core is idem, 'the same'. Every sense is a version of matching two things into one. Dates are approximate.","cn":"identify 是法语形的动词，建立在 identity 之上，其拉丁核心是 idem“同一个”。每个义项都是把两样东西配成一体的变体。年代为大致估计。"},"items":[{"era":"1640s","en":"First recorded in English meaning 'regard as the same', from French identifier, which was formed on identité.","cn":"英语中最早记录于 17 世纪 40 年代，意为“视为同一”，来自法语 identifier，后者由 identité 构成。"},{"era":"c. 1600 · identity","en":"The noun identity is recorded from about 1600, meaning 'sameness, oneness, state of being the same', from French identité (14c.) and Medieval Latin identitatem, from Latin idem 'the same'.","cn":"名词 identity 约从 1600 年起有记录，意为“相同、同一、处于相同状态”，来自法语 identité（14 世纪）与中世纪拉丁语 identitatem，再上溯拉丁语 idem“同一个”。"},{"era":"1560s · earlier form","en":"An earlier English form was idemptitie, from Medieval Latin idemptitas. It was replaced by the French-shaped identity.","cn":"英语更早的形式是 idemptitie，来自中世纪拉丁语 idemptitas。后来被法语形的 identity 取代。"},{"era":"1769","en":"The modern everyday sense, 'determine the identity of, recognise as or prove to be the same', is recorded.","cn":"现代日常义“确定……的身份、辨认出或证明为同一”有记录。"},{"era":"1780","en":"The sense 'make oneself one with, associate oneself, regard oneself as the essence of' appears; it leads to identify with and to self-identification.","cn":"出现“使自己与……成为一体、与……相联系、把自己视为其本质”的义项；它发展出 identify with 与自我认同。"},{"era":"1886 · MODERN","en":"The sense 'serve as a means of identification' is attested, which gives numbered tags and identifiers. The suffix -ify is the Latin-derived verb ending also seen in clarify and classify.","cn":"“用作识别标志”的义项有记录，由此产生编号标签与标识符。后缀 -ify 是拉丁来源的动词词尾，也见于 clarify 与 classify。"}]},"similar":{"note":{"en":"The first group separates the noun, the process noun, and the phrase identify with; the second group compares other verbs of recognition and sorting.","cn":"第一组把名词、过程名词与 identify with 这个短语分开；第二组比较其他表示辨认与归类的动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"identity","ipa":"/aɪˈdentəti/","tag":"noun: the sameness","definition":"who someone is, or the state of being the same. It is the noun behind the verb: identify is the act, identity is the result.","definitionCN":"某人是谁，或处于相同的状态。它是动词背后的名词：identify 是动作，identity 是结果。"},{"word":"identification","ipa":"/aɪˌdentɪfɪˈkeɪʃn/","tag":"process noun","definition":"the act or process of identifying, or an official document that proves who you are. It names the procedure or the paper, not the person's identity.","definitionCN":"识别的动作或过程，也指证明身份的官方文件。它命名程序或纸张，而不是那个人的身份。"},{"word":"identify with","ipa":"/aɪˈdentɪfaɪ wɪð/","tag":"phrasal use","definition":"to feel that another's experience is your own. The preposition changes the direction: identity is matched inward, not checked against a record outside.","definitionCN":"感到别人的经历就是自己的。这个介词改变了方向：身份是向内配对，而不是拿外部记录来核对。"}]},{"heading":"NEAR MEANING","entries":[{"word":"recognize","ipa":"/ˈrekəɡnaɪz/","tag":"know again","definition":"to know someone or something because you have met it before. Recognize is memory-based; identify can be done from a document or a test with no memory at all.","definitionCN":"因为以前见过而认出某人或某物。recognize 依赖记忆；identify 可以靠文件或检测完成，完全不需要记忆。"},{"word":"distinguish","ipa":"/dɪˈstɪŋɡwɪʃ/","tag":"tell apart","definition":"to see the difference between two things. Distinguish separates; identify settles which one it is.","definitionCN":"看出两物之间的差别。distinguish 把两者分开；identify 则确定它是其中的哪一个。"},{"word":"pinpoint","ipa":"/ˈpɪnpɔɪnt/","tag":"exact location","definition":"to locate something exactly. It stresses precision of place or moment, while identify stresses the correctness of the answer.","definitionCN":"精确地确定位置。它强调地点或时刻的准确，identify 强调答案的正确。"},{"word":"classify","ipa":"/ˈklæsɪfaɪ/","tag":"put into a class","definition":"to arrange things into groups by shared features. Classify sorts many items; identify names one item's place in that order.","definitionCN":"按共同特征把事物分组。classify 对许多项目排序；identify 指出单个项目在这个秩序中的位置。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: Latin idem 'the same', the noun identity, the process noun identification, and the phrase identify with.","cn":"只用真实成分与真实同族词：拉丁语 idem“同一个”、名词 identity、过程名词 identification，以及短语 identify with。"},"normal":[{"en":"The core is idem, 'the same'. Identify is the verb of deciding that two things are one.","cn":"核心是 idem“同一个”。identify 就是判定两样东西其实是一个的动作。"},{"en":"Identity is the result, identification is the process or the papers, and identify is the act.","cn":"identity 是结果，identification 是过程或证件，identify 是动作。"},{"en":"The suffix -ify makes verbs, as in clarify and classify; identify means 'to make same' in the sense of 'to establish as the same'.","cn":"后缀 -ify 构成动词，如 clarify、classify；identify 意为“使同一”，实际指“确认其为同一”。"},{"en":"identify with reverses the direction: instead of checking an outside record, you find the other person inside yourself.","cn":"identify with 把方向倒过来：不是核对外部记录，而是在自己心里找到对方。"},{"en":"The earliest English sense was 'regard as the same', so the word began as a judgement, not as a police procedure.","cn":"最早的英语义项是“视为同一”，所以这个词起初是一个判断，而不是一道查验手续。"}],"abstract":[{"en":"Picture two fingerprints laid side by side under a lamp. The moment the ridges line up, the pair collapses into one identity.","cn":"想象两枚指纹在灯下并排摆着。纹路对上的那一刻，这一对就收成了一个身份。"},{"en":"The same gesture works at any scale: a face and a photo, a symptom and a cause, three scattered sales and one trend.","cn":"同一个动作在任何尺度上都成立：一张脸与一张照片、一个症状与一个病因、三笔散落的销售与一个趋势。"},{"en":"What cannot be matched is not yet identified. That is why a mistaken match is worse than an admitted uncertainty.","cn":"配不上的东西就还没有被识别。这也是为什么配错比承认不确定更糟。"}]},"examples":[{"en":"The study identified three habits that predict later failure.","cn":"这项研究找出了三个能预测后来失败的习惯。"},{"en":"He identified with the character long before he understood why.","cn":"他还没弄明白原因，就已经对那个角色产生了共鸣。"},{"en":"Every sample was identified and logged before the lab closed.","cn":"实验室关闭前，每个样本都已被鉴定并登记。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“爱登提法”——爱登拿着身份证，把照片和人脸一提一对比，确认是同一个人 → identify 辨认、确认身份","word":"identify"},"root":"源自拉丁语 idem“同一个”（经法语 identité、identifier 进入英语），核心是“把两样东西对齐，确认它们是同一个”。","sensesIntro":{"en":"Nine senses of identify, all grown from one act: two things are set side by side, and a judgement is made that they are the same — a face, a cause, a pattern, a species, or the self.","cn":"identify 的九个义项都从同一个动作长出来：把两样东西并排放好，然后判定它们是同一个——一张脸、一个病因、一个模式、一个物种，或自我本身。"},"semanticMap":{"core":{"en":"CORE IMAGE: two things held side by side until they prove to be one.","cn":"核心意象：两样东西并排举起，直到证实它们是一个。"},"chain":["TWO THINGS RAISED","LAID SIDE BY SIDE","FOUND TO BE THE SAME","NAMED AS ONE","TRACED TO ITS SOURCE","MADE ONE WITH THE SELF"],"branches":[{"senses":"01 · 02 · 09","en":"MATCHING: a person, a copy, or a specimen is matched against what it should be the same as.","cn":"配对：人、摹本或标本被拿去与它应当相同的对象比对。"},{"senses":"03 · 04","en":"TRACING: an effect is matched back to its cause, and scattered cases are seen as one pattern.","cn":"追溯：结果被反向配到原因上，散落的个案被看成一个模式。"},{"senses":"05","en":"INWARD: the match is felt rather than proved, and the line between self and other thins.","cn":"向内：配对靠感受而非证明，自我与他者的界线变薄。"},{"senses":"06 · 07","en":"DECLARING: the person supplies the missing half, or two categories are declared equal.","cn":"宣告：本人补上缺失的另一半，或两个范畴被宣布相等。"},{"senses":"08","en":"DELEGATED: a tag or number does the matching on your behalf, so the object identifies itself.","cn":"代劳：标签或编号替你完成配对，于是物件自己完成了识别。"}]},"affixes":{"intro":{"en":"Identify is built on the Latin stem idem 'the same', carried through French identity and then given the verb suffix -ify. The same stem yields identity, identification, and identifier.","cn":"identify 建立在拉丁词干 idem“同一个”上，经法语 identity 传递，再加动词后缀 -ify。同一词干还给出 identity、identification 与 identifier。"},"latinIntro":{"en":"The Latin core is idem 'the same', whose neuter form supplies the ident- stem. Medieval Latin made identitas from it, French made identité, and English made both identity and the verb identify.","cn":"拉丁核心是 idem“同一个”，其中性形式提供 ident- 词干。中世纪拉丁语由此造出 identitas，法语造出 identité，英语则造出 identity 与动词 identify。"},"items":[{"word":"identify","structure":"ident- (same) + -ify (make, verb)","meaning":"to establish as the same; to recognise","meaningCN":"确认为同一；辨认（ident- 相同 + -ify 使……）","example":"Can you identify the man in this photograph?","exampleCN":"你能认出这张照片里的男人吗？"},{"word":"identity","structure":"ident- + -ity (state noun)","meaning":"who a person is; the state of being the same","meaningCN":"身份；同一性（-ity 构成状态名词）","example":"The witness refused to reveal her identity.","exampleCN":"证人拒绝透露自己的身份。"},{"word":"identification","structure":"identify + -ication (process noun)","meaning":"the act of identifying; proof of who one is","meaningCN":"识别；身份证明（-ication 构成过程名词）","example":"Bring identification to the interview.","exampleCN":"面试时请带上身份证明。"},{"word":"identifier","structure":"identify + -er (agent or instrument)","meaning":"a name, number, or symbol that identifies something","meaningCN":"标识符；识别符号（-er 表示施事或工具）","example":"Each parcel carries a unique identifier.","exampleCN":"每个包裹都带有一个唯一标识符。"},{"word":"identifiable","structure":"identify + -able (able to be)","meaning":"able to be recognised","meaningCN":"可辨认的（-able 表示能够被）","example":"The bird is identifiable by its red tail.","exampleCN":"这种鸟可通过红色尾羽辨认。"},{"word":"unidentified","structure":"un- (not) + identified","meaning":"not yet recognised or named","meaningCN":"身份不明的；未经确认的（un- 表示否定）","example":"An unidentified object appeared on the radar.","exampleCN":"雷达上出现了一个不明物体。"},{"word":"misidentify","structure":"mis- (wrongly) + identify","meaning":"to recognise something incorrectly","meaningCN":"误认；错误识别（mis- 表示错误）","example":"The guide misidentified the mushroom as edible.","exampleCN":"向导把那种蘑菇误认为可食用。"},{"word":"identical","structure":"ident- + -ical (adjective)","meaning":"exactly the same","meaningCN":"完全相同的（-ical 构成形容词）","example":"The twins wore identical coats.","exampleCN":"双胞胎穿着完全相同的外套。"},{"word":"identically","structure":"identical + -ly (adverb)","meaning":"in exactly the same way","meaningCN":"完全相同地","example":"Both switches are identically wired.","exampleCN":"两个开关的接线完全相同。"}],"latinEntries":[{"word":"idem","structure":"Latin pronoun and adjective","meaning":"the same","meaningCN":"同一个；相同的"},{"word":"identitas","structure":"ident- (same) + -itas (state noun)","meaning":"sameness, oneness","meaningCN":"相同；同一性（中世纪拉丁语）"},{"word":"identicus","structure":"ident- + -icus (adjective)","meaning":"of the same kind, identical","meaningCN":"同类的；完全相同的（中世纪拉丁语）"}]}},{"word":"ideology","ipa_uk":"/ˌaɪdiˈɒlədʒi/","ipa_us":"/ˌaɪdiˈɑːlədʒi/","definition_zh":"意识形态；观念体系；思想体系；（贬义）空想的教条","definition_en":"a systematic set of ideas and beliefs through which a group interprets the world and justifies its actions","core_image":"把散落的想法收进一张图，排成能解释整个世界的骨架","scene":"桌上摊着一份宣言，第一页写着几条原则，后面所有条款都向它对齐。 The party's manifesto opened with a page of principles, and every later policy had to fit that ideology.","sceneCN":"这里 ideology 是「政治意识形态」（第 1 个义项：解释并规范社会的一套系统观念）；句意：该党的宣言以一页原则开篇，后来的每项政策都必须符合这套意识形态。","pos":[{"tag":"n.","zh":"意识形态；观念体系；思想体系"},{"tag":"n.","zh":"（贬义）空想的理论；脱离实际的教条"}],"collocations":[{"phrase":"political ideology","zh":"政治意识形态"},{"phrase":"the dominant ideology","zh":"占主导地位的意识形态"},{"phrase":"ideological purity","zh":"意识形态上的纯洁性"},{"phrase":"the ideology of a movement","zh":"一场运动的思想体系"},{"phrase":"embrace an ideology","zh":"接受一套意识形态"},{"phrase":"corporate ideology","zh":"企业意识形态；企业文化纲领"}],"forms":[{"label":"名词复数（辅音字母加 y 结尾，变 y 为 i 加 -es）","form":"ideologies"}],"derivatives":[{"word":"ideological","pos":"adj.","zh":"意识形态的；思想体系的"},{"word":"ideologically","pos":"adv.","zh":"从意识形态角度；在观念上"},{"word":"ideologue","pos":"n.","zh":"意识形态鼓吹者；理论空谈家"},{"word":"ideologist","pos":"n.","zh":"思想体系研究者；观念学家"}],"senses":[{"no":"01","title":"Political ideology: a map for society","titleCN":"政治意识形态：解释社会的一张图","definition":"a connected set of political ideas that explains how a society should be ordered and what its institutions should aim at","definitionCN":"一套彼此关联的政治观念，解释社会应如何安排、制度应追求什么","example":"The two parties differ less in policy than in ideology.","exampleCN":"两党的差别不在具体政策，而在意识形态。","why":"Ideology began as a 'science of ideas' and later came to mean the system through which a group reads the world. A political ideology is that system applied to the ordering of society.","whyCN":"ideology 起初意为“观念的科学”，后来指一个群体借以解读世界的体系。政治意识形态就是把这套体系用于社会安排。"},{"no":"02","title":"Belief system of a group","titleCN":"群体的信念体系","definition":"the shared body of assumptions and values by which any group, not only a party, makes sense of its world","definitionCN":"任何群体（不只是政党）借以理解自身处境的共同预设与价值","example":"The profession's ideology treats long hours as proof of commitment.","exampleCN":"这个行业的观念体系把长时间工作当作敬业的证明。","why":"Once ideology is a system of ideas rather than a party programme, every group that shares assumptions has one, including professions, clubs, and families.","whyCN":"一旦 ideology 指观念体系而非政党纲领，任何共享预设的群体都有了一套，包括行业、社团与家庭。"},{"no":"03","title":"Derogatory: a doctrine out of touch","titleCN":"贬义：脱离实际的教条","definition":"in a hostile use, a rigid set of ideas held regardless of evidence, or theory with no practical use","definitionCN":"在敌意用法中，指不顾证据的僵硬观念，或没有实际用途的空论","example":"Critics dismissed the reform as ideology dressed up as science.","exampleCN":"批评者把这项改革斥为披着科学外衣的教条。","why":"The word's scientific origin promised proof; when a system of ideas refuses proof, the same word becomes an accusation of blindness.","whyCN":"这个词的科学出身曾承诺证明；当一套观念拒绝证明时，同一个词就变成了“盲目”的指控。"},{"no":"04","title":"Original sense: the science of ideas","titleCN":"本义：观念的科学","definition":"the original sense coined in 1796, a philosophy of the mind that derives knowledge from the senses","definitionCN":"1796 年造出的本义，指从感官经验推导知识的意识哲学","example":"The French philosopher called his project a science of ideas, set against metaphysics.","exampleCN":"那位法国哲学家把自己的工作称为“观念的科学”，与形而上学相对。","why":"Destutt de Tracy joined Greek idea 'form, look' to -logy 'study of' to name a new discipline. The literal meaning is a study of ideas, not a set of beliefs.","whyCN":"德斯蒂·德·特拉西把希腊语 idea“形相、外观”与 -logy“学科”组合，命名一门新学问。字面义是“对观念的研究”，而不是一套信念。"},{"no":"05","title":"Hidden framework behind neutral practice","titleCN":"隐含的价值预设","definition":"the unstated assumptions built into a practice, technology, or institution that looks neutral","definitionCN":"被嵌进某种看似中立的做法、技术或制度中的未言明预设","example":"The claim that data speak for themselves is itself an ideology.","exampleCN":"“数据自己会说话”这一说法本身就是一种意识形态。","why":"A map is most powerful when it looks like the territory. The same system of ideas becomes ideology when its assumptions stop being noticed.","whyCN":"一张地图最有力的时候，是它看起来像地面本身。当一套观念的预设不再被人注意到，它就成了意识形态。"},{"no":"06","title":"Corporate ideology: values as a script","titleCN":"企业意识形态：价值变成话术","definition":"the set of values and slogans through which a company explains itself and asks its staff to behave","definitionCN":"一个公司借以解释自身并要求员工照此行事的一套价值与口号","example":"The company's ideology praises speed and quietly punishes caution.","exampleCN":"这家公司的观念体系赞美速度，却在暗中惩罚谨慎。","why":"When a set of beliefs is used to organise a workplace, the political map becomes an internal one: it marks what counts as a good employee.","whyCN":"当一套信念被用来组织工作场所，政治地图就变成了内部地图：它标出什么样的人才算好员工。"},{"no":"07","title":"Religious or moral system","titleCN":"宗教或道德观念体系","definition":"a religious or moral framework that explains suffering, duty, and the proper order of life","definitionCN":"解释苦难、义务与生活应有秩序的一套宗教或道德框架","example":"The movement combined a strict moral ideology with practical charity.","exampleCN":"这场运动把严格的道德观念体系与实际慈善结合在一起。","why":"The same architecture of ideas can hold gods instead of parties. Whenever a group explains why the world is as it is, it is drawing this kind of map.","whyCN":"同一套观念架构也可以装神明而非政党。只要一个群体解释世界为何如此，它就在画这类地图。"},{"no":"08","title":"The -ism label: a political programme","titleCN":"以“主义”命名的政治纲领","definition":"a named political programme such as socialism, liberalism, or fascism, treated as a single package","definitionCN":"以社会主义、自由主义、法西斯主义等命名的成套政治纲领","example":"By 1918 the word was used of socialism and communism themselves.","exampleCN":"到 1918 年，这个词已被直接用来指社会主义与共产主义。","why":"English usage from 1907 first tied the term to socialist and communist writing; from 1918 the ideas and the movements merged into one label.","whyCN":"英语用法从 1907 年起先把这个词与社会主义、共产主义写作绑在一起；从 1918 年起，观念与运动合并成了同一个标签。"},{"no":"09","title":"Dogmatic purity: ideas that cannot bend","titleCN":"教条化的纯粹：不肯弯曲的观念","definition":"the state in which a set of ideas is defended so strictly that evidence and compromise are treated as betrayal","definitionCN":"一套观念被捍卫得极其严格，以致证据与妥协都被视为背叛的状态","example":"The purge was justified in the name of ideological purity.","exampleCN":"那场清洗以意识形态纯洁性的名义被正当化。","why":"A map that refuses correction stops being a guide and becomes a test of loyalty. Here ideology turns from a system of ideas into a border.","whyCN":"一张拒绝修正的地图不再是指南，而变成了忠诚的检验。此时意识形态从观念体系变成了一条边界。"}],"etymology":{"intro":{"en":"Ideology is a modern coinage from two Greek pieces, idea 'form, look' and -logy 'study of'. It began as a name for a science and ended as a name for the beliefs people cannot examine. Dates are approximate.","cn":"ideology 是用两个希腊成分造的现代新词：idea“形相、外观”与 -logy“学科”。它起初是一门科学的名称，最后成了人们无法审视的信念的名称。年代为大致估计。"},"items":[{"era":"1796","en":"Coined as French idéologie, 'science of ideas', by Destutt de Tracy, for a philosophy of the mind that derives knowledge from the senses, as opposed to metaphysics.","cn":"由德斯蒂·德·特拉西造出法语 idéologie，意为“观念的科学”，指一种从感官经验推导知识的意识哲学，与形而上学相对。"},{"era":"GREEK idea + -logia","en":"The coinage joins idéo- 'of ideas', from Greek idea 'form, the look of a thing', with -logie, from Greek -logia 'a speaking, discourse, science', from legein 'to speak'.","cn":"这个新词把 idéo-“观念的”、来自希腊语 idea“形相、事物的外观”，与 -logie 结合，后者来自希腊语 -logia“言说、论述、学科”，再上溯 legein“说”。"},{"era":"GREEK idein","en":"Greek idea comes from idein 'to see', from PIE *weid- 'to see'. An idea was first a visible form, then a form held in the mind.","cn":"希腊语 idea 来自 idein“看见”，再上溯原始印欧语 *weid-“看见”。观念最初是可见的形相，后来成为心中的形相。"},{"era":"1801–1815","en":"Destutt published his Eléments d'idéologie in these years, fixing the word in its learned, neutral sense.","cn":"德斯蒂在这一时期出版《观念学原理》，把这个词固定在学术性的中立义上。"},{"era":"1907 · 1918","en":"The sense 'systematic set of ideas, doctrines through which the world is interpreted' appears in English by 1907, earliest in socialist and communist writing; from 1918 it names socialism and communism themselves, and later fascism.","cn":"“借以解释世界的系统观念与学说”这一义项在 1907 年前后进入英语，最早见于社会主义与共产主义写作；从 1918 年起，它直接指社会主义与共产主义本身，后来又指法西斯主义。"},{"era":"MODERN ENGLISH","en":"The term became omnipresent only after Marx's The German Ideology and Mannheim's Ideology and Utopia appeared between the world wars. Ideological is recorded from 1797, and ideologue names the person who lives inside the map.","cn":"这个词要到马克思《德意志意识形态》与曼海姆《意识形态与乌托邦》在两次世界大战之间问世之后才无处不在。ideological 从 1797 年起有记录，ideologue 则指住在这张地图里的人。"}]},"similar":{"note":{"en":"The first group separates idea, ideal, the adjective, and the person from ideology; the second group compares other names for sets of beliefs.","cn":"第一组把 idea、ideal、形容词与“人”同 ideology 分开；第二组比较其他表示“信念集合”的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"idea","ipa":"/aɪˈdɪə/","tag":"single thought","definition":"a thought, concept, or plan in the mind. It is one unit; ideology is the system that arranges many such units into a world picture.","definitionCN":"心中的一个想法、概念或计划。它是一个单位；ideology 则是把许多这样的单位排成世界图景的体系。"},{"word":"ideal","ipa":"/aɪˈdiːəl/","tag":"perfect standard","definition":"a standard of perfection, or the best possible form of something. An ideal is what a belief aims at; an ideology is the whole frame that contains both the aim and its justification.","definitionCN":"完美的标准，或某物可能达到的最佳形态。ideal 是信念所指向的目标；ideology 是同时容纳目标与理由的整个框架。"},{"word":"ideological","ipa":"/ˌaɪdiəˈlɒdʒɪkl/","tag":"adjective","definition":"relating to an ideology. It describes how something is driven by a set of ideas, as in an ideological dispute, rather than naming the set itself.","definitionCN":"与意识形态有关的。它描述某事如何由一套观念驱动，如意识形态争论，而不是命名这套观念本身。"},{"word":"ideologue","ipa":"/ˌaɪdiˈɒləɡ/","tag":"person","definition":"a person who holds a doctrine rigidly and defends it. It is usually hostile: the ideologue is the one who will not look outside the map.","definitionCN":"僵硬坚持并捍卫一套学说的人。它通常带敌意：意识形态者就是不肯往地图外面看的那个人。"}]},{"heading":"NEAR MEANING","entries":[{"word":"doctrine","ipa":"/ˈdɒktrɪn/","tag":"taught principles","definition":"a set of principles taught or officially held, often by a church or a state. Doctrine stresses authority and instruction; ideology stresses the whole way of seeing the world.","definitionCN":"被教授或官方持有的一套原则，常属教会或国家。doctrine 强调权威与教导；ideology 强调整套看世界的方式。"},{"word":"belief system","ipa":"/bɪˈliːf ˌsɪstəm/","tag":"neutral plain term","definition":"the connected beliefs a person or group holds. It is the plain, neutral phrase; ideology is the academic and often political word for the same architecture.","definitionCN":"个人或群体所持的相互关联的信念。它是朴素中性的说法；ideology 是同一架构的学术用词，且常带政治色彩。"},{"word":"worldview","ipa":"/ˈwɜːldvjuː/","tag":"the whole outlook","definition":"the overall way a person or culture sees existence. A worldview may be private and philosophical; an ideology is more organised, shared, and acted upon.","definitionCN":"个人或文化看待存在的整体方式。worldview 可以是私人的、哲学的；ideology 则更有组织、更共享、更被付诸行动。"},{"word":"dogma","ipa":"/ˈdɒɡmə/","tag":"unquestionable teaching","definition":"a principle laid down as unquestionably true. Dogma is one brick; ideology is the building, and calling it dogma is already the hostile sense.","definitionCN":"被规定为不容置疑的原则。dogma 是一块砖；ideology 是整座建筑，而把它称为 dogma 时，已经用上了贬义。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: Greek idea 'form, look' plus -logy 'study of', and the family ideological / ideologue / ideologist.","cn":"只用真实成分与真实同族词：希腊语 idea“形相、外观”加 -logy“学科”，以及 ideological／ideologue／ideologist 词族。"},"normal":[{"en":"idea means 'form or look' and -logy means 'study of'. Ideology was literally the study of ideas before it became the ideas themselves.","cn":"idea 表示“形相或外观”，-logy 表示“对……的研究”。ideology 字面上是“对观念的研究”，后来才变成观念本身。"},{"en":"The -logy ending also builds biology, psychology and theology, so ideology belongs to the same family of 'named fields of study'.","cn":"-logy 也构成 biology、psychology、theology，所以 ideology 属于同一类“被命名的学问领域”。"},{"en":"Ideological is the adjective, ideologue is the person, and ideologist is the person who studies the system.","cn":"ideological 是形容词，ideologue 是信奉者，ideologist 是研究这套体系的人。"},{"en":"Do not confuse ideal with idea: an ideal is the perfect standard, an idea is one thought, and an ideology is the frame that holds many thoughts together.","cn":"不要把 ideal 与 idea 混同：ideal 是完美标准，idea 是一个想法，ideology 是把许多想法收在一起的那个框架。"},{"en":"The word was coined in 1796 as a neutral science, and only after 1907 did it become the name of political belief systems.","cn":"这个词 1796 年被造出时是一门中立科学，直到 1907 年之后才成为政治信念体系的名称。"}],"abstract":[{"en":"Picture a stack of loose notes. Ideology is the moment someone draws a frame around them and says: these belong together and explain everything.","cn":"想象一叠散乱的笔记。ideology 就是有人给它们画上一个框，并说：这些属于同一体，能解释一切的那一刻。"},{"en":"The frame can hold a party, a profession, a company, or a church. Whatever it holds, its power comes from being mistaken for the world itself.","cn":"这个框可以装一个政党、一个行业、一家公司或一座教堂。不论装什么，它的力量都来自被误当成世界本身。"},{"en":"A frame that can be revised stays a map. A frame that cannot be revised becomes a border, and crossing it is treated as betrayal.","cn":"可以修改的框仍是地图；不能修改的框变成边界，越过它就被当成背叛。"}]},"examples":[{"en":"The textbook presents its own assumptions as neutral method, which is how ideology usually hides.","cn":"这本教科书把自己的预设呈现为中立的方法，意识形态通常就是这样藏起来的。"},{"en":"She studied how colonial ideology shaped the maps children were given.","cn":"她研究殖民意识形态如何塑造发给孩子们的地图。"},{"en":"Calling every conviction an ideology makes it impossible to argue with any of them.","cn":"把一切信念都称为意识形态，会让人无法与其中任何一种辩论。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“爱迪欧乐吉”——爱迪欧（ideo）把一堆想法收进一个乐（logy）高音喇叭，对着全世界广播 → ideology 意识形态、观念体系","word":"ideology"},"root":"源自希腊语 idea“形相、外观”+ -logia“言说、学科”，1796 年由法语 idéologie 造出，核心是“把零散观念收成一套能解释世界的体系”。","sensesIntro":{"en":"Nine senses of ideology, all grown from one structure: scattered ideas are gathered into a frame, and that frame is then used to read the world, justify action, or shut out doubt.","cn":"ideology 的九个义项都从同一个结构长出来：零散的想法被收进一个框架，这个框架随后被用来解读世界、为行动辩护，或把怀疑关在门外。"},"semanticMap":{"core":{"en":"CORE IMAGE: a frame drawn around many ideas so that they explain a whole world.","cn":"核心意象：给许多想法画上一个框，使它们能解释整个世界。"},"chain":["MANY IDEAS","A FRAME DRAWN","A SYSTEM OF BELIEFS","A WAY TO READ THE WORLD","A JUSTIFICATION FOR ACTION","A BORDER THAT CANNOT BEND"],"branches":[{"senses":"01 · 08","en":"POLITICS: the frame becomes a party programme, and the programme acquires an -ism label.","cn":"政治：框架变成政党纲领，纲领再获得一个“主义”标签。"},{"senses":"02 · 06 · 07","en":"GROUP LIFE: professions, companies, and religions each read their world through their own frame.","cn":"群体生活：行业、公司与宗教各自用自己的一套框架解读世界。"},{"senses":"03 · 09","en":"RIGIDITY: when the frame refuses evidence and compromise, it turns from doctrine into an accusation and then into a border.","cn":"僵硬：当框架拒绝证据与妥协，它就从学说变成指控，再变成边界。"},{"senses":"04","en":"ORIGIN: the coined sense was a neutral study of ideas, not a set of beliefs.","cn":"起源：造词时的义项是对观念的中立研究，而不是一套信念。"},{"senses":"05","en":"HIDDEN FRAME: the system works best when its assumptions pass unnoticed, like a map mistaken for ground.","cn":"隐藏的框架：当预设不被人注意时，这套体系最有效，就像地图被当成地面。"}]},"affixes":{"intro":{"en":"Ideology is a modern compound of two Greek elements: idea 'form, look' and -logy 'study or discourse'. English adds -ical, -ly, -logue, and -ist to build the rest of the family.","cn":"ideology 是由两个希腊成分构成的现代复合词：idea“形相、外观”与 -logy“研究或论述”。英语再加上 -ical、-ly、-logue、-ist 构成整个词族。"},"latinIntro":{"en":"Latin idea was borrowed from Greek idea 'form, look', and Medieval Latin -logia came from Greek -logia, from logos 'word, speech'. The elements are Greek, but they reached modern European languages through Latin and French.","cn":"拉丁语 idea 借自希腊语 idea“形相、外观”，中世纪拉丁语 -logia 来自希腊语 -logia，再上溯 logos“词、言说”。成分是希腊的，但它们是经拉丁语与法语进入现代欧洲语言的。"},"items":[{"word":"ideology","structure":"ideo- (of ideas) + -logy (study, discourse)","meaning":"a system of ideas through which the world is interpreted","meaningCN":"解释世界的观念体系（ideo- 观念的 + -logy 学科）","example":"The film examines the ideology behind urban planning.","exampleCN":"这部影片审视城市规划背后的意识形态。"},{"word":"ideologies","structure":"ideology + -es (plural)","meaning":"more than one system of ideas","meaningCN":"多套观念体系（辅音加 y 结尾变 y 为 i 加 -es）","example":"Competing ideologies shaped the new constitution.","exampleCN":"彼此竞争的各种意识形态塑造了新宪法。"},{"word":"ideological","structure":"ideolog- + -ical (adjective)","meaning":"driven by or belonging to an ideology","meaningCN":"意识形态的；由观念体系驱动的（-ical 构成形容词）","example":"The split was personal before it became ideological.","exampleCN":"这场分裂先是人际的，后来才变成意识形态的。"},{"word":"ideologically","structure":"ideological + -ly (adverb)","meaning":"from the standpoint of an ideology","meaningCN":"从意识形态立场上（-ly 构成副词）","example":"The two proposals are ideologically opposed but practically similar.","exampleCN":"这两项提案在观念上对立，在实际操作上却相似。"},{"word":"ideologue","structure":"ideo- + -logue (one who speaks)","meaning":"a rigid defender of a doctrine","meaningCN":"教条捍卫者；意识形态者（-logue 表示说话者）","example":"He was a party ideologue who never met a compromise he liked.","exampleCN":"他是个党的意识形态者，从不喜欢任何妥协。"},{"word":"ideologist","structure":"ideolog- + -ist (person)","meaning":"one who studies or formulates ideologies","meaningCN":"研究或制定思想体系的人（-ist 表示人）","example":"The regime relied on ideologists to rewrite the textbooks.","exampleCN":"该政权依靠意识形态专家改写教科书。"},{"word":"idea","structure":"Greek idea 'form, look', from idein 'to see'","meaning":"a thought or concept in the mind","meaningCN":"心中的想法或概念（希腊语“形相、外观”）","example":"The idea came to her on the bus.","exampleCN":"这个想法是她在公交车上想到的。"},{"word":"ideal","structure":"idea + -al (adjective and noun)","meaning":"a standard of perfection","meaningCN":"理想；完美标准（-al 构成形容词与名词）","example":"The plan was an ideal rather than a schedule.","exampleCN":"这个方案更像一种理想，而不是一份日程。"},{"word":"idealize","structure":"ideal + -ize (verb)","meaning":"to represent something as perfect","meaningCN":"把某物理想化（-ize 构成动词）","example":"The memoir idealizes a childhood it barely describes.","exampleCN":"这本回忆录把它几乎没怎么描述的童年理想化了。"},{"word":"biology","structure":"bio- (life) + -logy (study)","meaning":"the study of living things","meaningCN":"生物学（bio- 生命 + -logy 学科）","example":"She took biology as her second subject.","exampleCN":"她把生物学选为第二专业。"},{"word":"psychology","structure":"psycho- (mind) + -logy (study)","meaning":"the study of the mind and behaviour","meaningCN":"心理学（psycho- 心灵 + -logy 学科）","example":"Psychology was once taught as part of philosophy.","exampleCN":"心理学曾作为哲学的一部分被教授。"},{"word":"theology","structure":"theo- (god) + -logy (study)","meaning":"the study of religion and divine things","meaningCN":"神学（theo- 神 + -logy 学科）","example":"He studied theology before turning to law.","exampleCN":"他先学神学，后来转学法律。"}],"latinEntries":[{"word":"idea","structure":"Greek idea 'form, look' from idein 'to see'","meaning":"a form, a visible shape; a concept in the mind","meaningCN":"形相、可见的形状；心中的概念（拉丁语借自希腊语）"},{"word":"-logia","structure":"Greek -logia, from logos 'word, speech'","meaning":"a speaking, discourse, treatise, science","meaningCN":"言说、论述、论著、学科（中世纪拉丁语 -logia）"},{"word":"logos","structure":"Greek logos, from legein 'to speak, gather'","meaning":"word, speech, reason","meaningCN":"词、言说、理性"}]}},{"word":"illustrate","ipa_uk":"/ɪˈlʌstreɪt/","ipa_us":"/ˈɪləstreɪt/","definition_zh":"说明；阐明；举例说明；为（书、文章）加插图","definition_en":"to make something clear by examples or pictures, or to add pictures to a text","core_image":"一束光打过去，把原本暗着的角落照亮","scene":"屏幕上放着一张示意图，一条曲线照亮了整套论证。 The lecturer put a diagram on the screen and used it to illustrate the whole argument about stress with a single curve.","sceneCN":"这里 illustrate 是「用图说明、图解」（第 4 个义项：用图表或示意图把道理呈现出来）；句意：讲师把一张示意图放上屏幕，用一条曲线阐明了关于压力的整套论证。","pos":[{"tag":"v.","zh":"说明；阐明；举例说明"},{"tag":"v.","zh":"给（书、文章）加插图"}],"collocations":[{"phrase":"illustrate a point","zh":"说明一个观点"},{"phrase":"illustrate the problem","zh":"说明问题所在"},{"phrase":"illustrate with examples","zh":"用例子说明"},{"phrase":"a well-illustrated book","zh":"插图精良的书"},{"phrase":"illustrate how something works","zh":"说明某物如何运作"},{"phrase":"be illustrated by","zh":"由……来说明"}],"forms":[{"label":"第三人称单数","form":"illustrates"},{"label":"过去式","form":"illustrated"},{"label":"过去分词","form":"illustrated"},{"label":"现在分词","form":"illustrating"}],"derivatives":[{"word":"illustration","pos":"n.","zh":"插图；图解；例证"},{"word":"illustrative","pos":"adj.","zh":"说明性的；用作例证的"},{"word":"illustrator","pos":"n.","zh":"插画家；插图绘制者"},{"word":"illustrated","pos":"adj.","zh":"配有插图的"},{"word":"illustratively","pos":"adv.","zh":"作为例证地；说明性地"}],"senses":[{"no":"01","title":"Add pictures to a text","titleCN":"给文字配图","definition":"to add drawings, photographs, or diagrams to a book, article, or talk","definitionCN":"为书籍、文章或讲话加入图画、照片或示意图","example":"The publisher illustrated the field guide with forty watercolours.","exampleCN":"出版社为这本野外指南配了四十幅水彩图。","why":"The picture sense is recorded from the 1630s. A drawing is light on the page: it makes a described thing visible instead of merely named.","whyCN":"配图义从 17 世纪 30 年代起有记录。图画就是落在纸上的光：它让被描述之物变得可见，而不只是被命名。"},{"no":"02","title":"Explain by examples","titleCN":"举例说明","definition":"to make an idea clear by giving examples that show what it means","definitionCN":"通过给出能显示其含义的例子，使一个观念变得清楚","example":"She illustrated the rule with three sentences from her own students.","exampleCN":"她用自己学生的三个句子说明了这条规则。","why":"The sense 'educate by means of examples' appears in the 1610s. An example is a small bright instance that lets the listener see the general rule.","whyCN":"“用例子来教导”这一义项出现在 17 世纪 10 年代。例子就是一个小的亮斑，让听者看见那条通则。"},{"no":"03","title":"Serve as an example of","titleCN":"本身即是例证","definition":"of a case, event, or object, to be an instance that proves or demonstrates a general claim","definitionCN":"指某个案例、事件或物件本身即是证明或展示某一通则的实例","example":"The collapse of the bridge illustrates the cost of deferred repairs.","exampleCN":"那座桥的垮塌说明了拖延维修的代价。","why":"Here the example does not accompany the claim; it is the claim made visible. The case and the principle become the same thing seen at two sizes.","whyCN":"这里的例子不是陪着论点出现，而是论点本身变得可见。个案与原理成为同一件事在两种尺度上的显现。"},{"no":"04","title":"Explain with a diagram","titleCN":"用图表图解","definition":"to present a relation, process, or quantity in a diagram, chart, or graph","definitionCN":"用示意图、图表或曲线呈现某种关系、过程或数量","example":"The lecturer illustrated the pressure curve on a single screen.","exampleCN":"讲师在一块屏幕上图解了压力曲线。","why":"A diagram is light thrown on a relation: what was a sentence about causes becomes a visible line that rises and falls.","whyCN":"示意图就是打在关系上的一束光：原本用句子讲因果，现在变成一条可见的、有起有落的线。"},{"no":"05","title":"Demonstrate a process live","titleCN":"现场演示过程","definition":"to show how something is done by performing it in front of others","definitionCN":"在他人面前实际操作，以展示某事如何完成","example":"The technician illustrated the repair step by step on a spare unit.","exampleCN":"技师在一台备用机上一一步步演示了维修过程。","why":"The light is now on the action itself. Instead of describing the steps, the demonstrator makes each step visible as it happens.","whyCN":"此时光落在动作本身。演示者不再描述步骤，而是让每一步在发生时就被看见。"},{"no":"06","title":"Make an abstract idea visible","titleCN":"把抽象观念形象化","definition":"to give a concrete, visible form to something abstract, such as a feeling or a value","definitionCN":"给抽象之物（如情感或价值）一个具体、可见的形状","example":"The mural illustrates hope as a window left open at night.","exampleCN":"这幅壁画把希望画成夜里一扇开着的窗。","why":"This is the oldest metaphor of the word: illustrare meant to light up. An abstract idea that has been illustrated is one you can finally see.","whyCN":"这是这个词最古老的比喻：illustrare 意为照亮。被形象化的抽象观念，就是终于能被看见的观念。"},{"no":"07","title":"Archaic: to light up","titleCN":"古义：照亮","definition":"in older usage, to shed light on a place or thing, literally or spiritually","definitionCN":"在较早用法中，指把某地或某物照亮，字面或精神上皆可","example":"The old hymn asks that grace illustrate the dark chamber.","exampleCN":"那首旧赞美诗祈求恩典照亮黑暗的内室。","why":"The verb entered English in the 1520s meaning 'light up, shed light on'. The physical sense came first and the explanatory senses are its heirs.","whyCN":"这个动词在 16 世纪 20 年代进入英语，意为“照亮、给光”。物理义先出现，各种解释义都是它的后裔。"},{"no":"08","title":"Archaic: to lend distinction","titleCN":"古义：使增光、使显赫","definition":"in older usage, to bring honour or fame to a person, family, or place","definitionCN":"在较早用法中，指给某人、家族或地方带来荣誉或名望","example":"The family was illustrated by three generations of judges.","exampleCN":"这个家族因三代法官而增光。","why":"Latin illustrare also meant 'adorn, render distinguished'. A person who is illustrated is one on whom light has been cast, so that others notice the honour.","whyCN":"拉丁语 illustrare 也意为“装饰、使显赫”。被“照亮”的人，就是有光打在他身上、让别人看见那份荣誉的人。"}],"etymology":{"intro":{"en":"Illustrate is built on Latin lux, 'light'. To illustrate is to throw light on something, first literally, then by pictures, examples, and diagrams. Dates are approximate.","cn":"illustrate 建立在拉丁语 lux“光”上。illustrate 就是把光照到某物上，先字面照亮，后来用图画、例子与示意图照亮。年代为大致估计。"},"items":[{"era":"1520s","en":"The verb is first recorded meaning 'light up, shed light on', partly a back-formation from illustration and partly from Latin illustratus, the past participle of illustrare.","cn":"这个动词最早记录于 16 世纪 20 年代，意为“照亮、给光”，一部分由 illustration 逆构而成，一部分直接来自 illustrare 的过去分词 illustratus。"},{"era":"1610s","en":"The sense 'educate by means of examples' appears, which turns the light into instruction.","cn":"出现“用例子来教导”的义项，把光变成了教导。"},{"era":"1630s","en":"The sense 'provide pictures to explain or decorate' is recorded, the sense closest to the modern book illustrator.","cn":"记录到“提供图画以解释或装饰”的义项，这是最接近现代书籍插画师的义项。"},{"era":"LATIN illustrare","en":"Latin illustrare meant 'light up, make light, illuminate', and figuratively 'make clear, disclose, explain; adorn, render distinguished'. It is in- 'in' plus lustrare 'make bright, illuminate'.","cn":"拉丁语 illustrare 意为“照亮、使有光、照明”，比喻义为“使清楚、揭示、解释；装饰、使显赫”。它由 in-“在内”加 lustrare“使明亮、照明”构成。"},{"era":"PIE *leuk-","en":"Lustrare goes back to a suffixed form of PIE *leuk- 'light, brightness', the same root that gives light, lucid, and translucent.","cn":"lustrare 可追溯到原始印欧语 *leuk-“光、明亮”的带后缀形式，同一词根也给出 light、lucid、translucent。"},{"era":"c. 1400 · MODERN","en":"The noun illustration is recorded from about 1400 as 'a shining', then 'a manifestation' and 'spiritual illumination'; the mental sense 'making clear in the mind' is from the 1580s, and 'an illustrative picture' from 1816. Illustrator meant 'one who enlightens' in the 1590s and 'one who draws pictures' by the 1680s.","cn":"名词 illustration 约从 1400 年起有记录，先是“发光”，再是“显现”与“精神启示”；“在头脑中使清楚”的心智义从 16 世纪 80 年代起，“插图”义从 1816 年起。illustrator 在 16 世纪 90 年代指“启发者”，到 17 世纪 80 年代指“画插图的人”。"}]},"similar":{"note":{"en":"The first group separates the picture, the adjective, and the person from the verb; the second group compares other verbs of making something clear.","cn":"第一组把插图、形容词与“人”同动词分开；第二组比较其他表示“使清楚”的动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"illustration","ipa":"/ˌɪləˈstreɪʃn/","tag":"noun: the picture or act","definition":"a drawing in a book, or the act of making something clear. It is the noun of illustrate and can name either the picture or the explaining.","definitionCN":"书中的图画，或使某物清楚的动作。它是 illustrate 的名词，既可指图画，也可指解释。"},{"word":"illustrative","ipa":"/ɪˈlʌstrətɪv/","tag":"adjective","definition":"serving to explain or demonstrate. It describes the function of an example, not the act of drawing, and is common in the phrase illustrative of.","definitionCN":"用于说明或证明的。它描述例子所起的作用，而不是绘画动作，常见于 illustrative of 这一搭配。"},{"word":"illustrator","ipa":"/ˈɪləstreɪtə(r)/","tag":"person","definition":"a person who draws pictures for books or magazines. It names the maker; illustrate names the making.","definitionCN":"为书籍或杂志画插图的人。它命名制作者；illustrate 命名制作动作。"}]},{"heading":"NEAR MEANING","entries":[{"word":"demonstrate","ipa":"/ˈdemənstreɪt/","tag":"show by doing","definition":"to show how something works by doing it or by evidence. Demonstrate proves; illustrate clarifies, and may use a picture rather than a proof.","definitionCN":"通过实际操作或证据展示某物如何运作。demonstrate 重在证明；illustrate 重在说明，且可以用图画而非证明。"},{"word":"explain","ipa":"/ɪkˈspleɪn/","tag":"make understandable","definition":"to make something understandable by giving reasons or details. Explain works in words; illustrate adds a visible case or image.","definitionCN":"通过给出理由或细节使某物可理解。explain 用言辞工作；illustrate 则再加上一个可见的案例或图像。"},{"word":"depict","ipa":"/dɪˈpɪkt/","tag":"represent in image","definition":"to represent something in a picture, painting, or words. Depict shows what something looks like; illustrate shows what something means.","definitionCN":"在图画、绘画或文字中表现某物。depict 展示某物看起来怎样；illustrate 展示某物意味着什么。"},{"word":"exemplify","ipa":"/ɪɡˈzemplɪfaɪ/","tag":"be an instance","definition":"to be a typical example of something, or to give an example. It stresses the example itself rather than the light thrown on the idea.","definitionCN":"成为某物的典型例子，或举出例子。它强调例子本身，而不是打在观念上的那束光。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts and real relatives: Latin lustrare 'make bright', the noun illustration, the adjective illustrative, and the person illustrator.","cn":"只用真实成分与真实同族词：拉丁语 lustrare“使明亮”、名词 illustration、形容词 illustrative，以及表示人的 illustrator。"},"normal":[{"en":"The core is Latin lux, 'light'. To illustrate is to put light on something so that it can be seen.","cn":"核心是拉丁语 lux“光”。illustrate 就是把光放到某物上，使它能够被看见。"},{"en":"Illustration is the picture or the act, illustrative means 'serving to clarify', and an illustrator is the person who draws.","cn":"illustration 是图画或行为，illustrative 意为“起说明作用的”，illustrator 是画图的人。"},{"en":"The -or ending marks the doer, as in creator and translator; the -ive ending marks a quality or function, as in instructive.","cn":"-or 词尾标记施动者，如 creator、translator；-ive 词尾标记性质或功能，如 instructive。"},{"en":"The verb entered English meaning 'light up' in the 1520s; pictures and examples are later ways of casting the same light.","cn":"这个动词在 16 世纪 20 年代以“照亮”之义进入英语；图画与例子只是后来投下同一束光的方式。"},{"en":"An illustrated book is not a book about light: it is a book with pictures that make the text visible.","cn":"an illustrated book 不是关于光的书：它是配有图画、让文字变得可见的书。"}],"abstract":[{"en":"Picture a dark room with one lamp on a cord. Whatever the lamp is moved to becomes clear; whatever it leaves stays in shadow.","cn":"想象一间暗室，只有一盏吊灯。灯移到哪里，哪里就清楚；灯离开的地方仍留在阴影里。"},{"en":"The lamp can be a drawing, an example, a diagram, or a live demonstration. The tool changes, the gesture does not.","cn":"这盏灯可以是一幅画、一个例子、一张图，或一次现场演示。工具变了，动作没有变。"},{"en":"There is a difference between lighting a thing and proving it. Illustration makes a claim visible; it does not by itself make it true.","cn":"照亮一物与证明一物并不相同。说明让一个主张变得可见，但它本身并不使主张成真。"}]},"examples":[{"en":"The chart illustrates why the two curves cannot cross.","cn":"这张图说明了为什么两条曲线不可能相交。"},{"en":"He illustrated the argument with a case from his own clinic.","cn":"他用自己诊所里的一个病例说明了这个论点。"},{"en":"Her illustrated guide to the shore has sold out twice.","cn":"她这本配图的海岸指南已经两次售罄。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“一拉斯特”——把幕布一拉，斯特（stre）先生打着灯上台，把每个要点都照亮 → illustrate 说明、图解","word":"illustrate"},"root":"源自拉丁语 illustrare“照亮、使明亮”，由 in-“在内”+ lustrare“使明亮”构成，核心是“把光照过去，让原本看不清的变得可见”。","sensesIntro":{"en":"Eight senses of illustrate, all grown from one beam of light: first a room is lit, then a text is given pictures, then an idea is given examples, diagrams, and visible form.","cn":"illustrate 的八个义项都从同一束光长出来：先照亮一间屋子，再给文字配上图画，然后给观念配上例子、示意图与可见的形状。"},"semanticMap":{"core":{"en":"CORE IMAGE: a beam of light thrown on what was dark and hard to see.","cn":"核心意象：一束光打向原本黑暗、难以看清之处。"},"chain":["A BEAM THROWN","THE DARK SPOT LIT","THE TEXT GIVEN PICTURES","THE RULE GIVEN EXAMPLES","THE RELATION DRAWN","THE IDEA MADE VISIBLE"],"branches":[{"senses":"01","en":"PICTURES: light takes the form of drawings and photographs attached to a text.","cn":"图画：光采取附在文字旁的素描与照片的形式。"},{"senses":"02 · 03","en":"EXAMPLES: a small bright instance shows the rule, and sometimes the instance is the proof.","cn":"例子：一个小的亮斑显示通则，有时这个实例本身就是证明。"},{"senses":"04 · 05","en":"DEMONSTRATION: the beam falls on a relation in a diagram, or on each step of a live process.","cn":"演示：光落在示意图中的一段关系上，或落在现场流程的每一步上。"},{"senses":"06","en":"VISIBLE FORM: an abstract idea is given a shape that can finally be seen.","cn":"可见的形状：抽象观念被赋予一个终于能被看见的形状。"},{"senses":"07 · 08","en":"OLD LIGHT: the oldest senses are literal lighting and the honour that light brings.","cn":"古老的光：最老的义项就是字面上的照明，以及光所带来的荣誉。"}]},"affixes":{"intro":{"en":"Illustrate comes from Latin illustrare, built on lustrare 'make bright', with the prefix in-. English adds -ion, -ive, -or, and -ed to make the rest of the family.","cn":"illustrate 来自拉丁语 illustrare，建立在 lustrare“使明亮”上，并带前缀 in-。英语加上 -ion、-ive、-or、-ed 构成整个词族。"},"latinIntro":{"en":"The Latin family is built on lustrare 'to make bright, illuminate', itself from a suffixed form of PIE *leuk- 'light'. Illustrare adds in- and means 'to light up, make clear'; illustris, 'bright, distinguished', is the adjective behind illustrious.","cn":"这一拉丁词族建立在 lustrare“使明亮、照明”上，后者来自原始印欧语 *leuk-“光”的带后缀形式。illustrare 加上 in-，意为“照亮、使清楚”；形容词 illustris“明亮的、显赫的”则是 illustrious 的来源。"},"items":[{"word":"illustrate","structure":"il- (in) + lustrare (make bright)","meaning":"to light up; to make clear by pictures or examples","meaningCN":"照亮；用图画或例子说明（il- 在内 + lustrare 使明亮）","example":"One graph illustrates the whole trend.","exampleCN":"一张图就说明了整个趋势。"},{"word":"illustration","structure":"illustrate + -ion (action or result noun)","meaning":"a picture in a text; the act of making clear","meaningCN":"插图；说明（-ion 构成行为或结果名词）","example":"The illustration shows the parts of the flower.","exampleCN":"这幅插图展示了花的各个部分。"},{"word":"illustrative","structure":"illustrat- + -ive (adjective)","meaning":"serving to explain or demonstrate","meaningCN":"说明性的；用作例证的（-ive 构成形容词）","example":"The case is illustrative of a wider failure.","exampleCN":"这个案例足以说明一种更普遍的失败。"},{"word":"illustrator","structure":"illustrate + -or (agent noun)","meaning":"a person who draws pictures for publications","meaningCN":"插画家（-or 表示施动者）","example":"The illustrator worked closely with the author.","exampleCN":"插画家与作者密切合作。"},{"word":"illustrated","structure":"illustrate + -ed (past participle)","meaning":"provided with pictures","meaningCN":"配有插图的（-ed 构成过去分词或形容词）","example":"She bought the illustrated edition for her nephew.","exampleCN":"她给侄子买了插图版。"},{"word":"illustrious","structure":"Latin illustris (bright, distinguished) + -ous","meaning":"famous and admired for great achievements","meaningCN":"显赫的；著名的（拉丁语 illustris“明亮的、显赫的”加 -ous）","example":"He came from an illustrious family of surgeons.","exampleCN":"他出身于一个显赫的外科医生家族。"},{"word":"illuminate","structure":"il- (in) + luminare (to light)","meaning":"to light up; to make clear","meaningCN":"照亮；阐明（同一“给光”意象的另一条拉丁路线）","example":"The manuscript was illuminated in gold and blue.","exampleCN":"这份手稿用金色和蓝色加以照明装饰。"},{"word":"elucidate","structure":"e- (out) + lucidus (clear, bright)","meaning":"to explain so that a matter becomes clear","meaningCN":"阐明；解释清楚（拉丁语 lucidus“明亮”）","example":"She elucidated the procedure in plain language.","exampleCN":"她用平实的语言把流程讲清楚了。"},{"word":"lucid","structure":"luc- (light) + -id (adjective)","meaning":"clear and easy to understand","meaningCN":"清晰易懂的（luc- 光 + -id 形容词）","example":"His lucid summary closed the meeting.","exampleCN":"他清晰的总结为会议收了尾。"}],"latinEntries":[{"word":"illustrare","structure":"in- (in) + lustrare (make bright)","meaning":"to light up, make bright; to make clear, disclose, explain; to adorn","meaningCN":"照亮、使明亮；使清楚、揭示、解释；装饰"},{"word":"lustrare","structure":"from a suffixed form of PIE *leuk- 'light, brightness'","meaning":"to make bright, illuminate","meaningCN":"使明亮；照明"},{"word":"illustris","structure":"in- + the root of lustrare","meaning":"bright, brilliant; distinguished","meaningCN":"明亮的、光辉的；显赫的"}]}}]);
